  LP.register({"format": "lpp", "contract": "2.0", "builtAt": "2026-11-24T17:06:54+00:00", "manifest": {"id": "pw", "contract": "2.0", "version": "1.0.0", "title": "UI Automation with Playwright", "tag": "Playwright · JS + Python", "short": "Playwright", "subtitle": "Playwright · JS + Python", "blurb": "End-to-end testing with Playwright in JavaScript and Python, from first test to CI.", "language": "en", "lessonRules": "relaxed", "labels": {"module": "Module"}, "levels": {"difficulty": ["Beginner", "Intermediate", "Advanced"], "question": ["Understand"]}, "variants": [{"id": "js", "label": "JavaScript"}, {"id": "py", "label": "Python"}], "plugins": [{"id": "labs-web", "version": "^1.0"}], "extensions": [], "exam": {"passMark": 65, "main": ["full", "quick"]}, "readiness": {"window": 3, "bands": {"ready": 80, "nearly": 65}}, "status": {"window": 6, "bands": {"strong": 85, "good": 70, "average": 50}}, "weakAreas": {"retireAfter": 2, "unit": "sessions"}, "theme": {"accent": "#007A87"}, "legacy": [{"key": "pwpath-v1", "format": "pwpath-v1"}, {"key": "learnpaths-v1", "format": "learnpaths-v1", "course": "pw"}]}, "syllabus": {"modules": [{"id": "1", "title": "Foundations", "difficulty": "Beginner", "blurb": "What Playwright is, how a project is set up, and how a test is built and run.", "sections": [], "topics": [{"code": "1.1", "title": "What Playwright is", "objective": "Describe Playwright, the browsers and languages it supports, and the ideas that make it reliable.", "level": "Understand", "minutes": 8}, {"code": "1.2", "title": "Setting up a project", "objective": "Install Playwright for JavaScript or Python and recognise the files a new project contains.", "level": "Understand", "minutes": 10}, {"code": "1.3", "title": "Anatomy of a test", "objective": "Write a test with a fixture, actions and an assertion in either language.", "level": "Understand", "minutes": 12}, {"code": "1.4", "title": "Running tests from the CLI", "objective": "Run, filter and inspect tests with the command line and the HTML report.", "level": "Understand", "minutes": 10}]}, {"id": "2", "title": "Locators", "difficulty": "Beginner", "blurb": "Finding elements the way users do, and keeping locators precise.", "sections": [], "topics": [{"code": "2.1", "title": "Role-based locators", "objective": "Locate elements by ARIA role and accessible name with getByRole.", "level": "Understand", "minutes": 12}, {"code": "2.2", "title": "Text, label, placeholder and test id", "objective": "Choose the right user-facing locator for text, form controls, images and test ids.", "level": "Understand", "minutes": 12}, {"code": "2.3", "title": "CSS, chaining and filtering", "objective": "Narrow locators by chaining and filtering, and judge when CSS or XPath is acceptable.", "level": "Understand", "minutes": 14}, {"code": "2.4", "title": "Strictness and lists", "objective": "Explain strict mode and work with lists using count, first, last and nth.", "level": "Understand", "minutes": 12}]}, {"id": "3", "title": "Actions", "difficulty": "Beginner", "blurb": "Navigating, clicking, typing, choosing and handling browser events.", "sections": [], "topics": [{"code": "3.1", "title": "Navigation and clicking", "objective": "Navigate pages and perform clicks with the right options.", "level": "Understand", "minutes": 10}, {"code": "3.2", "title": "Filling forms", "objective": "Fill text fields, tick boxes, choose options and upload files.", "level": "Understand", "minutes": 12}, {"code": "3.3", "title": "Keyboard and mouse", "objective": "Use key presses, shortcuts, hover and drag-and-drop.", "level": "Understand", "minutes": 10}, {"code": "3.4", "title": "Dialogs, popups and downloads", "objective": "Handle dialogs, new tabs, downloads and console events.", "level": "Understand", "minutes": 12}]}, {"id": "4", "title": "Assertions and waiting", "difficulty": "Intermediate", "blurb": "Checking results with retrying assertions and writing tests that do not flake.", "sections": [], "topics": [{"code": "4.1", "title": "Web-first assertions", "objective": "Assert page and element state with auto-retrying expect matchers.", "level": "Understand", "minutes": 14}, {"code": "4.2", "title": "Auto-waiting and actionability", "objective": "Explain the checks Playwright performs before each action.", "level": "Understand", "minutes": 12}, {"code": "4.3", "title": "Timeouts, negation and soft assertions", "objective": "Adjust timeouts and use negated and soft assertions correctly.", "level": "Understand", "minutes": 12}, {"code": "4.4", "title": "Writing stable tests", "objective": "Identify common causes of flaky tests and apply the fixes.", "level": "Understand", "minutes": 14}]}, {"id": "5", "title": "Organising tests", "difficulty": "Intermediate", "blurb": "Hooks, fixtures, page objects and configuration for a growing suite.", "sections": [], "topics": [{"code": "5.1", "title": "Hooks and grouping", "objective": "Group tests and share setup with hooks, tags, skip and only.", "level": "Understand", "minutes": 12}, {"code": "5.2", "title": "Fixtures", "objective": "Use built-in fixtures and write custom fixtures with setup and teardown.", "level": "Understand", "minutes": 16}, {"code": "5.3", "title": "Page Object Model", "objective": "Structure page objects that keep tests readable and maintainable.", "level": "Understand", "minutes": 14}, {"code": "5.4", "title": "Configuration and projects", "objective": "Configure base URL, retries, reporters, devices and projects.", "level": "Understand", "minutes": 14}]}, {"id": "6", "title": "Advanced testing", "difficulty": "Advanced", "blurb": "Network control, API tests, authentication, debugging, CI and visual checks.", "sections": [], "topics": [{"code": "6.1", "title": "Network mocking", "objective": "Intercept, fulfil, modify and abort network requests.", "level": "Understand", "minutes": 16}, {"code": "6.2", "title": "API testing", "objective": "Test REST APIs and use API calls to set up UI tests.", "level": "Understand", "minutes": 14}, {"code": "6.3", "title": "Authentication and storage state", "objective": "Reuse a logged-in state across tests with storage state and setup projects.", "level": "Understand", "minutes": 14}, {"code": "6.4", "title": "Debugging and tracing", "objective": "Debug failures with the Inspector, UI mode, Trace Viewer and codegen.", "level": "Understand", "minutes": 12}, {"code": "6.5", "title": "CI and parallel runs", "objective": "Run tests in parallel, shard across machines and configure CI.", "level": "Understand", "minutes": 14}, {"code": "6.6", "title": "Visual and cross-browser testing", "objective": "Compare screenshots and emulate devices and browsers.", "level": "Understand", "minutes": 12}]}]}, "lessons": {"1.1": {"front": {"topic": "1.1", "title": "What Playwright is", "objective": "Describe Playwright, the browsers and languages it supports, and the ideas that make it reliable.", "level": "Understand", "minutes": 8}, "explanation": "Playwright is an open-source framework from Microsoft for **end-to-end testing** of web applications. One API drives all three modern browser engines: **Chromium** (Chrome, Edge), **Firefox** and **WebKit** (the engine behind Safari), on Windows, macOS and Linux.\n\nYou can write Playwright tests in **TypeScript/JavaScript, Python, Java and .NET**. JavaScript users get the full test runner, *Playwright Test*. Python users usually run Playwright through **pytest** with the `pytest-playwright` plugin.\n\n### Why tests stay reliable\n- **Auto-waiting** — before clicking or typing, Playwright waits until the element is ready. You rarely write sleeps.\n- **Web-first assertions** — `expect` checks retry until the condition is met or a timeout passes.\n- **Isolation** — every test gets a fresh *browser context*, like a new private profile, so tests do not share cookies or storage.\n- **Tooling** — code generation, the Inspector, UI mode and the Trace Viewer help you write and debug tests.\n\nBrowsers run **headless** (no visible window) by default, which is fast and suits CI.", "example": {"js": "import { test, expect } from '@playwright/test';\n\ntest('shop opens', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await expect(page).toHaveTitle('Pocket Shop');\n});", "py": "from playwright.sync_api import Page, expect\n\ndef test_shop_opens(page: Page):\n    page.goto(\"https://shop.test/\")\n    expect(page).to_have_title(\"Pocket Shop\")"}, "exampleMd": "```js\nimport { test, expect } from '@playwright/test';\n\ntest('shop opens', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await expect(page).toHaveTitle('Pocket Shop');\n});\n```\n\n```py\nfrom playwright.sync_api import Page, expect\n\ndef test_shop_opens(page: Page):\n    page.goto(\"https://shop.test/\")\n    expect(page).to_have_title(\"Pocket Shop\")\n```", "watchOut": "Exams and interviews love the trio: Chromium, Firefox, WebKit. \"Safari\" is WebKit; \"Chrome\" and \"Edge\" are Chromium.", "demos": [], "raw": "\n## Explanation\nPlaywright is an open-source framework from Microsoft for **end-to-end testing** of web applications. One API drives all three modern browser engines: **Chromium** (Chrome, Edge), **Firefox** and **WebKit** (the engine behind Safari), on Windows, macOS and Linux.\n\nYou can write Playwright tests in **TypeScript/JavaScript, Python, Java and .NET**. JavaScript users get the full test runner, *Playwright Test*. Python users usually run Playwright through **pytest** with the `pytest-playwright` plugin.\n\n### Why tests stay reliable\n- **Auto-waiting** — before clicking or typing, Playwright waits until the element is ready. You rarely write sleeps.\n- **Web-first assertions** — `expect` checks retry until the condition is met or a timeout passes.\n- **Isolation** — every test gets a fresh *browser context*, like a new private profile, so tests do not share cookies or storage.\n- **Tooling** — code generation, the Inspector, UI mode and the Trace Viewer help you write and debug tests.\n\nBrowsers run **headless** (no visible window) by default, which is fast and suits CI.\n\n## Example\n```js\nimport { test, expect } from '@playwright/test';\n\ntest('shop opens', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await expect(page).toHaveTitle('Pocket Shop');\n});\n```\n\n```py\nfrom playwright.sync_api import Page, expect\n\ndef test_shop_opens(page: Page):\n    page.goto(\"https://shop.test/\")\n    expect(page).to_have_title(\"Pocket Shop\")\n```\n\n## Watch out\nExams and interviews love the trio: Chromium, Firefox, WebKit. \"Safari\" is WebKit; \"Chrome\" and \"Edge\" are Chromium.\n"}, "1.2": {"front": {"topic": "1.2", "title": "Setting up a project", "objective": "Install Playwright for JavaScript or Python and recognise the files a new project contains.", "level": "Understand", "minutes": 10}, "explanation": "### JavaScript / TypeScript\nRun `npm init playwright@latest` in a project folder. The wizard installs **@playwright/test**, downloads browsers and creates:\n- `playwright.config.ts` — project-wide settings (test folder, browsers, retries, reporter)\n- `tests/example.spec.ts` — a sample test\n- optionally a GitHub Actions workflow\n\nBrowsers can be (re)installed with `npx playwright install`. On Linux CI machines add `--with-deps` to install the system libraries the browsers need.\n\n### Python\n```\npip install pytest-playwright\nplaywright install\n```\nThe first line installs the pytest plugin and the Playwright library. The second downloads the browser binaries — forgetting it is the most common setup error.\n\n### Where tests live\n- Playwright Test finds files named `*.spec.ts` / `*.test.ts` (or `.js`) inside `testDir`.\n- pytest collects files named `test_*.py` or `*_test.py`, and functions starting with `test`.", "example": {"js": "// playwright.config.ts (generated, shortened)\nimport { defineConfig, devices } from '@playwright/test';\n\nexport default defineConfig({\n  testDir: './tests',\n  reporter: 'html',\n  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],\n});", "py": "# tests/test_home.py — pytest collects this file\nfrom playwright.sync_api import Page, expect\n\ndef test_home(page: Page):\n    page.goto(\"https://shop.test/\")\n    expect(page).to_have_title(\"Pocket Shop\")"}, "exampleMd": "```js\n// playwright.config.ts (generated, shortened)\nimport { defineConfig, devices } from '@playwright/test';\n\nexport default defineConfig({\n  testDir: './tests',\n  reporter: 'html',\n  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],\n});\n```\n\n```py\n# tests/test_home.py — pytest collects this file\nfrom playwright.sync_api import Page, expect\n\ndef test_home(page: Page):\n    page.goto(\"https://shop.test/\")\n    expect(page).to_have_title(\"Pocket Shop\")\n```", "watchOut": "\"I installed pytest-playwright but the browser won't launch\" → run `playwright install`.", "demos": [], "raw": "\n## Explanation\n### JavaScript / TypeScript\nRun `npm init playwright@latest` in a project folder. The wizard installs **@playwright/test**, downloads browsers and creates:\n- `playwright.config.ts` — project-wide settings (test folder, browsers, retries, reporter)\n- `tests/example.spec.ts` — a sample test\n- optionally a GitHub Actions workflow\n\nBrowsers can be (re)installed with `npx playwright install`. On Linux CI machines add `--with-deps` to install the system libraries the browsers need.\n\n### Python\n```\npip install pytest-playwright\nplaywright install\n```\nThe first line installs the pytest plugin and the Playwright library. The second downloads the browser binaries — forgetting it is the most common setup error.\n\n### Where tests live\n- Playwright Test finds files named `*.spec.ts` / `*.test.ts` (or `.js`) inside `testDir`.\n- pytest collects files named `test_*.py` or `*_test.py`, and functions starting with `test`.\n\n## Example\n```js\n// playwright.config.ts (generated, shortened)\nimport { defineConfig, devices } from '@playwright/test';\n\nexport default defineConfig({\n  testDir: './tests',\n  reporter: 'html',\n  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],\n});\n```\n\n```py\n# tests/test_home.py — pytest collects this file\nfrom playwright.sync_api import Page, expect\n\ndef test_home(page: Page):\n    page.goto(\"https://shop.test/\")\n    expect(page).to_have_title(\"Pocket Shop\")\n```\n\n## Watch out\n\"I installed pytest-playwright but the browser won't launch\" → run `playwright install`.\n"}, "1.3": {"front": {"topic": "1.3", "title": "Anatomy of a test", "objective": "Write a test with a fixture, actions and an assertion in either language.", "level": "Understand", "minutes": 12, "activities": ["first-test"]}, "explanation": "A test has three parts: **arrange** (get to the right state), **act** (do what a user does) and **assert** (check the result).\n\n### JavaScript\n`test(name, async ({ page }) => { … })` registers a test. The second argument receives an object of **fixtures**; `{ page }` takes the `page` fixture out of it. Playwright's API is **asynchronous**, so every action and assertion is preceded by `await`.\n\n### Python\npytest calls any function named `test_…`. Declaring a parameter called `page` asks the plugin for the **page fixture**. The sync API is used, so there is no `await`. Import `expect` from `playwright.sync_api`.\n\n### Assertions\n`expect(...)` checks state. A test without an assertion passes as long as nothing throws — which proves very little. End every test with at least one meaningful check.\n\nNaming differs by language: JavaScript uses camelCase (`getByRole`, `toHaveText`), Python uses snake_case (`get_by_role`, `to_have_text`).", "example": {"js": "import { test, expect } from '@playwright/test';\n\ntest('error for empty login', async ({ page }) => {\n  await page.goto('https://shop.test/');                        // arrange\n  await page.getByRole('button', { name: 'Log in' }).click();   // act\n  await expect(page.getByRole('alert'))                         // assert\n    .toHaveText('Username is required');\n});", "py": "from playwright.sync_api import Page, expect\n\ndef test_error_for_empty_login(page: Page):\n    page.goto(\"https://shop.test/\")                          # arrange\n    page.get_by_role(\"button\", name=\"Log in\").click()        # act\n    expect(page.get_by_role(\"alert\")).to_have_text(          # assert\n        \"Username is required\")"}, "exampleMd": "```js\nimport { test, expect } from '@playwright/test';\n\ntest('error for empty login', async ({ page }) => {\n  await page.goto('https://shop.test/');                        // arrange\n  await page.getByRole('button', { name: 'Log in' }).click();   // act\n  await expect(page.getByRole('alert'))                         // assert\n    .toHaveText('Username is required');\n});\n```\n\n```py\nfrom playwright.sync_api import Page, expect\n\ndef test_error_for_empty_login(page: Page):\n    page.goto(\"https://shop.test/\")                          # arrange\n    page.get_by_role(\"button\", name=\"Log in\").click()        # act\n    expect(page.get_by_role(\"alert\")).to_have_text(          # assert\n        \"Username is required\")\n```", "watchOut": "Forgetting `await` in JavaScript is the classic beginner bug: the test may finish before the action runs.", "demos": [], "raw": "\n## Explanation\nA test has three parts: **arrange** (get to the right state), **act** (do what a user does) and **assert** (check the result).\n\n### JavaScript\n`test(name, async ({ page }) => { … })` registers a test. The second argument receives an object of **fixtures**; `{ page }` takes the `page` fixture out of it. Playwright's API is **asynchronous**, so every action and assertion is preceded by `await`.\n\n### Python\npytest calls any function named `test_…`. Declaring a parameter called `page` asks the plugin for the **page fixture**. The sync API is used, so there is no `await`. Import `expect` from `playwright.sync_api`.\n\n### Assertions\n`expect(...)` checks state. A test without an assertion passes as long as nothing throws — which proves very little. End every test with at least one meaningful check.\n\nNaming differs by language: JavaScript uses camelCase (`getByRole`, `toHaveText`), Python uses snake_case (`get_by_role`, `to_have_text`).\n\n## Example\n```js\nimport { test, expect } from '@playwright/test';\n\ntest('error for empty login', async ({ page }) => {\n  await page.goto('https://shop.test/');                        // arrange\n  await page.getByRole('button', { name: 'Log in' }).click();   // act\n  await expect(page.getByRole('alert'))                         // assert\n    .toHaveText('Username is required');\n});\n```\n\n```py\nfrom playwright.sync_api import Page, expect\n\ndef test_error_for_empty_login(page: Page):\n    page.goto(\"https://shop.test/\")                          # arrange\n    page.get_by_role(\"button\", name=\"Log in\").click()        # act\n    expect(page.get_by_role(\"alert\")).to_have_text(          # assert\n        \"Username is required\")\n```\n\n## Watch out\nForgetting `await` in JavaScript is the classic beginner bug: the test may finish before the action runs.\n"}, "1.4": {"front": {"topic": "1.4", "title": "Running tests from the CLI", "objective": "Run, filter and inspect tests with the command line and the HTML report.", "level": "Understand", "minutes": 10}, "explanation": "### JavaScript (Playwright Test)\n- `npx playwright test` — run everything (headless, all projects)\n- `npx playwright test tests/login.spec.ts` — one file\n- `-g \"checkout\"` or `--grep` — only tests whose title matches\n- `--project=chromium` — one project (browser)\n- `--headed` — show the browser window\n- `--ui` — **UI mode**: watch mode, time-travel through steps\n- `--debug` — step through with the Playwright Inspector\n- `--last-failed` — rerun only the failures\n- `npx playwright show-report` — open the HTML report\n\n### Python (pytest)\n- `pytest` — run everything\n- `pytest -k \"checkout\"` — filter by name\n- `--headed`, `--browser firefox` (repeatable), `--slowmo 500`\n- `--tracing retain-on-failure` — keep traces for failed tests\n- parallel runs need the **pytest-xdist** plugin: `pytest -n auto`\n\nThe HTML report shows each test, its steps, errors and attachments such as traces and screenshots.", "example": {"js": "# run only checkout tests in Firefox, with a visible browser\nnpx playwright test -g \"checkout\" --project=firefox --headed\n\n# open the last HTML report\nnpx playwright show-report", "py": "# run only checkout tests in Firefox, with a visible browser\npytest -k \"checkout\" --browser firefox --headed\n\n# keep traces for failures\npytest --tracing retain-on-failure"}, "exampleMd": "```js\n# run only checkout tests in Firefox, with a visible browser\nnpx playwright test -g \"checkout\" --project=firefox --headed\n\n# open the last HTML report\nnpx playwright show-report\n```\n\n```py\n# run only checkout tests in Firefox, with a visible browser\npytest -k \"checkout\" --browser firefox --headed\n\n# keep traces for failures\npytest --tracing retain-on-failure\n```", "watchOut": "JS filters with `-g`; pytest filters with `-k`. Mixing them up is a common slip.", "demos": [], "raw": "\n## Explanation\n### JavaScript (Playwright Test)\n- `npx playwright test` — run everything (headless, all projects)\n- `npx playwright test tests/login.spec.ts` — one file\n- `-g \"checkout\"` or `--grep` — only tests whose title matches\n- `--project=chromium` — one project (browser)\n- `--headed` — show the browser window\n- `--ui` — **UI mode**: watch mode, time-travel through steps\n- `--debug` — step through with the Playwright Inspector\n- `--last-failed` — rerun only the failures\n- `npx playwright show-report` — open the HTML report\n\n### Python (pytest)\n- `pytest` — run everything\n- `pytest -k \"checkout\"` — filter by name\n- `--headed`, `--browser firefox` (repeatable), `--slowmo 500`\n- `--tracing retain-on-failure` — keep traces for failed tests\n- parallel runs need the **pytest-xdist** plugin: `pytest -n auto`\n\nThe HTML report shows each test, its steps, errors and attachments such as traces and screenshots.\n\n## Example\n```js\n# run only checkout tests in Firefox, with a visible browser\nnpx playwright test -g \"checkout\" --project=firefox --headed\n\n# open the last HTML report\nnpx playwright show-report\n```\n\n```py\n# run only checkout tests in Firefox, with a visible browser\npytest -k \"checkout\" --browser firefox --headed\n\n# keep traces for failures\npytest --tracing retain-on-failure\n```\n\n## Watch out\nJS filters with `-g`; pytest filters with `-k`. Mixing them up is a common slip.\n"}, "2.1": {"front": {"topic": "2.1", "title": "Role-based locators", "objective": "Locate elements by ARIA role and accessible name with getByRole.", "level": "Understand", "minutes": 12, "activities": ["role-login"]}, "explanation": "`getByRole(role, options)` finds elements by their **ARIA role** and **accessible name** — the same information screen readers use. Playwright recommends it as your **first choice**: it reflects how users perceive the page and survives most markup changes.\n\n### Roles you get for free\nNative HTML elements have implicit roles: `<button>` → `button`, `<a href>` → `link`, `<h1>`–`<h6>` → `heading`, `<input type=\"text\">` and `<textarea>` → `textbox`, checkboxes → `checkbox`, `<select>` → `combobox`, `<li>` → `listitem`.\n\n### The accessible name\nIt comes from a `<label>`, an `aria-label`, or the element's text. By default `name` matches **case-insensitively** and as a **substring**: `name: 'log'` matches “Log in”. Pass `exact: true` for a full, case-sensitive match, or a regular expression for patterns.\n\n### Useful options\n`level` (headings), `checked`, `disabled`, `expanded`, `selected`, `pressed`.\n\nIf an element cannot be found by role, that often signals an accessibility problem worth reporting.", "example": {"js": "await page.getByRole('textbox', { name: 'Username' }).fill('standard_user');\nawait page.getByRole('button', { name: 'Log in' }).click();\nawait expect(page.getByRole('heading', { name: 'Products', level: 2 })).toBeVisible();", "py": "page.get_by_role(\"textbox\", name=\"Username\").fill(\"standard_user\")\npage.get_by_role(\"button\", name=\"Log in\").click()\nexpect(page.get_by_role(\"heading\", name=\"Products\", level=2)).to_be_visible()"}, "exampleMd": "```js\nawait page.getByRole('textbox', { name: 'Username' }).fill('standard_user');\nawait page.getByRole('button', { name: 'Log in' }).click();\nawait expect(page.getByRole('heading', { name: 'Products', level: 2 })).toBeVisible();\n```\n\n```py\npage.get_by_role(\"textbox\", name=\"Username\").fill(\"standard_user\")\npage.get_by_role(\"button\", name=\"Log in\").click()\nexpect(page.get_by_role(\"heading\", name=\"Products\", level=2)).to_be_visible()\n```", "watchOut": "Password inputs also have the role `textbox`. There is no \"password\" role.", "demos": [], "raw": "\n## Explanation\n`getByRole(role, options)` finds elements by their **ARIA role** and **accessible name** — the same information screen readers use. Playwright recommends it as your **first choice**: it reflects how users perceive the page and survives most markup changes.\n\n### Roles you get for free\nNative HTML elements have implicit roles: `<button>` → `button`, `<a href>` → `link`, `<h1>`–`<h6>` → `heading`, `<input type=\"text\">` and `<textarea>` → `textbox`, checkboxes → `checkbox`, `<select>` → `combobox`, `<li>` → `listitem`.\n\n### The accessible name\nIt comes from a `<label>`, an `aria-label`, or the element's text. By default `name` matches **case-insensitively** and as a **substring**: `name: 'log'` matches “Log in”. Pass `exact: true` for a full, case-sensitive match, or a regular expression for patterns.\n\n### Useful options\n`level` (headings), `checked`, `disabled`, `expanded`, `selected`, `pressed`.\n\nIf an element cannot be found by role, that often signals an accessibility problem worth reporting.\n\n## Example\n```js\nawait page.getByRole('textbox', { name: 'Username' }).fill('standard_user');\nawait page.getByRole('button', { name: 'Log in' }).click();\nawait expect(page.getByRole('heading', { name: 'Products', level: 2 })).toBeVisible();\n```\n\n```py\npage.get_by_role(\"textbox\", name=\"Username\").fill(\"standard_user\")\npage.get_by_role(\"button\", name=\"Log in\").click()\nexpect(page.get_by_role(\"heading\", name=\"Products\", level=2)).to_be_visible()\n```\n\n## Watch out\nPassword inputs also have the role `textbox`. There is no \"password\" role.\n"}, "2.2": {"front": {"topic": "2.2", "title": "Text, label, placeholder and test id", "objective": "Choose the right user-facing locator for text, form controls, images and test ids.", "level": "Understand", "minutes": 12, "activities": ["todo-locators"]}, "explanation": "When a role does not fit, use the next user-facing locator:\n\n- **getByText(text)** — non-interactive content such as messages and paragraphs. Substring and case-insensitive by default; `{ exact: true }` tightens it.\n- **getByLabel(text)** — form controls by their `<label>` or `aria-label`. Ideal for inputs.\n- **getByPlaceholder(text)** — inputs that have a placeholder but no label.\n- **getByAltText(text)** — images by their `alt` text.\n- **getByTitle(text)** — elements with a `title` attribute.\n- **getByTestId(id)** — elements with `data-testid=\"id\"`.\n\n### About test ids\nTest ids are stable because they are not tied to text or layout, but users never see them. Use them when nothing user-facing is reliable — for example, a badge with changing numbers. The attribute name can be changed: `use: { testIdAttribute: 'data-qa' }` in the config, or `playwright.selectors.set_test_id_attribute(\"data-qa\")` in Python.", "example": {"js": "const input = page.getByPlaceholder('What needs to be done?');\nawait input.fill('Buy milk');\nawait input.press('Enter');\nawait expect(page.getByTestId('todo-item')).toHaveText('Buy milk');\nawait expect(page.getByText('1 item left')).toBeVisible();", "py": "new_todo = page.get_by_placeholder(\"What needs to be done?\")\nnew_todo.fill(\"Buy milk\")\nnew_todo.press(\"Enter\")\nexpect(page.get_by_test_id(\"todo-item\")).to_have_text(\"Buy milk\")\nexpect(page.get_by_text(\"1 item left\")).to_be_visible()"}, "exampleMd": "```js\nconst input = page.getByPlaceholder('What needs to be done?');\nawait input.fill('Buy milk');\nawait input.press('Enter');\nawait expect(page.getByTestId('todo-item')).toHaveText('Buy milk');\nawait expect(page.getByText('1 item left')).toBeVisible();\n```\n\n```py\nnew_todo = page.get_by_placeholder(\"What needs to be done?\")\nnew_todo.fill(\"Buy milk\")\nnew_todo.press(\"Enter\")\nexpect(page.get_by_test_id(\"todo-item\")).to_have_text(\"Buy milk\")\nexpect(page.get_by_text(\"1 item left\")).to_be_visible()\n```", "watchOut": "Order of preference: role → label → placeholder → text → alt/title → test id → CSS/XPath.", "demos": [], "raw": "\n## Explanation\nWhen a role does not fit, use the next user-facing locator:\n\n- **getByText(text)** — non-interactive content such as messages and paragraphs. Substring and case-insensitive by default; `{ exact: true }` tightens it.\n- **getByLabel(text)** — form controls by their `<label>` or `aria-label`. Ideal for inputs.\n- **getByPlaceholder(text)** — inputs that have a placeholder but no label.\n- **getByAltText(text)** — images by their `alt` text.\n- **getByTitle(text)** — elements with a `title` attribute.\n- **getByTestId(id)** — elements with `data-testid=\"id\"`.\n\n### About test ids\nTest ids are stable because they are not tied to text or layout, but users never see them. Use them when nothing user-facing is reliable — for example, a badge with changing numbers. The attribute name can be changed: `use: { testIdAttribute: 'data-qa' }` in the config, or `playwright.selectors.set_test_id_attribute(\"data-qa\")` in Python.\n\n## Example\n```js\nconst input = page.getByPlaceholder('What needs to be done?');\nawait input.fill('Buy milk');\nawait input.press('Enter');\nawait expect(page.getByTestId('todo-item')).toHaveText('Buy milk');\nawait expect(page.getByText('1 item left')).toBeVisible();\n```\n\n```py\nnew_todo = page.get_by_placeholder(\"What needs to be done?\")\nnew_todo.fill(\"Buy milk\")\nnew_todo.press(\"Enter\")\nexpect(page.get_by_test_id(\"todo-item\")).to_have_text(\"Buy milk\")\nexpect(page.get_by_text(\"1 item left\")).to_be_visible()\n```\n\n## Watch out\nOrder of preference: role → label → placeholder → text → alt/title → test id → CSS/XPath.\n"}, "2.3": {"front": {"topic": "2.3", "title": "CSS, chaining and filtering", "objective": "Narrow locators by chaining and filtering, and judge when CSS or XPath is acceptable.", "level": "Understand", "minutes": 14, "activities": ["table-filter"]}, "explanation": "### CSS and XPath\n`page.locator('css selector')` and `page.locator('xpath=//…')` work, but they depend on **markup structure** — class names, nesting, positions — that developers change freely. Prefer user-facing locators; keep CSS for cases like `#items li` where structure is the point.\n\n### Chaining\nCalling a locator method on another locator searches **inside** it:\n`page.getByRole('row').filter(…).getByRole('button')`.\n\n### Filtering\n`locator.filter(options)` keeps only matching elements:\n- `hasText` / `hasNotText` — contains (or not) some text\n- `has` / `hasNot` — contains (or not) an element matching another locator\n\n### Combining\n`a.or(b)` matches either; `a.and(b)` requires both.\n\nFiltering by the text a user sees (a product name, a person) is the standard way to pick one item out of a repeated list.", "example": {"js": "const row = page.getByRole('row').filter({ hasText: 'Chen Wei' });\nawait row.getByRole('button', { name: 'Edit' }).click();\n\n// rows that contain an Edit button but not the word \"Admin\"\nconst editable = page.getByRole('row')\n  .filter({ has: page.getByRole('button', { name: 'Edit' }) })\n  .filter({ hasNotText: 'Admin' });", "py": "row = page.get_by_role(\"row\").filter(has_text=\"Chen Wei\")\nrow.get_by_role(\"button\", name=\"Edit\").click()\n\n# rows that contain an Edit button but not the word \"Admin\"\neditable = (page.get_by_role(\"row\")\n            .filter(has=page.get_by_role(\"button\", name=\"Edit\"))\n            .filter(has_not_text=\"Admin\"))"}, "exampleMd": "```js\nconst row = page.getByRole('row').filter({ hasText: 'Chen Wei' });\nawait row.getByRole('button', { name: 'Edit' }).click();\n\n// rows that contain an Edit button but not the word \"Admin\"\nconst editable = page.getByRole('row')\n  .filter({ has: page.getByRole('button', { name: 'Edit' }) })\n  .filter({ hasNotText: 'Admin' });\n```\n\n```py\nrow = page.get_by_role(\"row\").filter(has_text=\"Chen Wei\")\nrow.get_by_role(\"button\", name=\"Edit\").click()\n\n# rows that contain an Edit button but not the word \"Admin\"\neditable = (page.get_by_role(\"row\")\n            .filter(has=page.get_by_role(\"button\", name=\"Edit\"))\n            .filter(has_not_text=\"Admin\"))\n```", "watchOut": "`has` takes a locator; `hasText` takes a string or regex. Python spells them `has` and `has_text`.", "demos": [], "raw": "\n## Explanation\n### CSS and XPath\n`page.locator('css selector')` and `page.locator('xpath=//…')` work, but they depend on **markup structure** — class names, nesting, positions — that developers change freely. Prefer user-facing locators; keep CSS for cases like `#items li` where structure is the point.\n\n### Chaining\nCalling a locator method on another locator searches **inside** it:\n`page.getByRole('row').filter(…).getByRole('button')`.\n\n### Filtering\n`locator.filter(options)` keeps only matching elements:\n- `hasText` / `hasNotText` — contains (or not) some text\n- `has` / `hasNot` — contains (or not) an element matching another locator\n\n### Combining\n`a.or(b)` matches either; `a.and(b)` requires both.\n\nFiltering by the text a user sees (a product name, a person) is the standard way to pick one item out of a repeated list.\n\n## Example\n```js\nconst row = page.getByRole('row').filter({ hasText: 'Chen Wei' });\nawait row.getByRole('button', { name: 'Edit' }).click();\n\n// rows that contain an Edit button but not the word \"Admin\"\nconst editable = page.getByRole('row')\n  .filter({ has: page.getByRole('button', { name: 'Edit' }) })\n  .filter({ hasNotText: 'Admin' });\n```\n\n```py\nrow = page.get_by_role(\"row\").filter(has_text=\"Chen Wei\")\nrow.get_by_role(\"button\", name=\"Edit\").click()\n\n# rows that contain an Edit button but not the word \"Admin\"\neditable = (page.get_by_role(\"row\")\n            .filter(has=page.get_by_role(\"button\", name=\"Edit\"))\n            .filter(has_not_text=\"Admin\"))\n```\n\n## Watch out\n`has` takes a locator; `hasText` takes a string or regex. Python spells them `has` and `has_text`.\n"}, "2.4": {"front": {"topic": "2.4", "title": "Strictness and lists", "objective": "Explain strict mode and work with lists using count, first, last and nth.", "level": "Understand", "minutes": 12, "activities": ["strict-lists"]}, "explanation": "### Strict mode\nActions such as `click()` and `fill()` require the locator to match **exactly one** element. If it matches several, Playwright throws a *strict mode violation* listing the matches. This protects you from clicking the wrong thing silently.\n\nFix it by making the locator more specific (a filter, a better name) or by choosing one element explicitly.\n\n### Working with many elements\n- `count()` — number of matches (no waiting)\n- `first()`, `last()`, `nth(i)` — pick one; `nth` is **zero-based**\n- `all()` — list of locators, one per match\n- `allTextContents()` — texts of all matches\n- `expect(locator).toHaveCount(n)` — retrying count check\n\nIn Python, `first` and `last` are **properties**; `nth(i)` is a method.\n\n### Locators are lazy\nA locator is a recipe, not an element. It is resolved every time you use it, so it always targets the current page state.\n\nPrefer filtering by meaning over positions: `nth(2)` breaks when the order changes.", "example": {"js": "const products = page.getByTestId('product');\nawait expect(products).toHaveCount(6);\nawait products.first().getByRole('button', { name: 'Add to cart' }).click();\nawait products.nth(2).getByRole('button', { name: 'Add to cart' }).click(); // third item\nconst names = await page.getByRole('heading', { level: 3 }).allTextContents();", "py": "products = page.get_by_test_id(\"product\")\nexpect(products).to_have_count(6)\nproducts.first.get_by_role(\"button\", name=\"Add to cart\").click()\nproducts.nth(2).get_by_role(\"button\", name=\"Add to cart\").click()  # third item\nnames = page.get_by_role(\"heading\", level=3).all_text_contents()"}, "exampleMd": "```js\nconst products = page.getByTestId('product');\nawait expect(products).toHaveCount(6);\nawait products.first().getByRole('button', { name: 'Add to cart' }).click();\nawait products.nth(2).getByRole('button', { name: 'Add to cart' }).click(); // third item\nconst names = await page.getByRole('heading', { level: 3 }).allTextContents();\n```\n\n```py\nproducts = page.get_by_test_id(\"product\")\nexpect(products).to_have_count(6)\nproducts.first.get_by_role(\"button\", name=\"Add to cart\").click()\nproducts.nth(2).get_by_role(\"button\", name=\"Add to cart\").click()  # third item\nnames = page.get_by_role(\"heading\", level=3).all_text_contents()\n```", "watchOut": "nth(1) is the second element. Zero-based indexing is a favourite trick question.", "demos": [], "raw": "\n## Explanation\n### Strict mode\nActions such as `click()` and `fill()` require the locator to match **exactly one** element. If it matches several, Playwright throws a *strict mode violation* listing the matches. This protects you from clicking the wrong thing silently.\n\nFix it by making the locator more specific (a filter, a better name) or by choosing one element explicitly.\n\n### Working with many elements\n- `count()` — number of matches (no waiting)\n- `first()`, `last()`, `nth(i)` — pick one; `nth` is **zero-based**\n- `all()` — list of locators, one per match\n- `allTextContents()` — texts of all matches\n- `expect(locator).toHaveCount(n)` — retrying count check\n\nIn Python, `first` and `last` are **properties**; `nth(i)` is a method.\n\n### Locators are lazy\nA locator is a recipe, not an element. It is resolved every time you use it, so it always targets the current page state.\n\nPrefer filtering by meaning over positions: `nth(2)` breaks when the order changes.\n\n## Example\n```js\nconst products = page.getByTestId('product');\nawait expect(products).toHaveCount(6);\nawait products.first().getByRole('button', { name: 'Add to cart' }).click();\nawait products.nth(2).getByRole('button', { name: 'Add to cart' }).click(); // third item\nconst names = await page.getByRole('heading', { level: 3 }).allTextContents();\n```\n\n```py\nproducts = page.get_by_test_id(\"product\")\nexpect(products).to_have_count(6)\nproducts.first.get_by_role(\"button\", name=\"Add to cart\").click()\nproducts.nth(2).get_by_role(\"button\", name=\"Add to cart\").click()  # third item\nnames = page.get_by_role(\"heading\", level=3).all_text_contents()\n```\n\n## Watch out\nnth(1) is the second element. Zero-based indexing is a favourite trick question.\n"}, "3.1": {"front": {"topic": "3.1", "title": "Navigation and clicking", "objective": "Navigate pages and perform clicks with the right options.", "level": "Understand", "minutes": 10, "activities": ["navigate-cart"]}, "explanation": "### Navigating\n`page.goto(url)` loads a page and, by default, waits for the **load** event. The `waitUntil` option accepts `'domcontentloaded'`, `'load'`, `'networkidle'` (discouraged) or `'commit'`. With a `baseURL` configured, `goto('/cart')` is resolved against it. Other navigation: `reload()`, `goBack()`, `goForward()`.\n\n### Clicking\n`locator.click()` scrolls the element into view, waits until it is actionable, then clicks its centre. Options:\n- `button: 'right' | 'middle'`\n- `clickCount: 2` (or use `dblclick()`)\n- `modifiers: ['Shift']`\n- `position: { x, y }`\n- `force: true` — skip actionability checks (last resort)\n\n### After a click navigates\nDo not add waits. The next action or a web-first assertion such as `expect(page).toHaveURL(…)` waits for the new page.", "example": {"js": "await page.getByRole('link', { name: 'Cart' }).click();\nawait expect(page).toHaveURL(/\\/cart$/);\nawait page.getByRole('button', { name: 'Remove' }).click({ modifiers: ['Shift'] });\nawait page.goBack();", "py": "page.get_by_role(\"link\", name=\"Cart\").click()\nexpect(page).to_have_url(re.compile(r\".*/cart$\"))\npage.get_by_role(\"button\", name=\"Remove\").click(modifiers=[\"Shift\"])\npage.go_back()"}, "exampleMd": "```js\nawait page.getByRole('link', { name: 'Cart' }).click();\nawait expect(page).toHaveURL(/\\/cart$/);\nawait page.getByRole('button', { name: 'Remove' }).click({ modifiers: ['Shift'] });\nawait page.goBack();\n```\n\n```py\npage.get_by_role(\"link\", name=\"Cart\").click()\nexpect(page).to_have_url(re.compile(r\".*/cart$\"))\npage.get_by_role(\"button\", name=\"Remove\").click(modifiers=[\"Shift\"])\npage.go_back()\n```", "watchOut": "`force: true` hides real problems (an overlay, a disabled button). Treat it as a code smell.", "demos": [], "raw": "\n## Explanation\n### Navigating\n`page.goto(url)` loads a page and, by default, waits for the **load** event. The `waitUntil` option accepts `'domcontentloaded'`, `'load'`, `'networkidle'` (discouraged) or `'commit'`. With a `baseURL` configured, `goto('/cart')` is resolved against it. Other navigation: `reload()`, `goBack()`, `goForward()`.\n\n### Clicking\n`locator.click()` scrolls the element into view, waits until it is actionable, then clicks its centre. Options:\n- `button: 'right' | 'middle'`\n- `clickCount: 2` (or use `dblclick()`)\n- `modifiers: ['Shift']`\n- `position: { x, y }`\n- `force: true` — skip actionability checks (last resort)\n\n### After a click navigates\nDo not add waits. The next action or a web-first assertion such as `expect(page).toHaveURL(…)` waits for the new page.\n\n## Example\n```js\nawait page.getByRole('link', { name: 'Cart' }).click();\nawait expect(page).toHaveURL(/\\/cart$/);\nawait page.getByRole('button', { name: 'Remove' }).click({ modifiers: ['Shift'] });\nawait page.goBack();\n```\n\n```py\npage.get_by_role(\"link\", name=\"Cart\").click()\nexpect(page).to_have_url(re.compile(r\".*/cart$\"))\npage.get_by_role(\"button\", name=\"Remove\").click(modifiers=[\"Shift\"])\npage.go_back()\n```\n\n## Watch out\n`force: true` hides real problems (an overlay, a disabled button). Treat it as a code smell.\n"}, "3.2": {"front": {"topic": "3.2", "title": "Filling forms", "objective": "Fill text fields, tick boxes, choose options and upload files.", "level": "Understand", "minutes": 12, "activities": ["signup-form"]}, "explanation": "### Text inputs\n- `fill(value)` — focuses the field, clears it and sets the value in one step. Works on `<input>`, `<textarea>` and `[contenteditable]`.\n- `clear()` — empties the field.\n- `pressSequentially(text)` — types one key at a time, firing key events. Use it only when the page reacts to each key (autocomplete, masks). It replaces the deprecated `type()`.\n\n### Checkboxes and radios\n`check()`, `uncheck()` and `setChecked(bool)` click only if needed and then verify the state. Radios are chosen with `check()`; a radio cannot be unchecked directly.\n\n### Select boxes\n`selectOption()` accepts a value or a label (`'pk'`, `'Pakistan'`), an object (`{ label: 'Pakistan' }`, `{ index: 2 }`) or an array for multi-selects.\n\n### Files\n`setInputFiles(path)` sets files on an `<input type=\"file\">`; an empty array clears it.", "example": {"js": "await page.getByLabel('Full name').fill('Ayesha Malik');\nawait page.getByLabel('Country').selectOption({ label: 'Pakistan' });\nawait page.getByRole('radio', { name: 'Pro' }).check();\nawait page.getByLabel('I agree to the terms').check();\nawait page.getByLabel('Avatar').setInputFiles('fixtures/avatar.png');", "py": "page.get_by_label(\"Full name\").fill(\"Ayesha Malik\")\npage.get_by_label(\"Country\").select_option(label=\"Pakistan\")\npage.get_by_role(\"radio\", name=\"Pro\").check()\npage.get_by_label(\"I agree to the terms\").check()\npage.get_by_label(\"Avatar\").set_input_files(\"fixtures/avatar.png\")"}, "exampleMd": "```js\nawait page.getByLabel('Full name').fill('Ayesha Malik');\nawait page.getByLabel('Country').selectOption({ label: 'Pakistan' });\nawait page.getByRole('radio', { name: 'Pro' }).check();\nawait page.getByLabel('I agree to the terms').check();\nawait page.getByLabel('Avatar').setInputFiles('fixtures/avatar.png');\n```\n\n```py\npage.get_by_label(\"Full name\").fill(\"Ayesha Malik\")\npage.get_by_label(\"Country\").select_option(label=\"Pakistan\")\npage.get_by_role(\"radio\", name=\"Pro\").check()\npage.get_by_label(\"I agree to the terms\").check()\npage.get_by_label(\"Avatar\").set_input_files(\"fixtures/avatar.png\")\n```", "watchOut": "`fill` replaces the current value; `pressSequentially` appends to it.", "demos": [], "raw": "\n## Explanation\n### Text inputs\n- `fill(value)` — focuses the field, clears it and sets the value in one step. Works on `<input>`, `<textarea>` and `[contenteditable]`.\n- `clear()` — empties the field.\n- `pressSequentially(text)` — types one key at a time, firing key events. Use it only when the page reacts to each key (autocomplete, masks). It replaces the deprecated `type()`.\n\n### Checkboxes and radios\n`check()`, `uncheck()` and `setChecked(bool)` click only if needed and then verify the state. Radios are chosen with `check()`; a radio cannot be unchecked directly.\n\n### Select boxes\n`selectOption()` accepts a value or a label (`'pk'`, `'Pakistan'`), an object (`{ label: 'Pakistan' }`, `{ index: 2 }`) or an array for multi-selects.\n\n### Files\n`setInputFiles(path)` sets files on an `<input type=\"file\">`; an empty array clears it.\n\n## Example\n```js\nawait page.getByLabel('Full name').fill('Ayesha Malik');\nawait page.getByLabel('Country').selectOption({ label: 'Pakistan' });\nawait page.getByRole('radio', { name: 'Pro' }).check();\nawait page.getByLabel('I agree to the terms').check();\nawait page.getByLabel('Avatar').setInputFiles('fixtures/avatar.png');\n```\n\n```py\npage.get_by_label(\"Full name\").fill(\"Ayesha Malik\")\npage.get_by_label(\"Country\").select_option(label=\"Pakistan\")\npage.get_by_role(\"radio\", name=\"Pro\").check()\npage.get_by_label(\"I agree to the terms\").check()\npage.get_by_label(\"Avatar\").set_input_files(\"fixtures/avatar.png\")\n```\n\n## Watch out\n`fill` replaces the current value; `pressSequentially` appends to it.\n"}, "3.3": {"front": {"topic": "3.3", "title": "Keyboard and mouse", "objective": "Use key presses, shortcuts, hover and drag-and-drop.", "level": "Understand", "minutes": 10, "activities": ["keyboard-mouse"]}, "explanation": "### Keys\n`locator.press(key)` focuses the element and presses a key: `'Enter'`, `'Tab'`, `'Escape'`, `'ArrowDown'`, `'Backspace'`, a character, or a combination like `'Shift+A'` and `'Control+Enter'`. `'ControlOrMeta+A'` uses Ctrl on Windows/Linux and ⌘ on macOS.\n\n`page.keyboard` works on whatever has focus: `press`, `type`, `down`, `up`, `insertText`.\n\n### Mouse\n- `hover()` — moves the pointer over an element; menus and tooltips that open on hover appear.\n- `dragTo(target)` — drags one locator onto another.\n- `page.mouse.click(x, y)`, `page.mouse.wheel(dx, dy)` — low-level, coordinate based. Prefer locator methods.\n\nHover-only UI disappears when the pointer leaves, so hover immediately before the next action.", "example": {"js": "const input = page.getByPlaceholder('What needs to be done?');\nawait input.fill('Write tests');\nawait input.press('Enter');\n\nawait page.getByRole('button', { name: 'Account' }).hover();\nawait page.getByRole('menuitem', { name: 'Settings' }).click();\nawait page.locator('#card-1').dragTo(page.locator('#done-column'));", "py": "new_todo = page.get_by_placeholder(\"What needs to be done?\")\nnew_todo.fill(\"Write tests\")\nnew_todo.press(\"Enter\")\n\npage.get_by_role(\"button\", name=\"Account\").hover()\npage.get_by_role(\"menuitem\", name=\"Settings\").click()\npage.locator(\"#card-1\").drag_to(page.locator(\"#done-column\"))"}, "exampleMd": "```js\nconst input = page.getByPlaceholder('What needs to be done?');\nawait input.fill('Write tests');\nawait input.press('Enter');\n\nawait page.getByRole('button', { name: 'Account' }).hover();\nawait page.getByRole('menuitem', { name: 'Settings' }).click();\nawait page.locator('#card-1').dragTo(page.locator('#done-column'));\n```\n\n```py\nnew_todo = page.get_by_placeholder(\"What needs to be done?\")\nnew_todo.fill(\"Write tests\")\nnew_todo.press(\"Enter\")\n\npage.get_by_role(\"button\", name=\"Account\").hover()\npage.get_by_role(\"menuitem\", name=\"Settings\").click()\npage.locator(\"#card-1\").drag_to(page.locator(\"#done-column\"))\n```", "watchOut": "Use `ControlOrMeta` in shortcuts so the same test works on macOS and Windows.", "demos": [], "raw": "\n## Explanation\n### Keys\n`locator.press(key)` focuses the element and presses a key: `'Enter'`, `'Tab'`, `'Escape'`, `'ArrowDown'`, `'Backspace'`, a character, or a combination like `'Shift+A'` and `'Control+Enter'`. `'ControlOrMeta+A'` uses Ctrl on Windows/Linux and ⌘ on macOS.\n\n`page.keyboard` works on whatever has focus: `press`, `type`, `down`, `up`, `insertText`.\n\n### Mouse\n- `hover()` — moves the pointer over an element; menus and tooltips that open on hover appear.\n- `dragTo(target)` — drags one locator onto another.\n- `page.mouse.click(x, y)`, `page.mouse.wheel(dx, dy)` — low-level, coordinate based. Prefer locator methods.\n\nHover-only UI disappears when the pointer leaves, so hover immediately before the next action.\n\n## Example\n```js\nconst input = page.getByPlaceholder('What needs to be done?');\nawait input.fill('Write tests');\nawait input.press('Enter');\n\nawait page.getByRole('button', { name: 'Account' }).hover();\nawait page.getByRole('menuitem', { name: 'Settings' }).click();\nawait page.locator('#card-1').dragTo(page.locator('#done-column'));\n```\n\n```py\nnew_todo = page.get_by_placeholder(\"What needs to be done?\")\nnew_todo.fill(\"Write tests\")\nnew_todo.press(\"Enter\")\n\npage.get_by_role(\"button\", name=\"Account\").hover()\npage.get_by_role(\"menuitem\", name=\"Settings\").click()\npage.locator(\"#card-1\").drag_to(page.locator(\"#done-column\"))\n```\n\n## Watch out\nUse `ControlOrMeta` in shortcuts so the same test works on macOS and Windows.\n"}, "3.4": {"front": {"topic": "3.4", "title": "Dialogs, popups and downloads", "objective": "Handle dialogs, new tabs, downloads and console events.", "level": "Understand", "minutes": 12, "activities": ["dialogs"]}, "explanation": "### Dialogs\n`alert`, `confirm` and `prompt` dialogs are **dismissed automatically** unless you handle them. Register a handler **before** the action that opens the dialog:\n\n`page.on('dialog', d => d.accept())` — or `page.once` for a single dialog. `accept(text)` answers a prompt; `dismiss()` cancels. `dialog.message()` and `dialog.type()` describe it.\n\n### New tabs (popups)\nStart waiting, *then* trigger: `const popupPromise = page.waitForEvent('popup'); await link.click(); const popup = await popupPromise;`. Python uses a context manager: `with page.expect_popup() as info: …` then `info.value`.\n\n### Downloads\nSame pattern with `'download'` (`page.expect_download()` in Python), then `download.saveAs(path)` or `download.suggestedFilename()`.\n\n### Console and errors\n`page.on('console', msg => …)` collects console messages; `page.on('pageerror', err => …)` catches uncaught exceptions.", "example": {"js": "page.once('dialog', dialog => dialog.accept('Playwright'));\nawait page.getByRole('button', { name: 'Show prompt' }).click();\nawait expect(page.getByRole('status')).toHaveText('You entered: Playwright');\n\nconst downloadPromise = page.waitForEvent('download');\nawait page.getByRole('link', { name: 'Export CSV' }).click();\nconst download = await downloadPromise;", "py": "page.once(\"dialog\", lambda dialog: dialog.accept(\"Playwright\"))\npage.get_by_role(\"button\", name=\"Show prompt\").click()\nexpect(page.get_by_role(\"status\")).to_have_text(\"You entered: Playwright\")\n\nwith page.expect_download() as download_info:\n    page.get_by_role(\"link\", name=\"Export CSV\").click()\ndownload = download_info.value"}, "exampleMd": "```js\npage.once('dialog', dialog => dialog.accept('Playwright'));\nawait page.getByRole('button', { name: 'Show prompt' }).click();\nawait expect(page.getByRole('status')).toHaveText('You entered: Playwright');\n\nconst downloadPromise = page.waitForEvent('download');\nawait page.getByRole('link', { name: 'Export CSV' }).click();\nconst download = await downloadPromise;\n```\n\n```py\npage.once(\"dialog\", lambda dialog: dialog.accept(\"Playwright\"))\npage.get_by_role(\"button\", name=\"Show prompt\").click()\nexpect(page.get_by_role(\"status\")).to_have_text(\"You entered: Playwright\")\n\nwith page.expect_download() as download_info:\n    page.get_by_role(\"link\", name=\"Export CSV\").click()\ndownload = download_info.value\n```", "watchOut": "Handler or waiter first, trigger second. Registering after the click is too late.", "demos": [], "raw": "\n## Explanation\n### Dialogs\n`alert`, `confirm` and `prompt` dialogs are **dismissed automatically** unless you handle them. Register a handler **before** the action that opens the dialog:\n\n`page.on('dialog', d => d.accept())` — or `page.once` for a single dialog. `accept(text)` answers a prompt; `dismiss()` cancels. `dialog.message()` and `dialog.type()` describe it.\n\n### New tabs (popups)\nStart waiting, *then* trigger: `const popupPromise = page.waitForEvent('popup'); await link.click(); const popup = await popupPromise;`. Python uses a context manager: `with page.expect_popup() as info: …` then `info.value`.\n\n### Downloads\nSame pattern with `'download'` (`page.expect_download()` in Python), then `download.saveAs(path)` or `download.suggestedFilename()`.\n\n### Console and errors\n`page.on('console', msg => …)` collects console messages; `page.on('pageerror', err => …)` catches uncaught exceptions.\n\n## Example\n```js\npage.once('dialog', dialog => dialog.accept('Playwright'));\nawait page.getByRole('button', { name: 'Show prompt' }).click();\nawait expect(page.getByRole('status')).toHaveText('You entered: Playwright');\n\nconst downloadPromise = page.waitForEvent('download');\nawait page.getByRole('link', { name: 'Export CSV' }).click();\nconst download = await downloadPromise;\n```\n\n```py\npage.once(\"dialog\", lambda dialog: dialog.accept(\"Playwright\"))\npage.get_by_role(\"button\", name=\"Show prompt\").click()\nexpect(page.get_by_role(\"status\")).to_have_text(\"You entered: Playwright\")\n\nwith page.expect_download() as download_info:\n    page.get_by_role(\"link\", name=\"Export CSV\").click()\ndownload = download_info.value\n```\n\n## Watch out\nHandler or waiter first, trigger second. Registering after the click is too late.\n"}, "4.1": {"front": {"topic": "4.1", "title": "Web-first assertions", "objective": "Assert page and element state with auto-retrying expect matchers.", "level": "Understand", "minutes": 14, "activities": ["sorted-list"]}, "explanation": "**Web-first assertions** take a locator or the page and **retry** until the condition is true or the assertion timeout (5 s by default) passes. They are the right way to check anything on screen.\n\n### Common matchers\n- Element state: `toBeVisible`, `toBeHidden`, `toBeEnabled`, `toBeDisabled`, `toBeChecked`, `toBeEditable`, `toBeFocused`\n- Content: `toHaveText`, `toContainText`, `toHaveValue`, `toHaveAttribute`, `toHaveClass`, `toHaveCount`\n- Page: `toHaveURL`, `toHaveTitle`\n- API response: `toBeOK`\n\n### toHaveText vs toContainText\n`toHaveText('Total: $9.99')` needs the **whole** text (whitespace normalised). `toContainText('$9.99')` accepts a **substring**. Both take a regular expression, and both take an **array** to check every element of a list in order.\n\n### The non-retrying trap\n`expect(await loc.textContent()).toBe('1')` reads the text **once**. If the page has not updated yet, it fails. Generic matchers (`toBe`, `toEqual`) are for plain values such as API data — not for the live page.", "example": {"js": "await expect(page.getByTestId('cart-badge')).toHaveText('2');\nawait expect(page.getByRole('alert')).toContainText('locked out');\nawait expect(page.getByLabel('Email')).toHaveValue('qa@example.com');\nawait expect(page.getByRole('heading', { level: 3 })).toHaveText(['Baby Onesie', 'Bike Light', /Tee/, 'Trail Backpack', 'Rain Shell', 'Fleece Jacket']);", "py": "expect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"2\")\nexpect(page.get_by_role(\"alert\")).to_contain_text(\"locked out\")\nexpect(page.get_by_label(\"Email\")).to_have_value(\"qa@example.com\")\nexpect(page.get_by_role(\"heading\", level=3)).to_have_text([\"Baby Onesie\", \"Bike Light\", re.compile(\"Tee\"), \"Trail Backpack\", \"Rain Shell\", \"Fleece Jacket\"])"}, "exampleMd": "```js\nawait expect(page.getByTestId('cart-badge')).toHaveText('2');\nawait expect(page.getByRole('alert')).toContainText('locked out');\nawait expect(page.getByLabel('Email')).toHaveValue('qa@example.com');\nawait expect(page.getByRole('heading', { level: 3 })).toHaveText(['Baby Onesie', 'Bike Light', /Tee/, 'Trail Backpack', 'Rain Shell', 'Fleece Jacket']);\n```\n\n```py\nexpect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"2\")\nexpect(page.get_by_role(\"alert\")).to_contain_text(\"locked out\")\nexpect(page.get_by_label(\"Email\")).to_have_value(\"qa@example.com\")\nexpect(page.get_by_role(\"heading\", level=3)).to_have_text([\"Baby Onesie\", \"Bike Light\", re.compile(\"Tee\"), \"Trail Backpack\", \"Rain Shell\", \"Fleece Jacket\"])\n```", "watchOut": "If you `await` inside `expect(...)` you have probably written a non-retrying assertion.", "demos": [], "raw": "\n## Explanation\n**Web-first assertions** take a locator or the page and **retry** until the condition is true or the assertion timeout (5 s by default) passes. They are the right way to check anything on screen.\n\n### Common matchers\n- Element state: `toBeVisible`, `toBeHidden`, `toBeEnabled`, `toBeDisabled`, `toBeChecked`, `toBeEditable`, `toBeFocused`\n- Content: `toHaveText`, `toContainText`, `toHaveValue`, `toHaveAttribute`, `toHaveClass`, `toHaveCount`\n- Page: `toHaveURL`, `toHaveTitle`\n- API response: `toBeOK`\n\n### toHaveText vs toContainText\n`toHaveText('Total: $9.99')` needs the **whole** text (whitespace normalised). `toContainText('$9.99')` accepts a **substring**. Both take a regular expression, and both take an **array** to check every element of a list in order.\n\n### The non-retrying trap\n`expect(await loc.textContent()).toBe('1')` reads the text **once**. If the page has not updated yet, it fails. Generic matchers (`toBe`, `toEqual`) are for plain values such as API data — not for the live page.\n\n## Example\n```js\nawait expect(page.getByTestId('cart-badge')).toHaveText('2');\nawait expect(page.getByRole('alert')).toContainText('locked out');\nawait expect(page.getByLabel('Email')).toHaveValue('qa@example.com');\nawait expect(page.getByRole('heading', { level: 3 })).toHaveText(['Baby Onesie', 'Bike Light', /Tee/, 'Trail Backpack', 'Rain Shell', 'Fleece Jacket']);\n```\n\n```py\nexpect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"2\")\nexpect(page.get_by_role(\"alert\")).to_contain_text(\"locked out\")\nexpect(page.get_by_label(\"Email\")).to_have_value(\"qa@example.com\")\nexpect(page.get_by_role(\"heading\", level=3)).to_have_text([\"Baby Onesie\", \"Bike Light\", re.compile(\"Tee\"), \"Trail Backpack\", \"Rain Shell\", \"Fleece Jacket\"])\n```\n\n## Watch out\nIf you `await` inside `expect(...)` you have probably written a non-retrying assertion.\n"}, "4.2": {"front": {"topic": "4.2", "title": "Auto-waiting and actionability", "objective": "Explain the checks Playwright performs before each action.", "level": "Understand", "minutes": 12, "activities": ["auto-wait"]}, "explanation": "Before an action, Playwright runs **actionability checks** and waits until they pass:\n\n| Action | Checks |\n|---|---|\n| click, dblclick, hover, check | attached, **visible**, **stable** (not animating), **receives events** (not covered), **enabled** |\n| fill, clear | attached, visible, **enabled**, **editable** |\n| press | attached |\n\nIf a check never passes, the action fails when the timeout is reached, and the error log says which check failed — for example *element is not enabled* or *element intercepts pointer events*.\n\n### What this removes\n- `waitForSelector` before clicks — not needed.\n- Sleeps while a button becomes enabled — not needed.\n- Waiting for navigation after a click — the next step waits.\n\n### Escape hatch\n`force: true` skips the checks. It can hide real bugs such as an overlay blocking users, so treat it as a last resort.", "example": {"js": "// The button is disabled for 3 seconds. No sleep needed:\nawait page.getByRole('button', { name: 'Click me' }).click();\nawait expect(page.locator('#late-msg')).toHaveText('Clicked!');", "py": "# The button is disabled for 3 seconds. No sleep needed:\npage.get_by_role(\"button\", name=\"Click me\").click()\nexpect(page.locator(\"#late-msg\")).to_have_text(\"Clicked!\")"}, "exampleMd": "```js\n// The button is disabled for 3 seconds. No sleep needed:\nawait page.getByRole('button', { name: 'Click me' }).click();\nawait expect(page.locator('#late-msg')).toHaveText('Clicked!');\n```\n\n```py\n# The button is disabled for 3 seconds. No sleep needed:\npage.get_by_role(\"button\", name=\"Click me\").click()\nexpect(page.locator(\"#late-msg\")).to_have_text(\"Clicked!\")\n```", "watchOut": "\"Receives events\" fails when another element sits on top — typical with cookie banners and modal overlays.", "demos": [], "raw": "\n## Explanation\nBefore an action, Playwright runs **actionability checks** and waits until they pass:\n\n| Action | Checks |\n|---|---|\n| click, dblclick, hover, check | attached, **visible**, **stable** (not animating), **receives events** (not covered), **enabled** |\n| fill, clear | attached, visible, **enabled**, **editable** |\n| press | attached |\n\nIf a check never passes, the action fails when the timeout is reached, and the error log says which check failed — for example *element is not enabled* or *element intercepts pointer events*.\n\n### What this removes\n- `waitForSelector` before clicks — not needed.\n- Sleeps while a button becomes enabled — not needed.\n- Waiting for navigation after a click — the next step waits.\n\n### Escape hatch\n`force: true` skips the checks. It can hide real bugs such as an overlay blocking users, so treat it as a last resort.\n\n## Example\n```js\n// The button is disabled for 3 seconds. No sleep needed:\nawait page.getByRole('button', { name: 'Click me' }).click();\nawait expect(page.locator('#late-msg')).toHaveText('Clicked!');\n```\n\n```py\n# The button is disabled for 3 seconds. No sleep needed:\npage.get_by_role(\"button\", name=\"Click me\").click()\nexpect(page.locator(\"#late-msg\")).to_have_text(\"Clicked!\")\n```\n\n## Watch out\n\"Receives events\" fails when another element sits on top — typical with cookie banners and modal overlays.\n"}, "4.3": {"front": {"topic": "4.3", "title": "Timeouts, negation and soft assertions", "objective": "Adjust timeouts and use negated and soft assertions correctly.", "level": "Understand", "minutes": 12, "activities": ["timeouts"]}, "explanation": "### Timeout layers (Playwright Test defaults)\n- **Test timeout**: 30 s for the whole test, including hooks. Change with `timeout` in config or `test.setTimeout(ms)`. `test.slow()` triples it.\n- **Assertion timeout**: 5 s. Change globally with `expect: { timeout }` in config, or per call: `toHaveText('x', { timeout: 10_000 })`.\n- **Action / navigation timeouts**: unlimited by default (bounded by the test timeout); set `actionTimeout` / `navigationTimeout` under `use`.\n\nPython: pass `timeout=` to an assertion or action, or call `expect.set_options(timeout=10_000)`.\n\n### Negation\n`expect(loc).not.toBeVisible()` (Python `not_to_be_visible()`) **waits** until the element is not visible. `toBeHidden()` is equivalent and reads better.\n\n### Soft assertions\n`expect.soft(...)` records a failure but lets the test continue, so one run reports several problems. The test is still marked failed at the end. Soft assertions are a Playwright Test feature.", "example": {"js": "await page.getByRole('button', { name: 'Generate report' }).click();\nawait expect(page.getByRole('status')).toHaveText('Report ready', { timeout: 10_000 });\nawait expect(page.getByText('Loading…')).toBeHidden();\nawait expect.soft(page.getByTestId('total')).toContainText('$53.99');", "py": "page.get_by_role(\"button\", name=\"Generate report\").click()\nexpect(page.get_by_role(\"status\")).to_have_text(\"Report ready\", timeout=10_000)\nexpect(page.get_by_text(\"Loading…\")).to_be_hidden()\nexpect(page.get_by_text(\"Loading…\")).not_to_be_visible()"}, "exampleMd": "```js\nawait page.getByRole('button', { name: 'Generate report' }).click();\nawait expect(page.getByRole('status')).toHaveText('Report ready', { timeout: 10_000 });\nawait expect(page.getByText('Loading…')).toBeHidden();\nawait expect.soft(page.getByTestId('total')).toContainText('$53.99');\n```\n\n```py\npage.get_by_role(\"button\", name=\"Generate report\").click()\nexpect(page.get_by_role(\"status\")).to_have_text(\"Report ready\", timeout=10_000)\nexpect(page.get_by_text(\"Loading…\")).to_be_hidden()\nexpect(page.get_by_text(\"Loading…\")).not_to_be_visible()\n```", "watchOut": "Raise the timeout for the one slow step, not for the whole suite.", "demos": [], "raw": "\n## Explanation\n### Timeout layers (Playwright Test defaults)\n- **Test timeout**: 30 s for the whole test, including hooks. Change with `timeout` in config or `test.setTimeout(ms)`. `test.slow()` triples it.\n- **Assertion timeout**: 5 s. Change globally with `expect: { timeout }` in config, or per call: `toHaveText('x', { timeout: 10_000 })`.\n- **Action / navigation timeouts**: unlimited by default (bounded by the test timeout); set `actionTimeout` / `navigationTimeout` under `use`.\n\nPython: pass `timeout=` to an assertion or action, or call `expect.set_options(timeout=10_000)`.\n\n### Negation\n`expect(loc).not.toBeVisible()` (Python `not_to_be_visible()`) **waits** until the element is not visible. `toBeHidden()` is equivalent and reads better.\n\n### Soft assertions\n`expect.soft(...)` records a failure but lets the test continue, so one run reports several problems. The test is still marked failed at the end. Soft assertions are a Playwright Test feature.\n\n## Example\n```js\nawait page.getByRole('button', { name: 'Generate report' }).click();\nawait expect(page.getByRole('status')).toHaveText('Report ready', { timeout: 10_000 });\nawait expect(page.getByText('Loading…')).toBeHidden();\nawait expect.soft(page.getByTestId('total')).toContainText('$53.99');\n```\n\n```py\npage.get_by_role(\"button\", name=\"Generate report\").click()\nexpect(page.get_by_role(\"status\")).to_have_text(\"Report ready\", timeout=10_000)\nexpect(page.get_by_text(\"Loading…\")).to_be_hidden()\nexpect(page.get_by_text(\"Loading…\")).not_to_be_visible()\n```\n\n## Watch out\nRaise the timeout for the one slow step, not for the whole suite.\n"}, "4.4": {"front": {"topic": "4.4", "title": "Writing stable tests", "objective": "Identify common causes of flaky tests and apply the fixes.", "level": "Understand", "minutes": 14, "activities": ["fix-flaky"]}, "explanation": "A **flaky** test sometimes passes and sometimes fails with no code change. Flakiness destroys trust in a suite, so remove its causes:\n\n- **Fixed sleeps** (`waitForTimeout`, `time.sleep`) — too short on a slow day, wasteful on a fast one. Wait for a condition with a web-first assertion instead.\n- **Brittle locators** — positional CSS (`li:nth-child(2)`), generated class names. Use roles, labels and filters.\n- **Non-retrying checks** of live UI (`expect(await …).toBe`). Use `toHaveText` and friends.\n- **Shared state** — tests reusing one account or one record collide in parallel. Give each test its own data.\n- **Order dependence** — test B relies on test A. Every test must set up what it needs.\n- **Unstable dependencies** — third-party services, real payment sandboxes. Mock them with `page.route`.\n\n### Retries are a safety net\n`retries: 2` reruns failed tests. A test that fails then passes is reported as **flaky** — a signal to investigate, not a fix. Combine with `trace: 'on-first-retry'` to capture what went wrong.", "example": {"js": "// fragile\nawait page.waitForTimeout(3000);\nawait page.locator('.products li:nth-child(2) button').click();\n\n// stable\nawait page.getByTestId('product').filter({ hasText: 'Bike Light' })\n  .getByRole('button', { name: 'Add to cart' }).click();\nawait expect(page.getByTestId('cart-badge')).toHaveText('1');", "py": "# fragile\npage.wait_for_timeout(3000)\npage.locator(\".products li:nth-child(2) button\").click()\n\n# stable\npage.get_by_test_id(\"product\").filter(has_text=\"Bike Light\") \\\n    .get_by_role(\"button\", name=\"Add to cart\").click()\nexpect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"1\")"}, "exampleMd": "```js\n// fragile\nawait page.waitForTimeout(3000);\nawait page.locator('.products li:nth-child(2) button').click();\n\n// stable\nawait page.getByTestId('product').filter({ hasText: 'Bike Light' })\n  .getByRole('button', { name: 'Add to cart' }).click();\nawait expect(page.getByTestId('cart-badge')).toHaveText('1');\n```\n\n```py\n# fragile\npage.wait_for_timeout(3000)\npage.locator(\".products li:nth-child(2) button\").click()\n\n# stable\npage.get_by_test_id(\"product\").filter(has_text=\"Bike Light\") \\\n    .get_by_role(\"button\", name=\"Add to cart\").click()\nexpect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"1\")\n```", "watchOut": "\"Flaky\" in the report means it failed, then passed on retry.", "demos": [], "raw": "\n## Explanation\nA **flaky** test sometimes passes and sometimes fails with no code change. Flakiness destroys trust in a suite, so remove its causes:\n\n- **Fixed sleeps** (`waitForTimeout`, `time.sleep`) — too short on a slow day, wasteful on a fast one. Wait for a condition with a web-first assertion instead.\n- **Brittle locators** — positional CSS (`li:nth-child(2)`), generated class names. Use roles, labels and filters.\n- **Non-retrying checks** of live UI (`expect(await …).toBe`). Use `toHaveText` and friends.\n- **Shared state** — tests reusing one account or one record collide in parallel. Give each test its own data.\n- **Order dependence** — test B relies on test A. Every test must set up what it needs.\n- **Unstable dependencies** — third-party services, real payment sandboxes. Mock them with `page.route`.\n\n### Retries are a safety net\n`retries: 2` reruns failed tests. A test that fails then passes is reported as **flaky** — a signal to investigate, not a fix. Combine with `trace: 'on-first-retry'` to capture what went wrong.\n\n## Example\n```js\n// fragile\nawait page.waitForTimeout(3000);\nawait page.locator('.products li:nth-child(2) button').click();\n\n// stable\nawait page.getByTestId('product').filter({ hasText: 'Bike Light' })\n  .getByRole('button', { name: 'Add to cart' }).click();\nawait expect(page.getByTestId('cart-badge')).toHaveText('1');\n```\n\n```py\n# fragile\npage.wait_for_timeout(3000)\npage.locator(\".products li:nth-child(2) button\").click()\n\n# stable\npage.get_by_test_id(\"product\").filter(has_text=\"Bike Light\") \\\n    .get_by_role(\"button\", name=\"Add to cart\").click()\nexpect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"1\")\n```\n\n## Watch out\n\"Flaky\" in the report means it failed, then passed on retry.\n"}, "5.1": {"front": {"topic": "5.1", "title": "Hooks and grouping", "objective": "Group tests and share setup with hooks, tags, skip and only.", "level": "Understand", "minutes": 12, "activities": ["hooks"]}, "explanation": "### Playwright Test\n- `test.describe(name, fn)` groups tests; groups can nest.\n- `test.beforeEach` / `test.afterEach` run before / after **every** test in the group (outer hooks first).\n- `test.beforeAll` / `test.afterAll` run **once per worker** for the group — not for the page fixture, which is per test.\n- `test.only` runs only marked tests (set `forbidOnly: !!process.env.CI` so it never reaches CI). `test.skip`, `test.fixme` and `test.fail` annotate tests.\n- **Tags** in titles or the `tag` option (`@smoke`) are selected with `--grep @smoke` or excluded with `--grep-invert`.\n\n### pytest\n- Setup lives in **fixtures**. `@pytest.fixture(autouse=True)` runs for every test in its scope — the closest match to `beforeEach`.\n- Group with modules or classes; select with `-k` or **markers**: `@pytest.mark.smoke` + `pytest -m smoke`.\n- `@pytest.mark.skip`, `@pytest.mark.parametrize` for data-driven tests.", "example": {"js": "test.describe('logged-in user', () => {\n  test.beforeEach(async ({ page }) => {\n    await page.goto('https://shop.test/');\n    // …log in\n  });\n\n  test('can add an item @smoke', async ({ page }) => { /* … */ });\n  test.skip('wishlist (not built yet)', async ({ page }) => {});\n});", "py": "import pytest\n\n@pytest.fixture(autouse=True)\ndef log_in(page):\n    page.goto(\"https://shop.test/\")\n    # …log in\n\n@pytest.mark.smoke\ndef test_can_add_an_item(page): ...\n\n@pytest.mark.parametrize(\"user\", [\"standard_user\", \"locked_out_user\"])\ndef test_login(page, user): ..."}, "exampleMd": "```js\ntest.describe('logged-in user', () => {\n  test.beforeEach(async ({ page }) => {\n    await page.goto('https://shop.test/');\n    // …log in\n  });\n\n  test('can add an item @smoke', async ({ page }) => { /* … */ });\n  test.skip('wishlist (not built yet)', async ({ page }) => {});\n});\n```\n\n```py\nimport pytest\n\n@pytest.fixture(autouse=True)\ndef log_in(page):\n    page.goto(\"https://shop.test/\")\n    # …log in\n\n@pytest.mark.smoke\ndef test_can_add_an_item(page): ...\n\n@pytest.mark.parametrize(\"user\", [\"standard_user\", \"locked_out_user\"])\ndef test_login(page, user): ...\n```", "watchOut": "beforeAll is per worker. With 4 workers it can run 4 times.", "demos": [], "raw": "\n## Explanation\n### Playwright Test\n- `test.describe(name, fn)` groups tests; groups can nest.\n- `test.beforeEach` / `test.afterEach` run before / after **every** test in the group (outer hooks first).\n- `test.beforeAll` / `test.afterAll` run **once per worker** for the group — not for the page fixture, which is per test.\n- `test.only` runs only marked tests (set `forbidOnly: !!process.env.CI` so it never reaches CI). `test.skip`, `test.fixme` and `test.fail` annotate tests.\n- **Tags** in titles or the `tag` option (`@smoke`) are selected with `--grep @smoke` or excluded with `--grep-invert`.\n\n### pytest\n- Setup lives in **fixtures**. `@pytest.fixture(autouse=True)` runs for every test in its scope — the closest match to `beforeEach`.\n- Group with modules or classes; select with `-k` or **markers**: `@pytest.mark.smoke` + `pytest -m smoke`.\n- `@pytest.mark.skip`, `@pytest.mark.parametrize` for data-driven tests.\n\n## Example\n```js\ntest.describe('logged-in user', () => {\n  test.beforeEach(async ({ page }) => {\n    await page.goto('https://shop.test/');\n    // …log in\n  });\n\n  test('can add an item @smoke', async ({ page }) => { /* … */ });\n  test.skip('wishlist (not built yet)', async ({ page }) => {});\n});\n```\n\n```py\nimport pytest\n\n@pytest.fixture(autouse=True)\ndef log_in(page):\n    page.goto(\"https://shop.test/\")\n    # …log in\n\n@pytest.mark.smoke\ndef test_can_add_an_item(page): ...\n\n@pytest.mark.parametrize(\"user\", [\"standard_user\", \"locked_out_user\"])\ndef test_login(page, user): ...\n```\n\n## Watch out\nbeforeAll is per worker. With 4 workers it can run 4 times.\n"}, "5.2": {"front": {"topic": "5.2", "title": "Fixtures", "objective": "Use built-in fixtures and write custom fixtures with setup and teardown.", "level": "Understand", "minutes": 16, "activities": ["custom-fixture"]}, "explanation": "A **fixture** provides something a test needs and cleans it up afterwards. Tests ask for fixtures by name.\n\n### Built-in fixtures\nPlaywright Test: `page`, `context`, `browser`, `browserName`, `request`. pytest-playwright: `page`, `context`, `browser`, `browser_name`, `playwright` and more. Each test gets its own `page` in its own `context`.\n\n### Custom fixtures in Playwright Test\n```\nconst test = base.extend({\n  todoPage: async ({ page }, use) => {\n    // setup\n    await use(value);   // the test runs here\n    // teardown\n  },\n});\n```\nFixtures are **on demand**: set up only for tests that use them. Options: `{ auto: true }` runs for every test, `{ scope: 'worker' }` shares one instance per worker.\n\n### Custom fixtures in pytest\nA function decorated with `@pytest.fixture`. Code before `yield` is setup, code after is teardown. `scope=\"session\"` shares it; put shared fixtures in **conftest.py**.", "example": {"js": "import { test as base, expect } from '@playwright/test';\n\nconst test = base.extend({\n  loggedInPage: async ({ page }, use) => {\n    await page.goto('https://shop.test/');\n    // …log in\n    await use(page);\n  },\n});\n\ntest('cart starts empty', async ({ loggedInPage }) => {\n  await expect(loggedInPage.getByTestId('cart-badge')).toBeHidden();\n});", "py": "import pytest\nfrom playwright.sync_api import Page, expect\n\n@pytest.fixture\ndef logged_in_page(page: Page):\n    page.goto(\"https://shop.test/\")\n    # …log in\n    yield page\n    # teardown runs here\n\ndef test_cart_starts_empty(logged_in_page: Page):\n    expect(logged_in_page.get_by_test_id(\"cart-badge\")).to_be_hidden()"}, "exampleMd": "```js\nimport { test as base, expect } from '@playwright/test';\n\nconst test = base.extend({\n  loggedInPage: async ({ page }, use) => {\n    await page.goto('https://shop.test/');\n    // …log in\n    await use(page);\n  },\n});\n\ntest('cart starts empty', async ({ loggedInPage }) => {\n  await expect(loggedInPage.getByTestId('cart-badge')).toBeHidden();\n});\n```\n\n```py\nimport pytest\nfrom playwright.sync_api import Page, expect\n\n@pytest.fixture\ndef logged_in_page(page: Page):\n    page.goto(\"https://shop.test/\")\n    # …log in\n    yield page\n    # teardown runs here\n\ndef test_cart_starts_empty(logged_in_page: Page):\n    expect(logged_in_page.get_by_test_id(\"cart-badge\")).to_be_hidden()\n```", "watchOut": "`await use()` in JS and `yield` in Python mark the same moment: the test runs there.", "demos": [], "raw": "\n## Explanation\nA **fixture** provides something a test needs and cleans it up afterwards. Tests ask for fixtures by name.\n\n### Built-in fixtures\nPlaywright Test: `page`, `context`, `browser`, `browserName`, `request`. pytest-playwright: `page`, `context`, `browser`, `browser_name`, `playwright` and more. Each test gets its own `page` in its own `context`.\n\n### Custom fixtures in Playwright Test\n```\nconst test = base.extend({\n  todoPage: async ({ page }, use) => {\n    // setup\n    await use(value);   // the test runs here\n    // teardown\n  },\n});\n```\nFixtures are **on demand**: set up only for tests that use them. Options: `{ auto: true }` runs for every test, `{ scope: 'worker' }` shares one instance per worker.\n\n### Custom fixtures in pytest\nA function decorated with `@pytest.fixture`. Code before `yield` is setup, code after is teardown. `scope=\"session\"` shares it; put shared fixtures in **conftest.py**.\n\n## Example\n```js\nimport { test as base, expect } from '@playwright/test';\n\nconst test = base.extend({\n  loggedInPage: async ({ page }, use) => {\n    await page.goto('https://shop.test/');\n    // …log in\n    await use(page);\n  },\n});\n\ntest('cart starts empty', async ({ loggedInPage }) => {\n  await expect(loggedInPage.getByTestId('cart-badge')).toBeHidden();\n});\n```\n\n```py\nimport pytest\nfrom playwright.sync_api import Page, expect\n\n@pytest.fixture\ndef logged_in_page(page: Page):\n    page.goto(\"https://shop.test/\")\n    # …log in\n    yield page\n    # teardown runs here\n\ndef test_cart_starts_empty(logged_in_page: Page):\n    expect(logged_in_page.get_by_test_id(\"cart-badge\")).to_be_hidden()\n```\n\n## Watch out\n`await use()` in JS and `yield` in Python mark the same moment: the test runs there.\n"}, "5.3": {"front": {"topic": "5.3", "title": "Page Object Model", "objective": "Structure page objects that keep tests readable and maintainable.", "level": "Understand", "minutes": 14, "activities": ["page-object"]}, "explanation": "The **Page Object Model** puts a page's locators and user actions in one class. Tests then read like a description of behaviour, and a markup change is fixed in **one place**.\n\n### Shape of a page object\n- The constructor receives `page` and creates **locators** (they are lazy, so nothing needs to be loaded yet).\n- Methods represent **user-level actions**: `login(user, password)`, `addToCart(name)`, not `clickButton3()`.\n- Keep most **assertions in the tests**, so each test states what it verifies. Small helpers that return locators for assertions are fine.\n\n### With fixtures\nA fixture can construct the page object and hand it to tests — no `new LoginPage(page)` in every test.\n\n### Avoid over-engineering\nOne class per meaningful page or component is enough. Deep inheritance trees and wrappers around every Playwright call make suites harder to read.", "example": {"js": "class LoginPage {\n  constructor(page) {\n    this.page = page;\n    this.username = page.getByLabel('Username');\n    this.password = page.getByLabel('Password');\n    this.submit = page.getByRole('button', { name: 'Log in' });\n  }\n  async goto() { await this.page.goto('https://shop.test/'); }\n  async login(user, pass) {\n    await this.username.fill(user);\n    await this.password.fill(pass);\n    await this.submit.click();\n  }\n}", "py": "class LoginPage:\n    def __init__(self, page):\n        self.page = page\n        self.username = page.get_by_label(\"Username\")\n        self.password = page.get_by_label(\"Password\")\n        self.submit = page.get_by_role(\"button\", name=\"Log in\")\n\n    def goto(self):\n        self.page.goto(\"https://shop.test/\")\n\n    def login(self, user, password):\n        self.username.fill(user)\n        self.password.fill(password)\n        self.submit.click()"}, "exampleMd": "```js\nclass LoginPage {\n  constructor(page) {\n    this.page = page;\n    this.username = page.getByLabel('Username');\n    this.password = page.getByLabel('Password');\n    this.submit = page.getByRole('button', { name: 'Log in' });\n  }\n  async goto() { await this.page.goto('https://shop.test/'); }\n  async login(user, pass) {\n    await this.username.fill(user);\n    await this.password.fill(pass);\n    await this.submit.click();\n  }\n}\n```\n\n```py\nclass LoginPage:\n    def __init__(self, page):\n        self.page = page\n        self.username = page.get_by_label(\"Username\")\n        self.password = page.get_by_label(\"Password\")\n        self.submit = page.get_by_role(\"button\", name=\"Log in\")\n\n    def goto(self):\n        self.page.goto(\"https://shop.test/\")\n\n    def login(self, user, password):\n        self.username.fill(user)\n        self.password.fill(password)\n        self.submit.click()\n```", "watchOut": "A good method name describes what the user wants, not which element is touched.", "demos": [], "raw": "\n## Explanation\nThe **Page Object Model** puts a page's locators and user actions in one class. Tests then read like a description of behaviour, and a markup change is fixed in **one place**.\n\n### Shape of a page object\n- The constructor receives `page` and creates **locators** (they are lazy, so nothing needs to be loaded yet).\n- Methods represent **user-level actions**: `login(user, password)`, `addToCart(name)`, not `clickButton3()`.\n- Keep most **assertions in the tests**, so each test states what it verifies. Small helpers that return locators for assertions are fine.\n\n### With fixtures\nA fixture can construct the page object and hand it to tests — no `new LoginPage(page)` in every test.\n\n### Avoid over-engineering\nOne class per meaningful page or component is enough. Deep inheritance trees and wrappers around every Playwright call make suites harder to read.\n\n## Example\n```js\nclass LoginPage {\n  constructor(page) {\n    this.page = page;\n    this.username = page.getByLabel('Username');\n    this.password = page.getByLabel('Password');\n    this.submit = page.getByRole('button', { name: 'Log in' });\n  }\n  async goto() { await this.page.goto('https://shop.test/'); }\n  async login(user, pass) {\n    await this.username.fill(user);\n    await this.password.fill(pass);\n    await this.submit.click();\n  }\n}\n```\n\n```py\nclass LoginPage:\n    def __init__(self, page):\n        self.page = page\n        self.username = page.get_by_label(\"Username\")\n        self.password = page.get_by_label(\"Password\")\n        self.submit = page.get_by_role(\"button\", name=\"Log in\")\n\n    def goto(self):\n        self.page.goto(\"https://shop.test/\")\n\n    def login(self, user, password):\n        self.username.fill(user)\n        self.password.fill(password)\n        self.submit.click()\n```\n\n## Watch out\nA good method name describes what the user wants, not which element is touched.\n"}, "5.4": {"front": {"topic": "5.4", "title": "Configuration and projects", "objective": "Configure base URL, retries, reporters, devices and projects.", "level": "Understand", "minutes": 14}, "explanation": "`playwright.config.ts` uses `defineConfig({ … })`. Key settings:\n\n- `testDir`, `timeout`, `expect: { timeout }`\n- `retries`, `workers`, `fullyParallel`, `forbidOnly`\n- `reporter`: `'list'`, `'line'`, `'dot'`, `'html'`, `'json'`, `'junit'`, `'blob'` — or an array of several\n- `use` — options for every test: `baseURL`, `headless`, `viewport`, `locale`, `trace`, `screenshot`, `video`, `storageState`, `testIdAttribute`\n- `projects` — run the same tests with different settings, e.g. `devices['Desktop Chrome']`, `devices['iPhone 13']`; select with `--project`\n- `webServer` — start your app (`command`, `url`) before the tests\n\nRecommended debugging artefacts: `trace: 'on-first-retry'`, `screenshot: 'only-on-failure'`, `video: 'retain-on-failure'`.\n\n### Python\nSettings come from CLI options, usually stored in `pytest.ini` / `pyproject.toml` `addopts` (`--base-url`, `--browser`, `--tracing`). Context options are changed by overriding the `browser_context_args` fixture in conftest.py.", "example": {"js": "import { defineConfig, devices } from '@playwright/test';\n\nexport default defineConfig({\n  testDir: './tests',\n  retries: process.env.CI ? 2 : 0,\n  reporter: [['html'], ['list']],\n  use: { baseURL: 'https://shop.test', trace: 'on-first-retry' },\n  projects: [\n    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },\n    { name: 'mobile', use: { ...devices['iPhone 13'] } },\n  ],\n  webServer: { command: 'npm run start', url: 'http://localhost:3000' },\n});", "py": "# pytest.ini\n# [pytest]\n# addopts = --base-url https://shop.test --browser chromium --tracing retain-on-failure\n\n# conftest.py\nimport pytest\n\n@pytest.fixture(scope=\"session\")\ndef browser_context_args(browser_context_args):\n    return {**browser_context_args, \"locale\": \"en-GB\", \"viewport\": {\"width\": 1280, \"height\": 720}}"}, "exampleMd": "```js\nimport { defineConfig, devices } from '@playwright/test';\n\nexport default defineConfig({\n  testDir: './tests',\n  retries: process.env.CI ? 2 : 0,\n  reporter: [['html'], ['list']],\n  use: { baseURL: 'https://shop.test', trace: 'on-first-retry' },\n  projects: [\n    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },\n    { name: 'mobile', use: { ...devices['iPhone 13'] } },\n  ],\n  webServer: { command: 'npm run start', url: 'http://localhost:3000' },\n});\n```\n\n```py\n# pytest.ini\n# [pytest]\n# addopts = --base-url https://shop.test --browser chromium --tracing retain-on-failure\n\n# conftest.py\nimport pytest\n\n@pytest.fixture(scope=\"session\")\ndef browser_context_args(browser_context_args):\n    return {**browser_context_args, \"locale\": \"en-GB\", \"viewport\": {\"width\": 1280, \"height\": 720}}\n```", "watchOut": "Projects = same tests, different settings. They also express dependencies such as a login setup project.", "demos": [], "raw": "\n## Explanation\n`playwright.config.ts` uses `defineConfig({ … })`. Key settings:\n\n- `testDir`, `timeout`, `expect: { timeout }`\n- `retries`, `workers`, `fullyParallel`, `forbidOnly`\n- `reporter`: `'list'`, `'line'`, `'dot'`, `'html'`, `'json'`, `'junit'`, `'blob'` — or an array of several\n- `use` — options for every test: `baseURL`, `headless`, `viewport`, `locale`, `trace`, `screenshot`, `video`, `storageState`, `testIdAttribute`\n- `projects` — run the same tests with different settings, e.g. `devices['Desktop Chrome']`, `devices['iPhone 13']`; select with `--project`\n- `webServer` — start your app (`command`, `url`) before the tests\n\nRecommended debugging artefacts: `trace: 'on-first-retry'`, `screenshot: 'only-on-failure'`, `video: 'retain-on-failure'`.\n\n### Python\nSettings come from CLI options, usually stored in `pytest.ini` / `pyproject.toml` `addopts` (`--base-url`, `--browser`, `--tracing`). Context options are changed by overriding the `browser_context_args` fixture in conftest.py.\n\n## Example\n```js\nimport { defineConfig, devices } from '@playwright/test';\n\nexport default defineConfig({\n  testDir: './tests',\n  retries: process.env.CI ? 2 : 0,\n  reporter: [['html'], ['list']],\n  use: { baseURL: 'https://shop.test', trace: 'on-first-retry' },\n  projects: [\n    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },\n    { name: 'mobile', use: { ...devices['iPhone 13'] } },\n  ],\n  webServer: { command: 'npm run start', url: 'http://localhost:3000' },\n});\n```\n\n```py\n# pytest.ini\n# [pytest]\n# addopts = --base-url https://shop.test --browser chromium --tracing retain-on-failure\n\n# conftest.py\nimport pytest\n\n@pytest.fixture(scope=\"session\")\ndef browser_context_args(browser_context_args):\n    return {**browser_context_args, \"locale\": \"en-GB\", \"viewport\": {\"width\": 1280, \"height\": 720}}\n```\n\n## Watch out\nProjects = same tests, different settings. They also express dependencies such as a login setup project.\n"}, "6.1": {"front": {"topic": "6.1", "title": "Network mocking", "objective": "Intercept, fulfil, modify and abort network requests.", "level": "Understand", "minutes": 16, "activities": ["mock-network"]}, "explanation": "`page.route(url, handler)` intercepts requests whose URL matches a **glob** (`'**/api/todos'`) or **regular expression**. The handler decides what happens:\n\n- `route.fulfill({ status, json, body, headers })` — respond without contacting the server\n- `route.abort()` — simulate a network failure\n- `route.continue({ headers, postData })` — send it on, optionally modified\n- `route.fetch()` then `route.fulfill({ response, json })` — get the real response and change it\n\nRegister routes **before** the action that triggers the request (often before `goto`). `context.route()` covers every page in the context; `unroute()` removes a handler.\n\n### Why mock?\n- Reach states that are hard to create: empty lists, errors, slow responses\n- Remove unstable third-party services\n- Make tests fast and deterministic\n\nTo *wait* for real traffic instead, use `page.waitForResponse(url)`. Recorded traffic can be replayed with `routeFromHAR`.", "example": {"js": "await page.route('**/api/todos', route => route.fulfill({\n  json: [{ title: 'Mocked', completed: false }],\n}));\nawait page.goto('https://todo.test/');\nawait expect(page.getByTestId('todo-item')).toHaveText('Mocked');\n\n// change the real response\nawait page.route('**/api/todos', async route => {\n  const response = await route.fetch();\n  const json = await response.json();\n  json.push({ title: 'Injected' });\n  await route.fulfill({ response, json });\n});", "py": "page.route(\"**/api/todos\", lambda route: route.fulfill(\n    json=[{\"title\": \"Mocked\", \"completed\": False}]))\npage.goto(\"https://todo.test/\")\nexpect(page.get_by_test_id(\"todo-item\")).to_have_text(\"Mocked\")\n\ndef add_item(route):\n    response = route.fetch()\n    data = response.json()\n    data.append({\"title\": \"Injected\"})\n    route.fulfill(response=response, json=data)\n\npage.route(\"**/api/todos\", add_item)"}, "exampleMd": "```js\nawait page.route('**/api/todos', route => route.fulfill({\n  json: [{ title: 'Mocked', completed: false }],\n}));\nawait page.goto('https://todo.test/');\nawait expect(page.getByTestId('todo-item')).toHaveText('Mocked');\n\n// change the real response\nawait page.route('**/api/todos', async route => {\n  const response = await route.fetch();\n  const json = await response.json();\n  json.push({ title: 'Injected' });\n  await route.fulfill({ response, json });\n});\n```\n\n```py\npage.route(\"**/api/todos\", lambda route: route.fulfill(\n    json=[{\"title\": \"Mocked\", \"completed\": False}]))\npage.goto(\"https://todo.test/\")\nexpect(page.get_by_test_id(\"todo-item\")).to_have_text(\"Mocked\")\n\ndef add_item(route):\n    response = route.fetch()\n    data = response.json()\n    data.append({\"title\": \"Injected\"})\n    route.fulfill(response=response, json=data)\n\npage.route(\"**/api/todos\", add_item)\n```", "watchOut": "A route registered after `goto` misses requests made during page load.", "demos": [], "raw": "\n## Explanation\n`page.route(url, handler)` intercepts requests whose URL matches a **glob** (`'**/api/todos'`) or **regular expression**. The handler decides what happens:\n\n- `route.fulfill({ status, json, body, headers })` — respond without contacting the server\n- `route.abort()` — simulate a network failure\n- `route.continue({ headers, postData })` — send it on, optionally modified\n- `route.fetch()` then `route.fulfill({ response, json })` — get the real response and change it\n\nRegister routes **before** the action that triggers the request (often before `goto`). `context.route()` covers every page in the context; `unroute()` removes a handler.\n\n### Why mock?\n- Reach states that are hard to create: empty lists, errors, slow responses\n- Remove unstable third-party services\n- Make tests fast and deterministic\n\nTo *wait* for real traffic instead, use `page.waitForResponse(url)`. Recorded traffic can be replayed with `routeFromHAR`.\n\n## Example\n```js\nawait page.route('**/api/todos', route => route.fulfill({\n  json: [{ title: 'Mocked', completed: false }],\n}));\nawait page.goto('https://todo.test/');\nawait expect(page.getByTestId('todo-item')).toHaveText('Mocked');\n\n// change the real response\nawait page.route('**/api/todos', async route => {\n  const response = await route.fetch();\n  const json = await response.json();\n  json.push({ title: 'Injected' });\n  await route.fulfill({ response, json });\n});\n```\n\n```py\npage.route(\"**/api/todos\", lambda route: route.fulfill(\n    json=[{\"title\": \"Mocked\", \"completed\": False}]))\npage.goto(\"https://todo.test/\")\nexpect(page.get_by_test_id(\"todo-item\")).to_have_text(\"Mocked\")\n\ndef add_item(route):\n    response = route.fetch()\n    data = response.json()\n    data.append({\"title\": \"Injected\"})\n    route.fulfill(response=response, json=data)\n\npage.route(\"**/api/todos\", add_item)\n```\n\n## Watch out\nA route registered after `goto` misses requests made during page load.\n"}, "6.2": {"front": {"topic": "6.2", "title": "API testing", "objective": "Test REST APIs and use API calls to set up UI tests.", "level": "Understand", "minutes": 14, "activities": ["api-tests"]}, "explanation": "Playwright can test HTTP APIs without a browser.\n\n### Playwright Test\nThe `request` fixture is an **APIRequestContext**. It honours `baseURL` and `extraHTTPHeaders` from the config. Methods: `get`, `post`, `put`, `patch`, `delete`, `fetch`. Options include `data` (JSON body), `form`, `params`, `headers`.\n\nThe response offers `status()`, `ok()` (true for 2xx), `json()`, `text()`, `headers()`. `await expect(response).toBeOK()` asserts a 2xx status with a helpful message.\n\n`page.request` is similar but **shares cookies** with the page's browser context — handy for calling an API as the logged-in user.\n\n### Python\nCreate a context with `playwright.request.new_context(base_url=…)` (often in a fixture) and `dispose()` it afterwards. On the response, `status` and `ok` are **properties**; `json()` is a method.\n\n### API calls in UI tests\nCreating data through the API is much faster than clicking through forms. Use the UI for what you are testing, the API for the setup.", "example": {"js": "test.use({ baseURL: 'https://api.test' });\n\ntest('create a user', async ({ request }) => {\n  const res = await request.post('/users', { data: { name: 'Sana', job: 'Tester' } });\n  expect(res.status()).toBe(201);\n  expect((await res.json()).name).toBe('Sana');\n});", "py": "import pytest\nfrom playwright.sync_api import Playwright, APIRequestContext\n\n@pytest.fixture\ndef api(playwright: Playwright):\n    ctx = playwright.request.new_context(base_url=\"https://api.test\")\n    yield ctx\n    ctx.dispose()\n\ndef test_create_a_user(api: APIRequestContext):\n    res = api.post(\"/users\", data={\"name\": \"Sana\", \"job\": \"Tester\"})\n    assert res.status == 201\n    assert res.json()[\"name\"] == \"Sana\""}, "exampleMd": "```js\ntest.use({ baseURL: 'https://api.test' });\n\ntest('create a user', async ({ request }) => {\n  const res = await request.post('/users', { data: { name: 'Sana', job: 'Tester' } });\n  expect(res.status()).toBe(201);\n  expect((await res.json()).name).toBe('Sana');\n});\n```\n\n```py\nimport pytest\nfrom playwright.sync_api import Playwright, APIRequestContext\n\n@pytest.fixture\ndef api(playwright: Playwright):\n    ctx = playwright.request.new_context(base_url=\"https://api.test\")\n    yield ctx\n    ctx.dispose()\n\ndef test_create_a_user(api: APIRequestContext):\n    res = api.post(\"/users\", data={\"name\": \"Sana\", \"job\": \"Tester\"})\n    assert res.status == 201\n    assert res.json()[\"name\"] == \"Sana\"\n```", "watchOut": "JS: `res.status()` is a method. Python: `res.status` is a property.", "demos": [], "raw": "\n## Explanation\nPlaywright can test HTTP APIs without a browser.\n\n### Playwright Test\nThe `request` fixture is an **APIRequestContext**. It honours `baseURL` and `extraHTTPHeaders` from the config. Methods: `get`, `post`, `put`, `patch`, `delete`, `fetch`. Options include `data` (JSON body), `form`, `params`, `headers`.\n\nThe response offers `status()`, `ok()` (true for 2xx), `json()`, `text()`, `headers()`. `await expect(response).toBeOK()` asserts a 2xx status with a helpful message.\n\n`page.request` is similar but **shares cookies** with the page's browser context — handy for calling an API as the logged-in user.\n\n### Python\nCreate a context with `playwright.request.new_context(base_url=…)` (often in a fixture) and `dispose()` it afterwards. On the response, `status` and `ok` are **properties**; `json()` is a method.\n\n### API calls in UI tests\nCreating data through the API is much faster than clicking through forms. Use the UI for what you are testing, the API for the setup.\n\n## Example\n```js\ntest.use({ baseURL: 'https://api.test' });\n\ntest('create a user', async ({ request }) => {\n  const res = await request.post('/users', { data: { name: 'Sana', job: 'Tester' } });\n  expect(res.status()).toBe(201);\n  expect((await res.json()).name).toBe('Sana');\n});\n```\n\n```py\nimport pytest\nfrom playwright.sync_api import Playwright, APIRequestContext\n\n@pytest.fixture\ndef api(playwright: Playwright):\n    ctx = playwright.request.new_context(base_url=\"https://api.test\")\n    yield ctx\n    ctx.dispose()\n\ndef test_create_a_user(api: APIRequestContext):\n    res = api.post(\"/users\", data={\"name\": \"Sana\", \"job\": \"Tester\"})\n    assert res.status == 201\n    assert res.json()[\"name\"] == \"Sana\"\n```\n\n## Watch out\nJS: `res.status()` is a method. Python: `res.status` is a property.\n"}, "6.3": {"front": {"topic": "6.3", "title": "Authentication and storage state", "objective": "Reuse a logged-in state across tests with storage state and setup projects.", "level": "Understand", "minutes": 14}, "explanation": "Logging in through the UI in every test is slow. Playwright can **save the authenticated state once** and reuse it.\n\n### Storage state\n`context.storageState({ path })` writes **cookies and localStorage** (optionally IndexedDB) to a JSON file. A new context created with `storageState: path` starts already logged in.\n\n### Setup project pattern (Playwright Test)\n1. A test file `auth.setup.ts` logs in and saves `playwright/.auth/user.json`.\n2. A project named `setup` runs that file.\n3. Other projects declare `dependencies: ['setup']` and `use: { storageState: 'playwright/.auth/user.json' }`.\n\nAdd `playwright/.auth` to **.gitignore** — the file holds live session data.\n\n### Variations\n- Different roles (admin, viewer): one state file per role, used by different projects or via `test.use({ storageState })`.\n- Log in through the API instead of the UI for speed.\n- Python: save with `context.storage_state(path=…)` and pass `storage_state` through `browser_context_args`.", "example": {"js": "// auth.setup.ts\nimport { test as setup } from '@playwright/test';\nsetup('authenticate', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  // …log in\n  await page.context().storageState({ path: 'playwright/.auth/user.json' });\n});\n\n// playwright.config.ts (projects)\n// { name: 'setup', testMatch: /.*\\.setup\\.ts/ },\n// { name: 'chromium', dependencies: ['setup'],\n//   use: { storageState: 'playwright/.auth/user.json' } }", "py": "# conftest.py\nimport pytest\n\n@pytest.fixture(scope=\"session\")\ndef browser_context_args(browser_context_args):\n    return {**browser_context_args, \"storage_state\": \"auth/user.json\"}\n\n# created once, e.g. by a script:\n# context.storage_state(path=\"auth/user.json\")"}, "exampleMd": "```js\n// auth.setup.ts\nimport { test as setup } from '@playwright/test';\nsetup('authenticate', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  // …log in\n  await page.context().storageState({ path: 'playwright/.auth/user.json' });\n});\n\n// playwright.config.ts (projects)\n// { name: 'setup', testMatch: /.*\\.setup\\.ts/ },\n// { name: 'chromium', dependencies: ['setup'],\n//   use: { storageState: 'playwright/.auth/user.json' } }\n```\n\n```py\n# conftest.py\nimport pytest\n\n@pytest.fixture(scope=\"session\")\ndef browser_context_args(browser_context_args):\n    return {**browser_context_args, \"storage_state\": \"auth/user.json\"}\n\n# created once, e.g. by a script:\n# context.storage_state(path=\"auth/user.json\")\n```", "watchOut": "Storage state = cookies + localStorage. sessionStorage is not included.", "demos": [], "raw": "\n## Explanation\nLogging in through the UI in every test is slow. Playwright can **save the authenticated state once** and reuse it.\n\n### Storage state\n`context.storageState({ path })` writes **cookies and localStorage** (optionally IndexedDB) to a JSON file. A new context created with `storageState: path` starts already logged in.\n\n### Setup project pattern (Playwright Test)\n1. A test file `auth.setup.ts` logs in and saves `playwright/.auth/user.json`.\n2. A project named `setup` runs that file.\n3. Other projects declare `dependencies: ['setup']` and `use: { storageState: 'playwright/.auth/user.json' }`.\n\nAdd `playwright/.auth` to **.gitignore** — the file holds live session data.\n\n### Variations\n- Different roles (admin, viewer): one state file per role, used by different projects or via `test.use({ storageState })`.\n- Log in through the API instead of the UI for speed.\n- Python: save with `context.storage_state(path=…)` and pass `storage_state` through `browser_context_args`.\n\n## Example\n```js\n// auth.setup.ts\nimport { test as setup } from '@playwright/test';\nsetup('authenticate', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  // …log in\n  await page.context().storageState({ path: 'playwright/.auth/user.json' });\n});\n\n// playwright.config.ts (projects)\n// { name: 'setup', testMatch: /.*\\.setup\\.ts/ },\n// { name: 'chromium', dependencies: ['setup'],\n//   use: { storageState: 'playwright/.auth/user.json' } }\n```\n\n```py\n# conftest.py\nimport pytest\n\n@pytest.fixture(scope=\"session\")\ndef browser_context_args(browser_context_args):\n    return {**browser_context_args, \"storage_state\": \"auth/user.json\"}\n\n# created once, e.g. by a script:\n# context.storage_state(path=\"auth/user.json\")\n```\n\n## Watch out\nStorage state = cookies + localStorage. sessionStorage is not included.\n"}, "6.4": {"front": {"topic": "6.4", "title": "Debugging and tracing", "objective": "Debug failures with the Inspector, UI mode, Trace Viewer and codegen.", "level": "Understand", "minutes": 12}, "explanation": "### Tools\n- **UI mode** (`npx playwright test --ui`) — runs tests in watch mode, lets you time-travel through each step and pick locators.\n- **Inspector** (`--debug`, or `PWDEBUG=1`) — steps through actions one by one. `page.pause()` stops a test and opens it.\n- **Trace Viewer** — a trace contains every action, DOM snapshots before and after, network requests, console logs and source. Record with `trace: 'on-first-retry'` (or `--trace on`), open with `npx playwright show-trace trace.zip` or at trace.playwright.dev.\n- **Codegen** (`npx playwright codegen https://shop.test`) — records your clicks and generates test code with recommended locators.\n- **VS Code extension** — run, debug and record from the editor.\n\n### Python\n`PWDEBUG=1 pytest -s` opens the Inspector; `--tracing retain-on-failure` keeps traces; `playwright show-trace` opens them; `playwright codegen` records.\n\n### Reading a failure\nStart with the error message and call log, then open the trace at the failing step and compare the DOM snapshot with what the test expected.", "example": {"js": "# open a recorded trace\nnpx playwright show-trace test-results/checkout/trace.zip\n\n# generate code by clicking through the app\nnpx playwright codegen https://shop.test\n\n// inside a test: stop here and open the Inspector\nawait page.pause();", "py": "# Inspector + see print output\nPWDEBUG=1 pytest -s -k checkout\n\n# keep traces only for failures\npytest --tracing retain-on-failure\nplaywright show-trace test-results/.../trace.zip\n\n# inside a test\npage.pause()"}, "exampleMd": "```js\n# open a recorded trace\nnpx playwright show-trace test-results/checkout/trace.zip\n\n# generate code by clicking through the app\nnpx playwright codegen https://shop.test\n\n// inside a test: stop here and open the Inspector\nawait page.pause();\n```\n\n```py\n# Inspector + see print output\nPWDEBUG=1 pytest -s -k checkout\n\n# keep traces only for failures\npytest --tracing retain-on-failure\nplaywright show-trace test-results/.../trace.zip\n\n# inside a test\npage.pause()\n```", "watchOut": "The Labs in this app record a trace too — open the Trace tab after a run.", "demos": [], "raw": "\n## Explanation\n### Tools\n- **UI mode** (`npx playwright test --ui`) — runs tests in watch mode, lets you time-travel through each step and pick locators.\n- **Inspector** (`--debug`, or `PWDEBUG=1`) — steps through actions one by one. `page.pause()` stops a test and opens it.\n- **Trace Viewer** — a trace contains every action, DOM snapshots before and after, network requests, console logs and source. Record with `trace: 'on-first-retry'` (or `--trace on`), open with `npx playwright show-trace trace.zip` or at trace.playwright.dev.\n- **Codegen** (`npx playwright codegen https://shop.test`) — records your clicks and generates test code with recommended locators.\n- **VS Code extension** — run, debug and record from the editor.\n\n### Python\n`PWDEBUG=1 pytest -s` opens the Inspector; `--tracing retain-on-failure` keeps traces; `playwright show-trace` opens them; `playwright codegen` records.\n\n### Reading a failure\nStart with the error message and call log, then open the trace at the failing step and compare the DOM snapshot with what the test expected.\n\n## Example\n```js\n# open a recorded trace\nnpx playwright show-trace test-results/checkout/trace.zip\n\n# generate code by clicking through the app\nnpx playwright codegen https://shop.test\n\n// inside a test: stop here and open the Inspector\nawait page.pause();\n```\n\n```py\n# Inspector + see print output\nPWDEBUG=1 pytest -s -k checkout\n\n# keep traces only for failures\npytest --tracing retain-on-failure\nplaywright show-trace test-results/.../trace.zip\n\n# inside a test\npage.pause()\n```\n\n## Watch out\nThe Labs in this app record a trace too — open the Trace tab after a run.\n"}, "6.5": {"front": {"topic": "6.5", "title": "CI and parallel runs", "objective": "Run tests in parallel, shard across machines and configure CI.", "level": "Understand", "minutes": 14}, "explanation": "### Parallelism\nPlaywright Test runs tests in **worker processes**. By default, **files** run in parallel and tests **within a file** run in order. `fullyParallel: true` (or `test.describe.configure({ mode: 'parallel' })`) parallelises individual tests. `workers` sets the count (default: half the CPU cores). Tests must therefore be independent.\n\n### Sharding\nSplit a suite across machines: `npx playwright test --shard=1/4` … `--shard=4/4`. Use the **blob** reporter on each shard and `npx playwright merge-reports` to build one HTML report.\n\n### CI checklist\n- `npm ci` and `npx playwright install --with-deps`\n- `retries: 2` on CI, `forbidOnly: true`, `trace: 'on-first-retry'`\n- upload `playwright-report/` as an artefact\n- the generated config uses `workers: 1` on CI for stability; raise it when the suite is isolated\n- or run inside the official Docker image `mcr.microsoft.com/playwright`\n\n### Python\nUse **pytest-xdist**: `pytest -n auto`. Shard across machines with your CI's matrix and test selection.", "example": {"js": "# .github/workflows/playwright.yml (core steps)\n- run: npm ci\n- run: npx playwright install --with-deps\n- run: npx playwright test --shard=${{ matrix.shard }}/4\n- uses: actions/upload-artifact@v4\n  with: { name: blob-report-${{ matrix.shard }}, path: blob-report }", "py": "# CI steps\npip install -r requirements.txt\nplaywright install --with-deps\npytest -n auto --tracing retain-on-failure"}, "exampleMd": "```js\n# .github/workflows/playwright.yml (core steps)\n- run: npm ci\n- run: npx playwright install --with-deps\n- run: npx playwright test --shard=${{ matrix.shard }}/4\n- uses: actions/upload-artifact@v4\n  with: { name: blob-report-${{ matrix.shard }}, path: blob-report }\n```\n\n```py\n# CI steps\npip install -r requirements.txt\nplaywright install --with-deps\npytest -n auto --tracing retain-on-failure\n```", "watchOut": "Default: files in parallel, tests inside a file sequential.", "demos": [], "raw": "\n## Explanation\n### Parallelism\nPlaywright Test runs tests in **worker processes**. By default, **files** run in parallel and tests **within a file** run in order. `fullyParallel: true` (or `test.describe.configure({ mode: 'parallel' })`) parallelises individual tests. `workers` sets the count (default: half the CPU cores). Tests must therefore be independent.\n\n### Sharding\nSplit a suite across machines: `npx playwright test --shard=1/4` … `--shard=4/4`. Use the **blob** reporter on each shard and `npx playwright merge-reports` to build one HTML report.\n\n### CI checklist\n- `npm ci` and `npx playwright install --with-deps`\n- `retries: 2` on CI, `forbidOnly: true`, `trace: 'on-first-retry'`\n- upload `playwright-report/` as an artefact\n- the generated config uses `workers: 1` on CI for stability; raise it when the suite is isolated\n- or run inside the official Docker image `mcr.microsoft.com/playwright`\n\n### Python\nUse **pytest-xdist**: `pytest -n auto`. Shard across machines with your CI's matrix and test selection.\n\n## Example\n```js\n# .github/workflows/playwright.yml (core steps)\n- run: npm ci\n- run: npx playwright install --with-deps\n- run: npx playwright test --shard=${{ matrix.shard }}/4\n- uses: actions/upload-artifact@v4\n  with: { name: blob-report-${{ matrix.shard }}, path: blob-report }\n```\n\n```py\n# CI steps\npip install -r requirements.txt\nplaywright install --with-deps\npytest -n auto --tracing retain-on-failure\n```\n\n## Watch out\nDefault: files in parallel, tests inside a file sequential.\n"}, "6.6": {"front": {"topic": "6.6", "title": "Visual and cross-browser testing", "objective": "Compare screenshots and emulate devices and browsers.", "level": "Understand", "minutes": 12}, "explanation": "### Visual comparisons (Playwright Test)\n`await expect(page).toHaveScreenshot()` (or on a locator) compares against a stored **baseline**. On the first run there is no baseline: the test **fails** and writes one. Later runs compare pixels.\n\n- `npx playwright test --update-snapshots` refreshes baselines after intended changes.\n- Tolerances: `maxDiffPixels`, `maxDiffPixelRatio`, `threshold`.\n- Stabilise: `mask: [locator]` hides dynamic areas (dates, ads); animations are disabled by default.\n- Baselines are stored **per browser and platform**, because fonts and rendering differ. Generate them in the same environment as CI (Docker helps).\n\nIn Python, `page.screenshot(path=…)` captures images; pixel comparison needs a plugin, since `toHaveScreenshot` belongs to Playwright Test.\n\n### Cross-browser and devices\nProjects run the suite in Chromium, Firefox and WebKit. `devices['iPhone 13']` emulates viewport, user agent, touch and device scale. Context options cover `locale`, `timezoneId`, `colorScheme`, `geolocation` with `permissions`.", "example": {"js": "test('product grid looks right', async ({ page }) => {\n  await page.goto('https://shop.test/inventory');\n  await expect(page).toHaveScreenshot('grid.png', {\n    mask: [page.getByTestId('cart-badge')],\n    maxDiffPixels: 100,\n  });\n});\n\n// config: { name: 'mobile-safari', use: { ...devices['iPhone 13'] } }", "py": "def test_product_grid(page):\n    page.goto(\"https://shop.test/inventory\")\n    page.screenshot(path=\"screens/grid.png\", full_page=True)\n\n# emulate a device from the CLI:\n# pytest --device \"iPhone 13\" --browser webkit"}, "exampleMd": "```js\ntest('product grid looks right', async ({ page }) => {\n  await page.goto('https://shop.test/inventory');\n  await expect(page).toHaveScreenshot('grid.png', {\n    mask: [page.getByTestId('cart-badge')],\n    maxDiffPixels: 100,\n  });\n});\n\n// config: { name: 'mobile-safari', use: { ...devices['iPhone 13'] } }\n```\n\n```py\ndef test_product_grid(page):\n    page.goto(\"https://shop.test/inventory\")\n    page.screenshot(path=\"screens/grid.png\", full_page=True)\n\n# emulate a device from the CLI:\n# pytest --device \"iPhone 13\" --browser webkit\n```", "watchOut": "First run of toHaveScreenshot = failure + new baseline. That is expected behaviour.", "demos": [], "raw": "\n## Explanation\n### Visual comparisons (Playwright Test)\n`await expect(page).toHaveScreenshot()` (or on a locator) compares against a stored **baseline**. On the first run there is no baseline: the test **fails** and writes one. Later runs compare pixels.\n\n- `npx playwright test --update-snapshots` refreshes baselines after intended changes.\n- Tolerances: `maxDiffPixels`, `maxDiffPixelRatio`, `threshold`.\n- Stabilise: `mask: [locator]` hides dynamic areas (dates, ads); animations are disabled by default.\n- Baselines are stored **per browser and platform**, because fonts and rendering differ. Generate them in the same environment as CI (Docker helps).\n\nIn Python, `page.screenshot(path=…)` captures images; pixel comparison needs a plugin, since `toHaveScreenshot` belongs to Playwright Test.\n\n### Cross-browser and devices\nProjects run the suite in Chromium, Firefox and WebKit. `devices['iPhone 13']` emulates viewport, user agent, touch and device scale. Context options cover `locale`, `timezoneId`, `colorScheme`, `geolocation` with `permissions`.\n\n## Example\n```js\ntest('product grid looks right', async ({ page }) => {\n  await page.goto('https://shop.test/inventory');\n  await expect(page).toHaveScreenshot('grid.png', {\n    mask: [page.getByTestId('cart-badge')],\n    maxDiffPixels: 100,\n  });\n});\n\n// config: { name: 'mobile-safari', use: { ...devices['iPhone 13'] } }\n```\n\n```py\ndef test_product_grid(page):\n    page.goto(\"https://shop.test/inventory\")\n    page.screenshot(path=\"screens/grid.png\", full_page=True)\n\n# emulate a device from the CLI:\n# pytest --device \"iPhone 13\" --browser webkit\n```\n\n## Watch out\nFirst run of toHaveScreenshot = failure + new baseline. That is expected behaviour.\n"}}, "questions": [{"id": "1.1-a", "topic": "1.1", "kind": "check", "level": "Understand", "concept": "1.1-a", "variant": null, "stem": "Which browser engines can one Playwright API drive?", "options": ["Chromium, Firefox and WebKit", "Chrome, Edge and Internet Explorer", "Any browser with a WebDriver server", "Chromium only"], "answer": 0, "rationale": ["the three modern engines.", "Internet Explorer is not supported; Chrome and Edge are both Chromium.", "Playwright does not use WebDriver servers.", "Firefox and WebKit are supported too."]}, {"id": "1.1-b", "topic": "1.1", "kind": "check", "level": "Understand", "concept": "1.1-b", "variant": null, "stem": "Which Playwright feature removes most of the need for manual sleeps?", "options": ["Parallel workers across browsers", "Headless mode", "Code generation", "Auto-waiting before actions"], "answer": 3, "rationale": ["Parallelism speeds up runs; it does not handle timing.", "Headless only hides the window.", "Codegen writes code; it does not wait.", "actions wait until elements are ready."]}, {"id": "1.1-c", "topic": "1.1", "kind": "check", "level": "Understand", "concept": "1.1-c", "variant": null, "stem": "Each test gets a fresh browser context. What is the main benefit?", "options": ["Tests can be written in any language", "Tests run faster than they would with one shared context", "Tests are isolated: no shared cookies or storage", "The browser window becomes visible"], "answer": 2, "rationale": ["Language support is unrelated to contexts.", "Speed is not the purpose; isolation is.", "like a new private profile per test.", "Visibility depends on headed mode, not contexts."]}, {"id": "1.2-a", "topic": "1.2", "kind": "check", "level": "Understand", "concept": "1.2-a", "variant": null, "stem": "Which command scaffolds a new Playwright Test project in JavaScript?", "options": ["npx create-playwright-app", "npm init playwright@latest", "npm run playwright setup", "npm install playwright-cli --save-dev"], "answer": 1, "rationale": ["Not the official scaffolding command.", "it runs the setup wizard.", "No such script exists by default.", "Not a real setup command."]}, {"id": "1.2-b", "topic": "1.2", "kind": "check", "level": "Understand", "concept": "1.2-b", "variant": null, "stem": "After `pip install pytest-playwright`, what else is required before tests can launch a browser?", "options": ["Nothing else", "Run `playwright install` to download browsers", "Install Selenium WebDriver", "Create a playwright.config.ts file in the project"], "answer": 1, "rationale": ["Browser binaries are downloaded separately.", "this downloads the browsers.", "Playwright does not use WebDriver.", "That file is for the JavaScript runner."]}, {"id": "1.2-c", "topic": "1.2", "kind": "check", "level": "Understand", "concept": "1.2-c", "variant": null, "stem": "Which file name would pytest collect as a test file by default?", "options": ["test_login.py", "login_tests_suite.py", "login.test.ts", "login.spec.py"], "answer": 0, "rationale": ["test_*.py is collected.", "pytest needs the test_ prefix or _test suffix.", "That is a TypeScript file.", "The .spec naming is a JavaScript convention."]}, {"id": "1.3-a", "topic": "1.3", "kind": "check", "level": "Understand", "concept": "1.3-a", "variant": null, "stem": "Why does JavaScript Playwright code use `await` before actions?", "options": ["To retry failed actions", "Because tests run in parallel", "To slow the test down so each step is visible on screen", "Because Playwright methods return promises"], "answer": 3, "rationale": ["Retries are a config option.", "Parallelism is unrelated to await.", "Slowing down is done with slowMo, not await.", "the API is asynchronous."]}, {"id": "1.3-b", "topic": "1.3", "kind": "check", "level": "Understand", "concept": "1.3-b", "variant": null, "stem": "How does a pytest-playwright test receive a browser page?", "options": ["By decorating the test function with @page", "By calling Page() inside the test", "By declaring a parameter named page", "By importing page from playwright"], "answer": 2, "rationale": ["No such decorator exists.", "Pages come from fixtures, not constructors.", "pytest injects the page fixture.", "There is no importable page object."]}, {"id": "1.3-c", "topic": "1.3", "kind": "check", "level": "Understand", "concept": "1.3-c", "variant": null, "stem": "Which import gives Python tests the `expect` function?", "options": ["from playwright.assertions import check", "from pytest import expect", "from playwright.sync_api import expect", "import expect"], "answer": 2, "rationale": ["No such module or name.", "pytest has no expect function.", "alongside Page.", "expect is not a standalone module."]}, {"id": "1.4-a", "topic": "1.4", "kind": "check", "level": "Understand", "concept": "1.4-a", "variant": null, "stem": "Which command runs only JavaScript tests whose title contains \"login\"?", "options": ["npx playwright test --only login", "npx playwright test -g \"login\"", "npx playwright test -k login", "npx playwright run login"], "answer": 1, "rationale": ["--only is not a CLI flag.", "-g is short for --grep.", "-k is the pytest filter.", "There is no run sub-command."]}, {"id": "1.4-b", "topic": "1.4", "kind": "check", "level": "Understand", "concept": "1.4-b", "variant": null, "stem": "Which command opens the HTML report after a JavaScript run?", "options": ["npx playwright show-report", "npx playwright test --report", "npx playwright report", "npx playwright open-report"], "answer": 0, "rationale": ["", "The reporter is configured, not opened, this way.", "Not a valid command.", "Not a valid command."]}, {"id": "1.4-c", "topic": "1.4", "kind": "check", "level": "Understand", "concept": "1.4-c", "variant": null, "stem": "How do you run pytest-playwright tests in Firefox with a visible window?", "options": ["pytest -b firefox -h", "PLAYWRIGHT=firefox pytest", "pytest --use-firefox --visible-window", "pytest --browser firefox --headed"], "answer": 3, "rationale": ["-h prints pytest help.", "Not how the plugin selects browsers.", "These flags do not exist.", ""]}, {"id": "2.1-a", "topic": "2.1", "kind": "check", "level": "Understand", "concept": "2.1-a", "variant": null, "stem": "Which locator does Playwright recommend trying first?", "options": ["XPath expressions", "locator() with CSS", "getByTestId()", "getByRole()"], "answer": 3, "rationale": ["XPath is the least preferred option.", "CSS ties tests to markup structure.", "Test ids are a fallback when no user-facing option fits.", "role plus accessible name."]}, {"id": "2.1-b", "topic": "2.1", "kind": "check", "level": "Understand", "concept": "2.1-b", "variant": null, "stem": "Given `<label for=\"e\">Email</label><input id=\"e\">`, which locator finds the input by role?", "options": ["getByRole('inputfield', { name: 'Email' })", "getByRole('input', { name: 'Email' })", "getByRole('textbox', { name: 'Email' })", "getByRole('label', { name: 'Email' })"], "answer": 2, "rationale": ["\"inputfield\" is not an ARIA role.", "\"input\" is a tag name, not a role.", "the label supplies the accessible name.", "This targets a label role, which a label element does not have."]}, {"id": "2.1-c", "topic": "2.1", "kind": "check", "level": "Understand", "concept": "2.1-c", "variant": null, "stem": "By default, does `getByRole('button', { name: 'log' })` match a button labelled “Log in”?", "options": ["No, names must match exactly", "Yes — matching is case-insensitive and substring", "Only with { exact: true }", "Only if the button also has an aria-label attribute"], "answer": 1, "rationale": ["Exact matching is opt-in.", "", "exact: true would prevent this match.", "Text content gives the name too."]}, {"id": "2.2-a", "topic": "2.2", "kind": "check", "level": "Understand", "concept": "2.2-a", "variant": null, "stem": "An input has a placeholder \"Search\" but no label. Which locator fits best?", "options": ["getByPlaceholder('Search')", "getByTitle('Search')", "locator('input:nth-child(1)')", "getByText('Search')"], "answer": 0, "rationale": ["", "Only works for a title attribute.", "Positional CSS is brittle.", "Placeholders are not text content."]}, {"id": "2.2-b", "topic": "2.2", "kind": "check", "level": "Understand", "concept": "2.2-b", "variant": null, "stem": "Which attribute does getByTestId use by default?", "options": ["data-testid", "test-id", "id", "data-test-id"], "answer": 0, "rationale": ["", "Not the default attribute.", "Plain ids are matched with CSS, not getByTestId.", "Not the default (the default is data-testid)."]}, {"id": "2.2-c", "topic": "2.2", "kind": "check", "level": "Understand", "concept": "2.2-c", "variant": null, "stem": "Your app uses `data-qa` attributes. How do you make getByTestId use them in Playwright Test?", "options": ["Rename every attribute to data-testid", "It is not possible", "Pass the attribute each time: getByTestId('x', 'data-qa')", "Set use: { testIdAttribute: 'data-qa' } in the config"], "answer": 3, "rationale": ["Unnecessary: the attribute is configurable.", "It is supported through config.", "getByTestId takes only the id.", "configured once."]}, {"id": "2.3-a", "topic": "2.3", "kind": "check", "level": "Understand", "concept": "2.3-a", "variant": null, "stem": "What does `page.getByRole('listitem').filter({ hasText: 'Milk' })` match?", "options": ["List items without \"Milk\"", "The text node \"Milk\"", "List items that contain the text \"Milk\"", "The first list item only"], "answer": 2, "rationale": ["That would be hasNotText.", "filter returns elements, not text nodes.", "", "filter keeps all matches."]}, {"id": "2.3-b", "topic": "2.3", "kind": "check", "level": "Understand", "concept": "2.3-b", "variant": null, "stem": "Why does Playwright discourage CSS and XPath selectors?", "options": ["They are slower to evaluate", "They break when markup structure changes", "They cannot find buttons", "They do not support waiting"], "answer": 1, "rationale": ["Speed is not the concern.", "structure is an implementation detail.", "They can find anything in the DOM.", "All locators auto-wait."]}, {"id": "2.3-c", "topic": "2.3", "kind": "check", "level": "Understand", "concept": "2.3-c", "variant": null, "stem": "What does `filter({ has: page.getByRole('button', { name: 'Buy' }) })` keep?", "options": ["Elements that are Buy buttons", "Elements that contain a Buy button", "Elements that sit next to a Buy button", "Elements without a Buy button"], "answer": 1, "rationale": ["has checks descendants, not the element itself.", "", "Siblings are not considered.", "That is hasNot."]}, {"id": "2.4-a", "topic": "2.4", "kind": "check", "level": "Understand", "concept": "2.4-a", "variant": null, "stem": "A locator matches three buttons and you call click(). What happens?", "options": ["A strict mode violation error is thrown", "Playwright waits for two of them to disappear", "The first button is clicked", "All three are clicked"], "answer": 0, "rationale": ["", "It fails immediately with the list of matches.", "Playwright never guesses.", "Actions target one element."]}, {"id": "2.4-b", "topic": "2.4", "kind": "check", "level": "Understand", "concept": "2.4-b", "variant": null, "stem": "Which element does `nth(1)` select?", "options": ["The last", "A random one", "The first", "The second"], "answer": 3, "rationale": ["That is last() or nth(-1).", "Selection is deterministic.", "That is nth(0) or first().", "indexing is zero-based."]}, {"id": "2.4-c", "topic": "2.4", "kind": "check", "level": "Understand", "concept": "2.4-c", "variant": null, "stem": "What does \"locators are lazy\" mean?", "options": ["They cache the first element they find on the page", "They are slow to create", "They are resolved each time they are used", "They only work after page load"], "answer": 2, "rationale": ["They do not cache elements.", "Creating a locator is instant.", "always current state.", "They can be created at any time."]}, {"id": "3.1-a", "topic": "3.1", "kind": "check", "level": "Understand", "concept": "3.1-a", "variant": null, "stem": "By default, what does `page.goto()` wait for?", "options": ["Nothing; it returns immediately", "Network idle", "The load event", "All images to finish"], "answer": 2, "rationale": ["It waits for navigation.", "networkidle is opt-in and discouraged.", "", "Images are part of load, but the event is the trigger."]}, {"id": "3.1-b", "topic": "3.1", "kind": "check", "level": "Understand", "concept": "3.1-b", "variant": null, "stem": "How do you right-click an element?", "options": ["locator.rightClick()", "locator.click({ button: 'right' })", "locator.contextMenu()", "page.mouse.right()"], "answer": 1, "rationale": ["No such method.", "", "No such method.", "No such method."]}, {"id": "3.1-c", "topic": "3.1", "kind": "check", "level": "Understand", "concept": "3.1-c", "variant": null, "stem": "What does `click({ force: true })` do?", "options": ["Skips the actionability checks", "Retries until it succeeds", "Clicks even when the page runs in headless mode", "Clicks twice"], "answer": 0, "rationale": ["use sparingly.", "Retries are not involved.", "Clicks always work headless.", "That is clickCount: 2."]}, {"id": "3.2-a", "topic": "3.2", "kind": "check", "level": "Understand", "concept": "3.2-a", "variant": null, "stem": "What is the main difference between `fill()` and `pressSequentially()`?", "options": ["pressSequentially clears the field first", "They are identical", "fill types slower", "fill sets the whole value at once; pressSequentially sends key events per character"], "answer": 3, "rationale": ["fill clears; pressSequentially appends.", "They behave differently.", "fill is the faster one.", ""]}, {"id": "3.2-b", "topic": "3.2", "kind": "check", "level": "Understand", "concept": "3.2-b", "variant": null, "stem": "What does `selectOption({ label: 'Pakistan' })` choose?", "options": ["The option with id \"Pakistan\"", "The first option", "The option whose value attribute is \"Pakistan\"", "The option whose visible text is \"Pakistan\""], "answer": 3, "rationale": ["Ids are not used.", "It selects the matching option.", "That would be { value }.", ""]}, {"id": "3.2-c", "topic": "3.2", "kind": "check", "level": "Understand", "concept": "3.2-c", "variant": null, "stem": "Which method uploads a file to `<input type=\"file\">`?", "options": ["upload()", "fill() with the file path", "setInputFiles()", "attach()"], "answer": 2, "rationale": ["No such method.", "fill cannot set files.", "", "No such method."]}, {"id": "3.3-a", "topic": "3.3", "kind": "check", "level": "Understand", "concept": "3.3-a", "variant": null, "stem": "How do you press Shift and A together on a focused input?", "options": ["press('Shift A')", "press('Shift+A')", "press(['Shift','A'])", "pressShift('A')"], "answer": 1, "rationale": ["Keys are joined with +.", "", "press takes a string.", "No such method."]}, {"id": "3.3-b", "topic": "3.3", "kind": "check", "level": "Understand", "concept": "3.3-b", "variant": null, "stem": "A submenu appears only while the pointer is over \"Account\". What do you call first?", "options": ["hover()", "focus()", "dispatchEvent(\"show\")", "click({ force: true })"], "answer": 0, "rationale": ["", "Focus does not trigger hover handlers.", "Synthetic events bypass real interaction.", "Forcing clicks hides the real behaviour."]}, {"id": "3.3-c", "topic": "3.3", "kind": "check", "level": "Understand", "concept": "3.3-c", "variant": null, "stem": "Which method drags one element onto another?", "options": ["dragTo()", "moveTo()", "drop()", "mouse.drag()"], "answer": 0, "rationale": ["", "No such locator method.", "No such method.", "No such method."]}, {"id": "3.4-a", "topic": "3.4", "kind": "check", "level": "Understand", "concept": "3.4-a", "variant": null, "stem": "What happens to a confirm() dialog when no dialog handler is registered?", "options": ["The test fails immediately", "The test hangs until timeout", "It is accepted automatically (OK pressed)", "It is dismissed automatically"], "answer": 3, "rationale": ["No error is raised by default.", "Playwright does not hang on unhandled dialogs.", "Default behaviour is to dismiss.", ""]}, {"id": "3.4-b", "topic": "3.4", "kind": "check", "level": "Understand", "concept": "3.4-b", "variant": null, "stem": "When must the dialog handler be registered?", "options": ["Any time before the test ends", "After the click, once the dialog is on screen", "Before the action that opens the dialog", "In playwright.config.ts"], "answer": 2, "rationale": ["It must exist when the dialog appears.", "By then the dialog has already been dismissed.", "", "Handlers are registered on the page."]}, {"id": "3.4-c", "topic": "3.4", "kind": "check", "level": "Understand", "concept": "3.4-c", "variant": null, "stem": "What is the correct order to catch a new tab opened by a link?", "options": ["Click, then call waitForEvent(\"popup\")", "Start waitForEvent(\"popup\"), click, then await the promise", "Call page.newTab() before clicking", "Use page.on(\"tab\")"], "answer": 1, "rationale": ["The event may fire before you start waiting.", "", "No such method.", "The event is called popup."]}, {"id": "4.1-a", "topic": "4.1", "kind": "check", "level": "Understand", "concept": "4.1-a", "variant": null, "stem": "What is the difference between toHaveText and toContainText?", "options": ["toHaveText is case-insensitive", "toHaveText needs the full text; toContainText accepts a substring", "toContainText does not retry", "There is no difference"], "answer": 1, "rationale": ["Both are case-sensitive for strings.", "", "Both retry.", "They differ in matching."]}, {"id": "4.1-b", "topic": "4.1", "kind": "check", "level": "Understand", "concept": "4.1-b", "variant": null, "stem": "What is wrong with `expect(await badge.textContent()).toBe('1')`?", "options": ["It reads the value once and does not retry", "toBe cannot compare strings, only numbers and booleans", "Nothing; it is the recommended style", "textContent does not exist"], "answer": 0, "rationale": ["use toHaveText instead.", "toBe compares strings fine.", "Web-first assertions are recommended.", "It exists, but returns a snapshot."]}, {"id": "4.1-c", "topic": "4.1", "kind": "check", "level": "Understand", "concept": "4.1-c", "variant": null, "stem": "What is the default timeout of a web-first assertion?", "options": ["30 seconds", "No timeout", "1 second", "5 seconds"], "answer": 3, "rationale": ["That is the default test timeout.", "Assertions always have a timeout.", "Too short; not the default.", ""]}, {"id": "4.2-a", "topic": "4.2", "kind": "check", "level": "Understand", "concept": "4.2-a", "variant": null, "stem": "Which checks does Playwright perform before a click?", "options": ["That the network is idle", "Only that the element exists", "Visible, stable, receives events, enabled", "Editable and focused"], "answer": 2, "rationale": ["Network state is not an actionability check.", "It checks much more than existence.", "", "Editable is checked for fill, not click."]}, {"id": "4.2-b", "topic": "4.2", "kind": "check", "level": "Understand", "concept": "4.2-b", "variant": null, "stem": "A button is disabled for 2 seconds after page load. What does `click()` do?", "options": ["Fails immediately", "Clicks the disabled button", "Waits until it is enabled, then clicks", "Reloads the page"], "answer": 2, "rationale": ["It waits within the timeout.", "Disabled elements are not clicked.", "", "No reload happens."]}, {"id": "4.2-c", "topic": "4.2", "kind": "check", "level": "Understand", "concept": "4.2-c", "variant": null, "stem": "A modal overlay covers a button. Which check keeps the click waiting?", "options": ["Stable", "Receives events", "Enabled and editable", "Visible"], "answer": 1, "rationale": ["Stable is about movement.", "another element would get the click.", "Enabled and editable apply to form controls, not overlays.", "The button may still be visible."]}, {"id": "4.3-a", "topic": "4.3", "kind": "check", "level": "Understand", "concept": "4.3-a", "variant": null, "stem": "What is the default test timeout in Playwright Test?", "options": ["30 seconds", "60 seconds (one minute)", "5 seconds", "10 seconds"], "answer": 0, "rationale": ["", "Not the default.", "That is the assertion timeout.", "Not a default."]}, {"id": "4.3-b", "topic": "4.3", "kind": "check", "level": "Understand", "concept": "4.3-b", "variant": null, "stem": "How does expect.soft() behave when it fails?", "options": ["It retries the test", "It stops the test immediately", "It ignores the failure completely", "It records the failure and lets the test continue"], "answer": 3, "rationale": ["Retries are separate.", "That is a normal assertion.", "The test still fails at the end.", ""]}, {"id": "4.3-c", "topic": "4.3", "kind": "check", "level": "Understand", "concept": "4.3-c", "variant": null, "stem": "What does `await expect(loc).not.toBeVisible()` do?", "options": ["Fails if the element exists in the DOM", "Hides the element", "Checks once that the element is hidden", "Waits until the element is not visible, up to the timeout"], "answer": 3, "rationale": ["Hidden elements in the DOM pass.", "Assertions never change the page.", "Negated assertions retry too.", ""]}, {"id": "4.4-a", "topic": "4.4", "kind": "check", "level": "Understand", "concept": "4.4-a", "variant": null, "stem": "Which is the most reliable replacement for `waitForTimeout(3000)` before checking a success message?", "options": ["Increasing the test timeout in the config", "waitForTimeout(5000)", "expect(message).toBeVisible()", "page.reload()"], "answer": 2, "rationale": ["Timeout limits waiting; it does not wait for a condition.", "A longer sleep is still a guess.", "waits exactly as long as needed.", "Reloading may lose the message."]}, {"id": "4.4-b", "topic": "4.4", "kind": "check", "level": "Understand", "concept": "4.4-b", "variant": null, "stem": "What does `retries: 2` in the config do?", "options": ["Runs each test twice always", "Reruns failed tests up to twice; pass-on-retry is reported as flaky", "Retries each action twice", "Fixes flaky tests"], "answer": 1, "rationale": ["Only failures are retried.", "", "Actions are not retried individually.", "It only masks symptoms."]}, {"id": "4.4-c", "topic": "4.4", "kind": "check", "level": "Understand", "concept": "4.4-c", "variant": null, "stem": "Tests pass alone but fail in parallel because they edit the same user. What is the cause?", "options": ["Shared state between tests", "Missing await before an action", "Wrong browser", "Too few workers"], "answer": 0, "rationale": ["isolate test data.", "A missing await gives other symptoms, even when run alone.", "Browser choice is unrelated.", "More workers would make it worse."]}, {"id": "5.1-a", "topic": "5.1", "kind": "check", "level": "Understand", "concept": "5.1-a", "variant": null, "stem": "When does test.beforeEach run?", "options": ["Before every test in its scope", "Only before the first test in the file", "After every test", "Once per file"], "answer": 0, "rationale": ["", "That describes beforeAll per worker.", "That is afterEach.", "That is closer to beforeAll."]}, {"id": "5.1-b", "topic": "5.1", "kind": "check", "level": "Understand", "concept": "5.1-b", "variant": null, "stem": "How often does test.beforeAll run?", "options": ["Once per CI build", "Only when --headed is used", "Before every test", "Once per worker process"], "answer": 3, "rationale": ["Each worker runs it separately.", "Unrelated to headed mode.", "That is beforeEach.", ""]}, {"id": "5.1-c", "topic": "5.1", "kind": "check", "level": "Understand", "concept": "5.1-c", "variant": null, "stem": "What does test.only do, and why guard it in CI?", "options": ["Retries a test once", "Runs a test in one browser only", "Runs a test alone; forbidOnly stops it from silently skipping the rest in CI", "Marks a test as required"], "answer": 2, "rationale": ["Retries are separate.", "Projects control browsers.", "", "No such meaning."]}, {"id": "5.2-a", "topic": "5.2", "kind": "check", "level": "Understand", "concept": "5.2-a", "variant": null, "stem": "In a Playwright Test fixture, when does code after `await use(value)` run?", "options": ["Before the test", "After the test, as teardown", "Only if the test fails, to clean up", "Never"], "answer": 1, "rationale": ["Setup comes before use().", "", "Teardown always runs.", "It runs after the test."]}, {"id": "5.2-b", "topic": "5.2", "kind": "check", "level": "Understand", "concept": "5.2-b", "variant": null, "stem": "When is a custom (non-auto) fixture set up?", "options": ["Before every test in the project", "Only for tests that request it", "Once when the config loads", "Only in CI"], "answer": 1, "rationale": ["Only auto fixtures do that.", "fixtures are on demand.", "Fixtures are per test by default.", "Environment is irrelevant."]}, {"id": "5.2-c", "topic": "5.2", "kind": "check", "level": "Understand", "concept": "5.2-c", "variant": null, "stem": "Where do you put pytest fixtures shared by several test files?", "options": ["conftest.py", "__init__.py", "fixtures.json", "pytest.ini"], "answer": 0, "rationale": ["pytest discovers it automatically.", "Not used for fixture sharing.", "Fixtures are Python code.", "That holds settings."]}, {"id": "5.3-a", "topic": "5.3", "kind": "check", "level": "Understand", "concept": "5.3-a", "variant": null, "stem": "What is the main benefit of the Page Object Model?", "options": ["Assertions become optional", "It removes the need for fixtures and test hooks", "Tests run faster", "A locator change is updated in one place"], "answer": 3, "rationale": ["Tests still need assertions.", "They combine well with fixtures.", "Speed is unchanged.", "maintainability."]}, {"id": "5.3-b", "topic": "5.3", "kind": "check", "level": "Understand", "concept": "5.3-b", "variant": null, "stem": "Where should a page object create its locators?", "options": ["Only after page load", "Inside every method call", "In the constructor", "In the config file"], "answer": 2, "rationale": ["Locators can be created before loading.", "Possible but repetitive.", "locators are lazy.", "Config holds settings."]}, {"id": "5.3-c", "topic": "5.3", "kind": "check", "level": "Understand", "concept": "5.3-c", "variant": null, "stem": "Which is the recommended home for most assertions?", "options": ["In afterEach hooks", "Inside page object methods", "In the tests", "In global setup"], "answer": 2, "rationale": ["Hooks are for setup and teardown.", "Hidden assertions make tests unclear.", "tests state what they verify.", "Global setup prepares state."]}, {"id": "5.4-a", "topic": "5.4", "kind": "check", "level": "Understand", "concept": "5.4-a", "variant": null, "stem": "Where do you set baseURL in playwright.config.ts?", "options": ["At the top level as baseUrl", "Inside use: { baseURL }", "Inside projects only", "In package.json"], "answer": 1, "rationale": ["It belongs under use, spelled baseURL.", "", "Projects can override it, but use is the usual place.", "Not a package.json setting."]}, {"id": "5.4-b", "topic": "5.4", "kind": "check", "level": "Understand", "concept": "5.4-b", "variant": null, "stem": "What are projects used for?", "options": ["Running the same tests with different settings, such as browsers or devices", "Storing test data", "Grouping tests into describes", "Splitting code into npm packages"], "answer": 0, "rationale": ["", "Not their purpose.", "describe groups tests.", "Unrelated to npm packages."]}, {"id": "5.4-c", "topic": "5.4", "kind": "check", "level": "Understand", "concept": "5.4-c", "variant": null, "stem": "What does the webServer option do?", "options": ["Proxies network requests", "Runs tests on a remote server", "Hosts the HTML report", "Starts your application before the tests run"], "answer": 3, "rationale": ["Use page.route for that.", "Not its purpose.", "show-report serves the report.", ""]}, {"id": "6.1-a", "topic": "6.1", "kind": "check", "level": "Understand", "concept": "6.1-a", "variant": null, "stem": "What does route.fulfill() do?", "options": ["Blocks the request", "Records the response to a HAR file", "Sends the request to the server unchanged", "Responds with your data without contacting the server"], "answer": 3, "rationale": ["That is abort().", "Recording uses other options.", "That is continue().", ""]}, {"id": "6.1-b", "topic": "6.1", "kind": "check", "level": "Understand", "concept": "6.1-b", "variant": null, "stem": "How do you change one field of the real server response?", "options": ["It is not possible", "route.continue({ json })", "route.fetch(), edit the JSON, then route.fulfill({ response, json })", "page.waitForResponse() then edit it"], "answer": 2, "rationale": ["It is supported.", "continue cannot change the response body.", "", "Waiting does not modify what the page receives."]}, {"id": "6.1-c", "topic": "6.1", "kind": "check", "level": "Understand", "concept": "6.1-c", "variant": null, "stem": "Why register a route before page.goto()?", "options": ["Routes only work on blank pages", "Requests made during page load would otherwise be missed", "goto clears all routes", "It is required by TypeScript"], "answer": 1, "rationale": ["Routes work on any page.", "", "Routes persist across navigations.", "Unrelated to types."]}, {"id": "6.2-a", "topic": "6.2", "kind": "check", "level": "Understand", "concept": "6.2-a", "variant": null, "stem": "For which status codes is response.ok() true?", "options": ["Any 2xx", "Any status below 400", "200 and 304", "Only 200"], "answer": 0, "rationale": ["", "3xx is not ok.", "304 is not ok.", "201 and 204 are ok too."]}, {"id": "6.2-b", "topic": "6.2", "kind": "check", "level": "Understand", "concept": "6.2-b", "variant": null, "stem": "Why create test data through the API in a UI test?", "options": ["It is much faster and less fragile than clicking through forms", "APIs are always mocked", "Playwright requires it", "The UI cannot create data"], "answer": 0, "rationale": ["", "APIs are called for real here.", "Not required.", "The UI can, but slowly."]}, {"id": "6.2-c", "topic": "6.2", "kind": "check", "level": "Understand", "concept": "6.2-c", "variant": null, "stem": "How does page.request differ from the request fixture?", "options": ["page.request ignores baseURL", "They are identical in every way", "page.request cannot send POST", "page.request shares cookies with the page’s browser context"], "answer": 3, "rationale": ["Not the key difference.", "Cookie sharing differs.", "It supports all methods.", ""]}, {"id": "6.3-a", "topic": "6.3", "kind": "check", "level": "Understand", "concept": "6.3-a", "variant": null, "stem": "What does storageState save?", "options": ["Only sessionStorage", "Screenshots and videos", "Cookies and localStorage", "The full browser profile with history"], "answer": 2, "rationale": ["sessionStorage is not included.", "Those are test artefacts.", "", "History is not saved."]}, {"id": "6.3-b", "topic": "6.3", "kind": "check", "level": "Understand", "concept": "6.3-b", "variant": null, "stem": "What does `dependencies: ['setup']` on a project do?", "options": ["Installs npm packages", "Runs the setup project first", "Shares fixtures between files", "Retries setup on failure"], "answer": 1, "rationale": ["Unrelated to npm.", "", "Not what dependencies does.", "Retries are separate."]}, {"id": "6.3-c", "topic": "6.3", "kind": "check", "level": "Understand", "concept": "6.3-c", "variant": null, "stem": "Should `playwright/.auth/*.json` be committed to git?", "options": ["Yes, so CI can use it", "No — it contains live session data; regenerate it each run", "Only for public sites", "Only the admin file"], "answer": 1, "rationale": ["CI regenerates it via the setup project.", "", "Sessions are sensitive everywhere.", "All roles are sensitive."]}, {"id": "6.4-a", "topic": "6.4", "kind": "check", "level": "Understand", "concept": "6.4-a", "variant": null, "stem": "What does a Playwright trace contain?", "options": ["Actions, DOM snapshots, network, console and source", "Only the error message", "A video only", "Only a final screenshot"], "answer": 0, "rationale": ["", "The error is only part of it.", "Video is a separate artefact.", "Much more than one screenshot."]}, {"id": "6.4-b", "topic": "6.4", "kind": "check", "level": "Understand", "concept": "6.4-b", "variant": null, "stem": "What is codegen for?", "options": ["Generating test data", "Producing the HTML report", "Compiling TypeScript", "Recording interactions and generating test code"], "answer": 3, "rationale": ["Not a data generator.", "Reports come from reporters.", "Not a compiler.", ""]}, {"id": "6.4-c", "topic": "6.4", "kind": "check", "level": "Understand", "concept": "6.4-c", "variant": null, "stem": "What does page.pause() do in a headed debug run?", "options": ["Saves a trace", "Waits 1 second", "Pauses the test and opens the Playwright Inspector", "Skips the rest of the test"], "answer": 2, "rationale": ["Tracing is configured separately.", "Not a sleep.", "", "The test resumes from the Inspector."]}, {"id": "6.5-a", "topic": "6.5", "kind": "check", "level": "Understand", "concept": "6.5-a", "variant": null, "stem": "What does `--shard=2/3` do?", "options": ["Runs 2 projects of 3", "Runs with 2 workers out of 3", "Runs the second of three equal parts of the suite", "Retries 2 of 3 failures"], "answer": 2, "rationale": ["Projects use --project.", "Workers are set with --workers.", "", "Unrelated to retries."]}, {"id": "6.5-b", "topic": "6.5", "kind": "check", "level": "Understand", "concept": "6.5-b", "variant": null, "stem": "By default, how do tests inside a single file run?", "options": ["In parallel", "Sequentially in one worker", "In random order, one test per worker", "One per browser"], "answer": 1, "rationale": ["Only with fullyParallel or parallel mode.", "", "Order is preserved.", "Projects control browsers."]}, {"id": "6.5-c", "topic": "6.5", "kind": "check", "level": "Understand", "concept": "6.5-c", "variant": null, "stem": "What does forbidOnly protect against?", "options": ["A committed test.only silently skipping the rest of the suite", "Tests without assertions", "Using only CSS locators", "Running tests in only one browser"], "answer": 0, "rationale": ["", "Unrelated.", "Unrelated.", "Unrelated."]}, {"id": "6.6-a", "topic": "6.6", "kind": "check", "level": "Understand", "concept": "6.6-a", "variant": null, "stem": "What happens the first time toHaveScreenshot runs without a baseline?", "options": ["It downloads a baseline", "It skips the test", "It passes silently", "It fails and writes the baseline image"], "answer": 3, "rationale": ["Baselines are local.", "The test runs and fails.", "It reports the missing baseline.", ""]}, {"id": "6.6-b", "topic": "6.6", "kind": "check", "level": "Understand", "concept": "6.6-b", "variant": null, "stem": "Which flag refreshes screenshot baselines after an intended UI change?", "options": ["--reset-baseline-images", "--snapshots=new", "--refresh", "--update-snapshots"], "answer": 3, "rationale": ["Not a flag.", "Not a flag.", "Not a flag.", ""]}, {"id": "6.6-c", "topic": "6.6", "kind": "check", "level": "Understand", "concept": "6.6-c", "variant": null, "stem": "How do you stop a changing date from breaking a screenshot comparison?", "options": ["Use full_page", "Increase the timeout", "Use the mask option for that element", "Run headed"], "answer": 2, "rationale": ["Captures more, not less.", "Timing does not change pixels.", "", "Unrelated."]}, {"id": "1.1-d", "topic": "1.1", "kind": "bank", "level": "Understand", "concept": "1.1-d", "variant": null, "stem": "Which list contains only officially supported Playwright languages?", "options": ["Python, Ruby, Go", "TypeScript, Python, Java, .NET", "JavaScript, PHP, Rust", "Java, Kotlin, Swift, Objective-C"], "answer": 1, "rationale": ["Ruby and Go have no official bindings.", "the four official language bindings.", "PHP and Rust are not official.", "Kotlin, Swift and Objective-C are not official."]}, {"id": "1.1-e", "topic": "1.1", "kind": "bank", "level": "Understand", "concept": "1.1-e", "variant": null, "stem": "What does running \"headless\" mean?", "options": ["The browser runs without a visible window", "Only the page header is rendered, not the body", "Tests skip the network", "Tests run without assertions"], "answer": 0, "rationale": ["headless is the default.", "The whole page is rendered, just not shown.", "Network traffic happens normally.", "Assertions are unrelated to headless mode."]}, {"id": "1.2-d", "topic": "1.2", "kind": "bank", "level": "Understand", "concept": "1.2-d", "variant": null, "stem": "What does `npx playwright install --with-deps` add compared to plain `install`?", "options": ["Operating-system libraries the browsers need", "Extra browsers such as Opera", "The VS Code extension", "All the test dependencies listed in package.json"], "answer": 0, "rationale": ["useful on fresh Linux/CI machines.", "Only Chromium, Firefox and WebKit are installed.", "Extensions are installed separately.", "npm handles package.json dependencies."]}, {"id": "1.2-e", "topic": "1.2", "kind": "bank", "level": "Understand", "concept": "1.2-e", "variant": null, "stem": "In a JavaScript project, where do project-wide settings such as retries and reporters live?", "options": [".playwrightrc", "package.json", "tests/playwright.settings.json", "playwright.config.ts"], "answer": 3, "rationale": ["Not a Playwright file.", "package.json lists dependencies, not Playwright settings.", "Not a Playwright convention.", "created by the init wizard."]}, {"id": "1.3-d", "topic": "1.3", "kind": "bank", "level": "Understand", "concept": "1.3-d", "variant": null, "stem": "In `async ({ page }) => { … }`, what does `{ page }` do?", "options": ["Imports page from the config", "Creates a new page object", "Destructures the page fixture from the fixtures object", "Declares a block scope"], "answer": 2, "rationale": ["Nothing is imported here.", "The runner creates the page; the test only receives it.", "fixtures arrive as one object.", "The braces are in the parameter list."]}, {"id": "1.3-e", "topic": "1.3", "kind": "bank", "level": "Understand", "concept": "1.3-e", "variant": null, "stem": "A test performs actions but contains no assertion. What happens when it runs?", "options": ["It fails with an \"expected at least one assertion\" error", "It passes if no step throws an error", "It is skipped automatically", "It is reported as flaky"], "answer": 1, "rationale": ["Playwright does not require assertions.", "which makes it a weak test.", "Only explicit skips are skipped.", "Flaky means it passed on retry."]}, {"id": "1.4-d", "topic": "1.4", "kind": "bank", "level": "Understand", "concept": "1.4-d", "variant": null, "stem": "Which flag opens Playwright Test in UI mode?", "options": ["--gui", "--ui", "--watch", "--inspect"], "answer": 1, "rationale": ["Not a Playwright Test flag.", "watch mode and time travel.", "Not a Playwright Test flag.", "Debugging uses --debug."]}, {"id": "1.4-e", "topic": "1.4", "kind": "bank", "level": "Understand", "concept": "1.4-e", "variant": null, "stem": "What do you need to run pytest-playwright tests in parallel?", "options": ["The pytest-xdist plugin (-n)", "A playwright.config.ts file", "Nothing; pytest runs in parallel by default", "The --workers flag"], "answer": 0, "rationale": ["e.g. pytest -n auto.", "That config is for the JS runner.", "pytest runs tests sequentially by default.", "--workers is a Playwright Test option."]}, {"id": "2.1-d", "topic": "2.1", "kind": "bank", "level": "Understand", "concept": "2.1-d", "variant": null, "stem": "How do you target only `<h2>` headings by role?", "options": ["getByRole('heading', { headingSize: 2 })", "getByRole('heading').nth(2)", "getByRole('h2')", "getByRole('heading', { level: 2 })"], "answer": 3, "rationale": ["The option is called level.", "nth picks a position, not a level.", "h2 is a tag, not a role.", ""]}, {"id": "2.1-e", "topic": "2.1", "kind": "bank", "level": "Understand", "concept": "2.1-e", "variant": null, "stem": "Where does a link’s accessible name usually come from?", "options": ["Its id attribute", "Its href attribute", "Its text content (or aria-label)", "Its CSS class"], "answer": 2, "rationale": ["Ids do not contribute to names.", "The URL is not the name.", "", "Classes do not contribute to names."]}, {"id": "2.2-d", "topic": "2.2", "kind": "bank", "level": "Understand", "concept": "2.2-d", "variant": null, "stem": "Which locator finds an image by its alternative text?", "options": ["getByRole('picture')", "getByTitle()", "getByAltText()", "getByImage()"], "answer": 2, "rationale": ["\"picture\" is not the image role; the role is img.", "Title is a different attribute.", "", "No such method."]}, {"id": "2.2-e", "topic": "2.2", "kind": "bank", "level": "Understand", "concept": "2.2-e", "variant": null, "stem": "What does `getByText('Total', { exact: true })` change compared to the default?", "options": ["It ignores hidden and zero-size elements on the page", "It requires a full, case-sensitive match", "It searches only inside buttons", "It waits longer"], "answer": 1, "rationale": ["Visibility is unrelated to exact.", "", "getByText searches all elements.", "Timing is unchanged."]}, {"id": "2.3-d", "topic": "2.3", "kind": "bank", "level": "Understand", "concept": "2.3-d", "variant": null, "stem": "In `row.getByRole('button')`, where does the search happen?", "options": ["Only inside the elements matched by row", "Only in the next row", "In the parent of row", "Across the whole page"], "answer": 0, "rationale": ["", "Scope is the matched row elements.", "Chaining searches descendants.", "Chaining narrows the scope."]}, {"id": "2.3-e", "topic": "2.3", "kind": "bank", "level": "Understand", "concept": "2.3-e", "variant": null, "stem": "What does `locatorA.or(locatorB)` do?", "options": ["Matches only elements matching both locators", "Tries A, and B only after a timeout", "Picks whichever is visible first", "Matches elements matching either locator"], "answer": 3, "rationale": ["That is and().", "Both are evaluated together.", "Visibility is not part of or().", ""]}, {"id": "2.4-d", "topic": "2.4", "kind": "bank", "level": "Understand", "concept": "2.4-d", "variant": null, "stem": "In Python, how do you get the first match of a locator?", "options": ["locator[0]", "locator.get(0)", "locator.first()", "locator.first"], "answer": 3, "rationale": ["Locators are not indexable.", "No such method.", "In Python first is a property, not a method.", ""]}, {"id": "2.4-e", "topic": "2.4", "kind": "bank", "level": "Understand", "concept": "2.4-e", "variant": null, "stem": "Why is `filter({ hasText: \"Bike Light\" })` usually better than `nth(1)`?", "options": ["filter skips strict mode", "It runs faster", "It keeps working if the list order changes", "nth is deprecated"], "answer": 2, "rationale": ["Strict mode still applies.", "Speed is similar.", "it targets meaning, not position.", "nth is not deprecated."]}, {"id": "3.1-d", "topic": "3.1", "kind": "bank", "level": "Understand", "concept": "3.1-d", "variant": null, "stem": "`page.goto('/cart')` fails with an invalid URL error. What is missing?", "options": ["A waitUntil option", "A baseURL in the configuration", "An await keyword", "The --headed flag"], "answer": 1, "rationale": ["waitUntil controls timing, not resolution.", "relative URLs need a base.", "Missing await causes different problems.", "Headed mode does not affect URLs."]}, {"id": "3.1-e", "topic": "3.1", "kind": "bank", "level": "Understand", "concept": "3.1-e", "variant": null, "stem": "After clicking a link that navigates, what is the best way to confirm the new page?", "options": ["expect(page).toHaveURL(...)", "expect(page.url()).toBe(...)", "Reload the page", "page.waitForTimeout(2000)"], "answer": 0, "rationale": ["it retries.", "This reads the URL once without retrying.", "Reloading tests nothing.", "Fixed sleeps are slow and flaky."]}, {"id": "3.2-d", "topic": "3.2", "kind": "bank", "level": "Understand", "concept": "3.2-d", "variant": null, "stem": "You call `check()` on a checkbox that is already checked. What happens?", "options": ["Nothing changes; the call succeeds", "An error is thrown", "It is clicked twice", "It becomes unchecked"], "answer": 0, "rationale": ["it only clicks when needed.", "Already checked is fine.", "No clicks happen.", "check never unchecks."]}, {"id": "3.2-e", "topic": "3.2", "kind": "bank", "level": "Understand", "concept": "3.2-e", "variant": null, "stem": "Which method selects a radio button?", "options": ["toggle()", "selectOption()", "select()", "check()"], "answer": 3, "rationale": ["No such method.", "selectOption is for <select>.", "No such method.", ""]}, {"id": "3.3-d", "topic": "3.3", "kind": "bank", "level": "Understand", "concept": "3.3-d", "variant": null, "stem": "Why use `ControlOrMeta+A` instead of `Control+A`?", "options": ["It selects only visible text", "It is faster", "It maps to ⌘ on macOS and Ctrl elsewhere", "Control+A is deprecated"], "answer": 2, "rationale": ["Selection behaviour is the same.", "Speed is the same.", "cross-platform shortcuts.", "Control+A still works."]}, {"id": "3.3-e", "topic": "3.3", "kind": "bank", "level": "Understand", "concept": "3.3-e", "variant": null, "stem": "What does `page.keyboard.type()` act on?", "options": ["A locator you pass in", "The currently focused element", "The whole page body, whatever has focus", "The browser address bar"], "answer": 1, "rationale": ["keyboard methods take no locator.", "", "Typing goes to the focused element, not always the body.", "The address bar is not part of the page."]}, {"id": "3.4-d", "topic": "3.4", "kind": "bank", "level": "Understand", "concept": "3.4-d", "variant": null, "stem": "In Python, how do you capture a download triggered by a click?", "options": ["page.on(\"download\") after the click", "with page.expect_download() as info: …click…", "page.download(click)", "download = page.wait_for_download(timeout=5000)"], "answer": 1, "rationale": ["Registering afterwards may miss it.", "the context manager pattern.", "No such method.", "Not the Python API."]}, {"id": "3.4-e", "topic": "3.4", "kind": "bank", "level": "Understand", "concept": "3.4-e", "variant": null, "stem": "How can a test collect messages written with console.log by the page?", "options": ["page.on('console', …)", "page.console()", "expect(page).toHaveConsole()", "Enable verbose mode"], "answer": 0, "rationale": ["", "No such method.", "No such matcher.", "Verbose mode affects the runner, not page logs."]}, {"id": "4.1-d", "topic": "4.1", "kind": "bank", "level": "Understand", "concept": "4.1-d", "variant": null, "stem": "Which matcher checks the current value of an input field?", "options": ["toContainText", "toHaveAttribute(\"value\")", "toHaveText", "toHaveValue"], "answer": 3, "rationale": ["Text matchers read text content.", "The attribute is the initial value, not the current one.", "Inputs have no text content.", ""]}, {"id": "4.1-e", "topic": "4.1", "kind": "bank", "level": "Understand", "concept": "4.1-e", "variant": null, "stem": "What does passing an array to toHaveText check?", "options": ["That the array has the same length as the page", "That any matched element matches any one of the strings", "Every matched element, in order, against each entry", "Only the first element"], "answer": 2, "rationale": ["It compares matched elements with entries.", "It is an ordered, one-to-one comparison.", "", "All elements are compared."]}, {"id": "4.2-d", "topic": "4.2", "kind": "bank", "level": "Understand", "concept": "4.2-d", "variant": null, "stem": "Which extra check does fill() perform that click() does not?", "options": ["Focused", "Stable", "Editable", "Receives events"], "answer": 2, "rationale": ["fill focuses the element itself.", "Stable is a click check.", "read-only inputs cannot be filled.", "That is a click check."]}, {"id": "4.2-e", "topic": "4.2", "kind": "bank", "level": "Understand", "concept": "4.2-e", "variant": null, "stem": "What does the \"stable\" check mean?", "options": ["The page has stopped loading network requests", "The element is not moving or animating", "The element has a fixed id", "The test is not flaky"], "answer": 1, "rationale": ["Page loading is not this check.", "", "Ids are unrelated.", "It is an element check."]}, {"id": "4.3-d", "topic": "4.3", "kind": "bank", "level": "Understand", "concept": "4.3-d", "variant": null, "stem": "What does test.slow() do?", "options": ["Triples the test timeout", "Runs the test last", "Marks it as flaky", "Adds slowMo between actions"], "answer": 0, "rationale": ["", "Order is unchanged.", "It does not mark flakiness.", "slowMo is a launch option."]}, {"id": "4.3-e", "topic": "4.3", "kind": "bank", "level": "Understand", "concept": "4.3-e", "variant": null, "stem": "Where do you raise the assertion timeout for the whole Playwright Test suite?", "options": ["test.setTimeout()", "actionTimeout", "use: { timeout }", "expect: { timeout } in the config"], "answer": 3, "rationale": ["That sets the test timeout.", "That applies to actions.", "use has no timeout option for assertions.", ""]}, {"id": "4.4-d", "topic": "4.4", "kind": "bank", "level": "Understand", "concept": "4.4-d", "variant": null, "stem": "In the HTML report, what does a \"flaky\" label mean?", "options": ["The test took longer than usual", "The test has no assertions", "The test was skipped", "The test failed at first and passed on a retry"], "answer": 3, "rationale": ["Duration does not mark flakiness.", "Not detected by the report.", "Skips are labelled skipped.", ""]}, {"id": "4.4-e", "topic": "4.4", "kind": "bank", "level": "Understand", "concept": "4.4-e", "variant": null, "stem": "Test B only passes if test A ran first. Why is this a problem?", "options": ["A will be retried", "Tests run slower", "Tests must be independent; order and parallelism can change", "B will be skipped"], "answer": 2, "rationale": ["Retries are unrelated.", "Speed is not the issue.", "", "Nothing is skipped automatically."]}, {"id": "5.1-d", "topic": "5.1", "kind": "bank", "level": "Understand", "concept": "5.1-d", "variant": null, "stem": "What is the pytest equivalent of beforeEach for every test in a file?", "options": ["setUp()", "@pytest.fixture(autouse=True)", "@pytest.before", "conftest.run()"], "answer": 1, "rationale": ["setUp belongs to unittest classes.", "", "No such decorator.", "No such function."]}, {"id": "5.1-e", "topic": "5.1", "kind": "bank", "level": "Understand", "concept": "5.1-e", "variant": null, "stem": "How do you run only tests tagged @smoke in Playwright Test?", "options": ["npx playwright test --grep @smoke", "npx playwright test -m smoke", "npx playwright test --only-tagged @smoke", "npx playwright test --tag smoke"], "answer": 0, "rationale": ["", "-m is the pytest marker filter.", "No such flag.", "Not the CLI flag."]}, {"id": "5.2-d", "topic": "5.2", "kind": "bank", "level": "Understand", "concept": "5.2-d", "variant": null, "stem": "How do you make a Playwright Test fixture shared by all tests in one worker?", "options": ["{ scope: 'worker' }", "{ shared: true }", "{ auto: true }", "test.describe.serial"], "answer": 0, "rationale": ["", "No such option.", "auto runs it for every test, still per test.", "serial controls ordering."]}, {"id": "5.2-e", "topic": "5.2", "kind": "bank", "level": "Understand", "concept": "5.2-e", "variant": null, "stem": "What does the built-in page fixture give each test?", "options": ["A page only after login", "A page in every browser at once", "The same page, shared by all tests in the file", "A new page in a new isolated browser context"], "answer": 3, "rationale": ["Login is your job.", "Projects choose the browser.", "Sharing would break isolation.", ""]}, {"id": "5.3-d", "topic": "5.3", "kind": "bank", "level": "Understand", "concept": "5.3-d", "variant": null, "stem": "Which method name fits a page object best?", "options": ["doStuff()", "clickSecondButtonInForm()", "login(user, password)", "locatorForField3()"], "answer": 2, "rationale": ["Says nothing.", "Describes an element, not a user goal.", "a user-level action.", "Implementation detail."]}, {"id": "5.3-e", "topic": "5.3", "kind": "bank", "level": "Understand", "concept": "5.3-e", "variant": null, "stem": "How can tests receive a page object without calling `new` every time?", "options": ["Global variables", "A custom fixture that builds and provides it", "A beforeAll hook", "Importing it from the config"], "answer": 1, "rationale": ["Globals break isolation.", "", "beforeAll cannot use the per-test page.", "Config does not provide objects."]}, {"id": "5.4-d", "topic": "5.4", "kind": "bank", "level": "Understand", "concept": "5.4-d", "variant": null, "stem": "In pytest-playwright, how do you change context options such as locale for every test?", "options": ["Edit playwright.config.ts", "Override the browser_context_args fixture", "Set PLAYWRIGHT_LOCALE", "Pass locale to page.goto()"], "answer": 1, "rationale": ["The JS config is not read by pytest.", "", "Not a supported variable.", "goto has no such option."]}, {"id": "5.4-e", "topic": "5.4", "kind": "bank", "level": "Understand", "concept": "5.4-e", "variant": null, "stem": "What does trace: 'on-first-retry' mean?", "options": ["Record a trace only when a failed test is retried the first time", "Record only on the first test", "Never record traces", "Record a trace for every test"], "answer": 0, "rationale": ["cheap and useful in CI.", "Not related to test order.", "That is 'off'.", "That is 'on'."]}, {"id": "6.1-d", "topic": "6.1", "kind": "bank", "level": "Understand", "concept": "6.1-d", "variant": null, "stem": "Which glob matches `https://shop.test/api/v1/items`?", "options": ["'/api'", "'api/*/items/*'", "'*/api/*'", "'**/api/**'"], "answer": 3, "rationale": ["Globs match the whole URL.", "The pattern does not fit.", "A single * does not cross slashes.", "** matches any path segments."]}, {"id": "6.1-e", "topic": "6.1", "kind": "bank", "level": "Understand", "concept": "6.1-e", "variant": null, "stem": "How do you test that the app shows an error when the network fails?", "options": ["route.continue()", "route.fulfill({ status: 200 })", "route.abort()", "page.setOffline()"], "answer": 2, "rationale": ["That passes the request through.", "That is a success response.", "", "The method is context.setOffline, and abort is targeted."]}, {"id": "6.2-d", "topic": "6.2", "kind": "bank", "level": "Understand", "concept": "6.2-d", "variant": null, "stem": "Which option sends a JSON body with request.post?", "options": ["body", "json", "data", "payload"], "answer": 2, "rationale": ["Not the option name.", "Not the option name in the request API.", "", "Not an option."]}, {"id": "6.2-e", "topic": "6.2", "kind": "bank", "level": "Understand", "concept": "6.2-e", "variant": null, "stem": "In Python, how do you read the status code of an APIResponse?", "options": ["response.status()", "response.status", "response.get_status()", "response[\"status\"]"], "answer": 1, "rationale": ["That is the JS form.", "a property.", "No such method.", "Responses are not subscriptable."]}, {"id": "6.3-d", "topic": "6.3", "kind": "bank", "level": "Understand", "concept": "6.3-d", "variant": null, "stem": "How do you test as an admin and as a viewer in one suite?", "options": ["Use a separate storage state file per role", "Use two config files", "It is not possible", "Log out between tests"], "answer": 0, "rationale": ["", "Projects or test.use handle it in one config.", "It is supported.", "Slow and fragile."]}, {"id": "6.3-e", "topic": "6.3", "kind": "bank", "level": "Understand", "concept": "6.3-e", "variant": null, "stem": "What is the main benefit of reusing storage state?", "options": ["More accurate and stable assertions", "Tests run headed", "Better screenshots", "Tests skip the slow UI login"], "answer": 3, "rationale": ["Unrelated.", "Unrelated.", "Unrelated.", ""]}, {"id": "6.4-d", "topic": "6.4", "kind": "bank", "level": "Understand", "concept": "6.4-d", "variant": null, "stem": "How do you open the Inspector for pytest-playwright tests?", "options": ["pytest --ui", "playwright debug", "pytest --inspect --headed", "PWDEBUG=1 pytest -s"], "answer": 3, "rationale": ["UI mode belongs to Playwright Test.", "Not a command.", "Not a valid option.", ""]}, {"id": "6.4-e", "topic": "6.4", "kind": "bank", "level": "Understand", "concept": "6.4-e", "variant": null, "stem": "Which command opens a saved trace file?", "options": ["npx playwright trace view", "npx playwright show-report trace.zip", "npx playwright show-trace trace.zip", "npx playwright open trace.zip"], "answer": 2, "rationale": ["Not the right command.", "That opens the HTML report.", "", "Not the right command."]}, {"id": "6.5-d", "topic": "6.5", "kind": "bank", "level": "Understand", "concept": "6.5-d", "variant": null, "stem": "How do you run pytest-playwright tests in parallel?", "options": ["pytest --workers 4", "pytest -n auto (pytest-xdist)", "pytest --parallel --workers=auto", "It happens by default"], "answer": 1, "rationale": ["Not a pytest option.", "", "Not a pytest option.", "pytest is sequential by default."]}, {"id": "6.5-e", "topic": "6.5", "kind": "bank", "level": "Understand", "concept": "6.5-e", "variant": null, "stem": "How do you get one HTML report from several shards?", "options": ["Use the blob reporter per shard and merge-reports", "Run show-report on each", "Shards cannot be combined", "Copy the folders together"], "answer": 0, "rationale": ["", "That gives separate reports.", "They can be merged.", "Reports would overwrite each other."]}, {"id": "6.6-d", "topic": "6.6", "kind": "bank", "level": "Understand", "concept": "6.6-d", "variant": null, "stem": "How do you emulate an iPhone in a Playwright Test project?", "options": ["use: { ...devices['iPhone 13'] }", "use: { mobile: true }", "browserName: 'iphone'", "use: { device: 'iPhone 13', mobile: true }"], "answer": 0, "rationale": ["", "Not an option.", "Not a browser.", "Not the API; spread devices['iPhone 13'] instead."]}, {"id": "6.6-e", "topic": "6.6", "kind": "bank", "level": "Understand", "concept": "6.6-e", "variant": null, "stem": "Why are screenshot baselines stored per browser and platform?", "options": ["Git requires it", "For security", "To save disk space", "Rendering and fonts differ between them"], "answer": 3, "rationale": ["Unrelated.", "Unrelated.", "They use more space, not less.", ""]}], "blueprints": {"full": {"title": "Full mock test", "questions": 30, "minutes": 40, "mode": "both", "slots": [{"module": "1", "count": 4}, {"module": "2", "count": 6}, {"module": "3", "count": 5}, {"module": "4", "count": 6}, {"module": "5", "count": 5}, {"module": "6", "count": 4}]}, "quick": {"title": "Quick check", "questions": 10, "minutes": 12, "mode": "both", "slots": [{"module": "1", "count": 1}, {"module": "2", "count": 2}, {"module": "3", "count": 2}, {"module": "4", "count": 2}, {"module": "5", "count": 2}, {"module": "6", "count": 1}]}}, "fixedMocks": {}, "cheatsheets": {"1": "### Install\n- JS: `npm init playwright@latest` · browsers: `npx playwright install --with-deps`\n- Python: `pip install pytest-playwright` then `playwright install`\n\n### Test skeleton\n- JS: `test('name', async ({ page }) => { … })` + `await` on every call\n- Python: `def test_name(page: Page):` — sync API, no await\n- Import: `import { test, expect } from '@playwright/test'` / `from playwright.sync_api import Page, expect`\n\n### Run\n- JS: `npx playwright test`, `-g \"title\"`, `--project=firefox`, `--headed`, `--ui`, `--debug`, `--last-failed`, `show-report`\n- Python: `pytest`, `-k \"name\"`, `--browser firefox`, `--headed`, `--slowmo 500`, `--tracing retain-on-failure`, `-n auto` (xdist)\n\n### Must know\n- Engines: Chromium, Firefox, WebKit. Languages: TS/JS, Python, Java, .NET\n- Headless by default. Fresh browser context per test = isolation\n- File names: `*.spec.ts` / `test_*.py`", "2": "### Priority\nrole → label → placeholder → text → alt / title → test id → CSS / XPath\n\n### Builders (JS · Python)\n- `getByRole('button', { name: 'Save' })` · `get_by_role(\"button\", name=\"Save\")`\n- `getByLabel` · `get_by_label` — form controls\n- `getByPlaceholder` · `get_by_placeholder`\n- `getByText` · `get_by_text` — substring, case-insensitive; `exact: true`\n- `getByAltText`, `getByTitle`, `getByTestId` (`data-testid`; configurable)\n- `locator('css')`, `locator('xpath=//…')`\n\n### Narrowing\n- Chain: `row.getByRole('button')` searches inside\n- `filter({ hasText, hasNotText, has, hasNot })` · Python `has_text=`\n- `a.or(b)`, `a.and(b)`\n\n### Lists\n- Strict mode: actions need exactly one match\n- `first()`, `last()`, `nth(i)` (zero-based) · Python `first`, `last` are properties\n- `count()`, `all()`, `allTextContents()`, `toHaveCount(n)`\n- Locators are lazy — resolved on every use", "3": "### Navigation & clicks\n- `goto(url)` waits for **load**; relative URLs need `baseURL`\n- `click({ button: 'right', clickCount: 2, modifiers: ['Shift'], force })`, `dblclick()`\n- After a click navigates: `expect(page).toHaveURL(…)`\n\n### Forms\n- `fill` (replace) · `pressSequentially` (key by key) · `clear`\n- `check`, `uncheck`, `setChecked` — radios: `check()`\n- `selectOption('value' | 'Label' | { label } | { index } | [...])`\n- `setInputFiles(path)`\n\n### Keyboard & mouse\n- `press('Enter')`, `'Shift+A'`, `'ControlOrMeta+A'`\n- `page.keyboard.type / press / down / up`\n- `hover()`, `dragTo(target)`\n\n### Events\n- Dialogs auto-dismissed. `page.on('dialog', d => d.accept())` **before** the trigger\n- Popup: `const p = page.waitForEvent('popup'); await click; await p` · Python `with page.expect_popup() as info:`\n- Download: `'download'` / `expect_download()`\n- `page.on('console')`, `page.on('pageerror')`", "4": "### Web-first assertions (retry, 5 s)\n- Element: `toBeVisible`, `toBeHidden`, `toBeEnabled`, `toBeDisabled`, `toBeChecked`, `toBeEditable`, `toBeFocused`\n- Content: `toHaveText` (full), `toContainText` (substring), `toHaveValue`, `toHaveAttribute`, `toHaveClass`, `toHaveCount`\n- Page: `toHaveURL`, `toHaveTitle` · API: `toBeOK`\n- Arrays: `toHaveText([...])` checks each element in order\n- Python: snake_case, negation `not_to_be_visible()`\n\n### Actionability\n- click: visible, stable, receives events, enabled\n- fill: visible, enabled, editable\n- `force: true` skips checks (avoid)\n\n### Timeouts\n- Test 30 s · assertion 5 s · action/navigation unlimited (within test)\n- Per call `{ timeout: 10_000 }` / `timeout=10_000`; config `expect: { timeout }`; `test.slow()` ×3\n- `expect.soft()` continues after a failure\n\n### Flakiness killers\n- No sleeps · no positional CSS · no `expect(await …)` on live UI\n- Independent tests, own data · mock unstable services\n- Retries + `trace: 'on-first-retry'`; \"flaky\" = passed on retry", "5": "### Hooks & selection\n- `test.describe`, `beforeEach/afterEach` (per test), `beforeAll/afterAll` (per worker)\n- `test.only` (+ `forbidOnly` in CI), `test.skip`, `test.fixme`, tags `@smoke` + `--grep`\n- pytest: `@pytest.fixture(autouse=True)`, markers `-m smoke`, `@pytest.mark.parametrize`\n\n### Fixtures\n- Built-in: `page`, `context`, `browser`, `browserName`, `request`\n- `base.extend({ name: async ({ page }, use) => { setup; await use(v); teardown } })`\n- On demand; `{ auto: true }`, `{ scope: 'worker' }`\n- pytest: `@pytest.fixture` + `yield`, `scope=\"session\"`, share via **conftest.py**\n\n### Page objects\n- Locators in the constructor, user-level methods, assertions in tests\n- Provide page objects through fixtures\n\n### Config (playwright.config.ts)\n- `testDir, timeout, retries, workers, fullyParallel, reporter`\n- `use: { baseURL, trace, screenshot, video, storageState, testIdAttribute }`\n- `projects: [{ name, use: { ...devices['iPhone 13'] }, dependencies }]`, `webServer`\n- Python: `addopts` in pytest.ini, override `browser_context_args`", "6": "### Network\n- `page.route(glob|regex, handler)` **before** the trigger\n- `fulfill({ status, json, body })`, `abort()`, `continue({ headers })`\n- Modify: `const r = await route.fetch(); … route.fulfill({ response: r, json })`\n- `context.route`, `unroute`, `waitForResponse`, `routeFromHAR`\n\n### API\n- JS: `request` fixture · `get/post/put/patch/delete(url, { data, params, headers })`\n- `res.status()`, `res.ok()`, `await res.json()`, `expect(res).toBeOK()`\n- `page.request` shares cookies with the page\n- Python: `playwright.request.new_context(base_url=…)`, `res.status` / `res.ok` properties\n\n### Auth\n- `context.storageState({ path })` = cookies + localStorage\n- Setup project + `dependencies: ['setup']` + `use: { storageState }`\n- `.auth/` in .gitignore · one state per role\n\n### Debug\n- `--ui`, `--debug`, `page.pause()`, `PWDEBUG=1`\n- Trace: `show-trace`, trace.playwright.dev · `codegen <url>`\n\n### CI & scale\n- Files parallel, tests in a file sequential (unless `fullyParallel`)\n- `--shard=1/4` + blob reporter + `merge-reports`\n- `install --with-deps`, retries 2, forbidOnly, Docker `mcr.microsoft.com/playwright`\n- Python: `pytest -n auto`\n\n### Visual & devices\n- `toHaveScreenshot`: first run fails + writes baseline; `--update-snapshots`; `mask`, `maxDiffPixels`\n- Baselines per browser/OS · `devices['iPhone 13']`, locale, timezoneId, colorScheme"}, "activities": {"api-tests": {"id": "api-tests", "type": "lab", "plugin": "labs-web", "topic": "6.2", "title": "Test a REST API", "placement": "standalone", "minutes": 10, "brief": "Test the Users API at `https://api.test` directly — no browser page needed.", "tasks": ["`POST /users` with `{ name: \"Sana\", job: \"Tester\" }` → status **201**, body `name` is `Sana`", "`GET /users/1` → status **200**, `data.name` is `Aisha Khan`", "`GET /users/99` → status **404**", "`POST /users` with no name → status **400**"], "hints": ["JS: `res.status()` and `res.ok()` are methods. Python: `res.status` and `res.ok` are properties.", "`data` sends a JSON body. `expect(res).toBeOK()` passes for any 2xx status."], "checks": [{"label": "Sends POST and GET requests", "type": "match", "args": [{"apiMethods": ["POST", "GET"]}]}, {"label": "Covers 201, 200, 404 and 400", "type": "match", "args": [{"apiStatuses": [201, 200, 404, 400]}]}, {"label": "Makes at least 5 assertions", "type": "asserted", "args": [["toBe", "assert", "toBeOK"], "Makes at least 5 assertions", 5]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest.use({ baseURL: 'https://api.test' });\n\ntest('create a user', async ({ request }) => {\n  const res = await request.post('/users', { data: { name: 'Sana', job: 'Tester' } });\n  expect(res.status()).toBe(201);\n  const body = await res.json();\n  expect(body.name).toBe('Sana');\n\n  const bad = await request.post('/users', { data: { job: 'Tester' } });\n  expect(bad.status()).toBe(400);\n});\n\ntest('read users', async ({ request }) => {\n  const res = await request.get('/users/1');\n  await expect(res).toBeOK();\n  expect((await res.json()).data.name).toBe('Aisha Khan');\n\n  const missing = await request.get('/users/99');\n  expect(missing.status()).toBe(404);\n});\n", "py": "from playwright.sync_api import APIRequestContext, expect\n\n\ndef test_create_a_user(api_request_context: APIRequestContext):\n    res = api_request_context.post(\"/users\", data={\"name\": \"Sana\", \"job\": \"Tester\"})\n    assert res.status == 201\n    assert res.json()[\"name\"] == \"Sana\"\n\n    bad = api_request_context.post(\"/users\", data={\"job\": \"Tester\"})\n    assert bad.status == 400\n\n\ndef test_read_users(api_request_context: APIRequestContext):\n    res = api_request_context.get(\"/users/1\")\n    expect(res).to_be_ok()\n    assert res.json()[\"data\"][\"name\"] == \"Aisha Khan\"\n\n    missing = api_request_context.get(\"/users/99\")\n    assert missing.status == 404\n"}, "site": "https://api.test/users", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest.use({ baseURL: 'https://api.test' });\n\ntest('create a user', async ({ request }) => {\n\n});\n\ntest('read users', async ({ request }) => {\n\n});\n", "py": "from playwright.sync_api import APIRequestContext, expect\n\n\n# The api_request_context fixture uses https://api.test as its base URL.\n\ndef test_create_a_user(api_request_context: APIRequestContext):\n    pass\n\n\ndef test_read_users(api_request_context: APIRequestContext):\n    pass\n"}, "legacyId": "api-tests"}}, "auto-wait": {"id": "auto-wait", "type": "lab", "plugin": "labs-web", "topic": "4.2", "title": "Let Playwright wait", "placement": "standalone", "minutes": 10, "brief": "Everything on this page appears late or becomes enabled late. Write the test **without any sleeps** — auto-waiting and web-first assertions handle the timing.", "tasks": ["Click **Start**; assert `Hello World!` becomes visible (takes 2 s)", "Click the delayed button **Click me** (enabled after 3 s); assert `#late-msg` says `Clicked!`", "Click **Load more**; assert the list under it has **6** items"], "hints": ["`click()` waits until the button is visible **and enabled**.", "The delayed button is named **Click me** only once it is enabled — before that it says *Enabled soon*."], "checks": [{"label": "No fixed sleeps", "type": "noCalls", "args": ["waitForTimeout", "No fixed sleeps"]}, {"label": "Waits for Hello World!", "type": "asserted", "args": ["toBeVisible", "Waits for Hello World!"]}, {"label": "Asserts 6 list items", "type": "asserted", "args": ["toHaveCount", "Asserts 6 list items"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('wait for dynamic content', async ({ page }) => {\n  await page.goto('https://play.test/dynamic');\n  await page.getByRole('button', { name: 'Start' }).click();\n  await expect(page.getByText('Hello World!')).toBeVisible();\n  await page.getByRole('button', { name: 'Click me' }).click();\n  await expect(page.locator('#late-msg')).toHaveText('Clicked!');\n  await page.getByRole('button', { name: 'Load more' }).click();\n  await expect(page.locator('#items li')).toHaveCount(6);\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_wait_for_dynamic_content(page: Page):\n    page.goto(\"https://play.test/dynamic\")\n    page.get_by_role(\"button\", name=\"Start\").click()\n    expect(page.get_by_text(\"Hello World!\")).to_be_visible()\n    page.get_by_role(\"button\", name=\"Click me\").click()\n    expect(page.locator(\"#late-msg\")).to_have_text(\"Clicked!\")\n    page.get_by_role(\"button\", name=\"Load more\").click()\n    expect(page.locator(\"#items li\")).to_have_count(6)\n"}, "site": "https://play.test/dynamic", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('wait for dynamic content', async ({ page }) => {\n  await page.goto('https://play.test/dynamic');\n  // No waitForTimeout() allowed!\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_wait_for_dynamic_content(page: Page):\n    page.goto(\"https://play.test/dynamic\")\n    # No wait_for_timeout() allowed!\n"}, "legacyId": "auto-wait"}}, "custom-fixture": {"id": "custom-fixture", "type": "lab", "plugin": "labs-web", "topic": "5.2", "title": "Write a custom fixture", "placement": "standalone", "minutes": 10, "brief": "Create a `loggedInPage` fixture (Python: `logged_in_page`) that logs in and hands the page to the test. Use it for a full checkout.", "tasks": ["JavaScript: `const test = base.extend({ loggedInPage: async ({ page }, use) => { … await use(page); } })`", "Python: a `@pytest.fixture` that logs in and `yield`s the page", "In the test: add **Fleece Jacket**, open the cart, click **Checkout**", "Fill First name, Last name, Postal code; click **Continue**", "Assert the total (test id `total`) contains `$53.99`, click **Finish**, assert `Thank you for your order!`"], "hints": ["A fixture runs code **before** `use()` / `yield` (setup) and **after** it (teardown).", "The test asks for the fixture by name in its parameters."], "checks": [{"label": "Defines a custom fixture", "type": "code", "args": [{"re": "\\.extend\\s*\\(", "flags": ""}, {"re": "@pytest\\.fixture", "flags": ""}, "Defines a custom fixture"]}, {"label": "Hands the page over", "type": "code", "args": [{"re": "await\\s+use\\s*\\(", "flags": ""}, {"re": "yield\\s+\\w+", "flags": ""}, "Hands the page over"]}, {"label": "Completes the order", "type": "url", "args": [{"re": "checkout\\/complete", "flags": ""}, "Completes the order"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test as base, expect } from '@playwright/test';\n\nconst test = base.extend({\n  loggedInPage: async ({ page }, use) => {\n    await page.goto('https://shop.test/');\n    await page.getByLabel('Username').fill('standard_user');\n    await page.getByLabel('Password').fill('secret_sauce');\n    await page.getByRole('button', { name: 'Log in' }).click();\n    await use(page);\n  },\n});\n\ntest('checkout one item', async ({ loggedInPage: page }) => {\n  await page.getByTestId('product').filter({ hasText: 'Fleece Jacket' })\n    .getByRole('button', { name: 'Add to cart' }).click();\n  await page.getByRole('link', { name: 'Cart' }).click();\n  await page.getByRole('button', { name: 'Checkout' }).click();\n  await page.getByLabel('First name').fill('Sam');\n  await page.getByLabel('Last name').fill('Lee');\n  await page.getByLabel('Postal code').fill('54000');\n  await page.getByRole('button', { name: 'Continue' }).click();\n  await expect(page.getByTestId('total')).toContainText('$53.99');\n  await page.getByRole('button', { name: 'Finish' }).click();\n  await expect(page.getByRole('heading', { name: 'Thank you for your order!' })).toBeVisible();\n});\n", "py": "import pytest\nfrom playwright.sync_api import Page, expect\n\n\n@pytest.fixture\ndef logged_in_page(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n    yield page\n\n\ndef test_checkout_one_item(logged_in_page: Page):\n    page = logged_in_page\n    page.get_by_test_id(\"product\").filter(has_text=\"Fleece Jacket\").get_by_role(\"button\", name=\"Add to cart\").click()\n    page.get_by_role(\"link\", name=\"Cart\").click()\n    page.get_by_role(\"button\", name=\"Checkout\").click()\n    page.get_by_label(\"First name\").fill(\"Sam\")\n    page.get_by_label(\"Last name\").fill(\"Lee\")\n    page.get_by_label(\"Postal code\").fill(\"54000\")\n    page.get_by_role(\"button\", name=\"Continue\").click()\n    expect(page.get_by_test_id(\"total\")).to_contain_text(\"$53.99\")\n    page.get_by_role(\"button\", name=\"Finish\").click()\n    expect(page.get_by_role(\"heading\", name=\"Thank you for your order!\")).to_be_visible()\n"}, "site": "https://shop.test/", "starter": {"js": "import { test as base, expect } from '@playwright/test';\n\n// TODO: const test = base.extend({ loggedInPage: ... });\n\ntest('checkout one item', async ({ loggedInPage: page }) => {\n\n});\n", "py": "import pytest\nfrom playwright.sync_api import Page, expect\n\n\n# TODO: @pytest.fixture def logged_in_page(page: Page): ... yield page\n\n\ndef test_checkout_one_item(logged_in_page: Page):\n    page = logged_in_page\n"}, "legacyId": "custom-fixture"}}, "dialogs": {"id": "dialogs", "type": "lab", "plugin": "labs-web", "topic": "3.4", "title": "Handle browser dialogs", "placement": "standalone", "minutes": 10, "brief": "Playwright dismisses dialogs automatically unless you register a handler **before** the action that opens them.", "tasks": ["Test 1: accept the **confirm** dialog; assert `You clicked: OK`", "Test 2: answer the **prompt** with `Playwright`; assert `You entered: Playwright`"], "hints": ["`page.on(\"dialog\", …)` or `page.once(\"dialog\", …)` registers the handler.", "`dialog.accept(text)` fills a prompt; `dialog.dismiss()` cancels.", "Python handler: `lambda dialog: dialog.accept()`."], "checks": [{"label": "Calls dialog.accept()", "type": "calls", "args": ["accept", "Calls dialog.accept()", 2]}, {"label": "At least 2 passing tests", "type": "tests", "args": [2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('accept a confirm dialog', async ({ page }) => {\n  await page.goto('https://play.test/dialogs');\n  page.once('dialog', dialog => dialog.accept());\n  await page.getByRole('button', { name: 'Show confirm' }).click();\n  await expect(page.getByRole('status')).toHaveText('You clicked: OK');\n});\n\ntest('answer a prompt', async ({ page }) => {\n  await page.goto('https://play.test/dialogs');\n  page.once('dialog', async dialog => {\n    expect(dialog.message()).toBe('What is your name?');\n    await dialog.accept('Playwright');\n  });\n  await page.getByRole('button', { name: 'Show prompt' }).click();\n  await expect(page.getByRole('status')).toHaveText('You entered: Playwright');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_accept_a_confirm_dialog(page: Page):\n    page.goto(\"https://play.test/dialogs\")\n    page.once(\"dialog\", lambda dialog: dialog.accept())\n    page.get_by_role(\"button\", name=\"Show confirm\").click()\n    expect(page.get_by_role(\"status\")).to_have_text(\"You clicked: OK\")\n\n\ndef test_answer_a_prompt(page: Page):\n    page.goto(\"https://play.test/dialogs\")\n    page.once(\"dialog\", lambda dialog: dialog.accept(\"Playwright\"))\n    page.get_by_role(\"button\", name=\"Show prompt\").click()\n    expect(page.get_by_role(\"status\")).to_have_text(\"You entered: Playwright\")\n"}, "site": "https://play.test/dialogs", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('accept a confirm dialog', async ({ page }) => {\n  await page.goto('https://play.test/dialogs');\n\n});\n\ntest('answer a prompt', async ({ page }) => {\n  await page.goto('https://play.test/dialogs');\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_accept_a_confirm_dialog(page: Page):\n    page.goto(\"https://play.test/dialogs\")\n\n\ndef test_answer_a_prompt(page: Page):\n    page.goto(\"https://play.test/dialogs\")\n"}, "legacyId": "dialogs"}}, "first-test": {"id": "first-test", "type": "lab", "plugin": "labs-web", "topic": "1.3", "title": "Your first test", "placement": "standalone", "minutes": 10, "brief": "Write a test that opens **Pocket Shop**, checks the browser tab title, and checks that the main heading is on screen.", "tasks": ["Open `https://shop.test/`", "Assert the page title is `Pocket Shop`", "Assert the heading **Pocket Shop** is visible"], "hints": ["Navigation: `page.goto(url)`.", "Page-level assertion: `expect(page).toHaveTitle(...)` — Python: `to_have_title`.", "A heading is found with `getByRole(\"heading\", { name: \"…\" })`."], "checks": [{"label": "Opens the page with goto()", "type": "calls", "args": ["goto", "Opens the page with goto()"]}, {"label": "Asserts the title", "type": "asserted", "args": ["toHaveTitle", "Asserts the title"]}, {"label": "Asserts the heading is visible", "type": "asserted", "args": ["toBeVisible", "Asserts the heading is visible"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('home page shows the shop name', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await expect(page).toHaveTitle('Pocket Shop');\n  await expect(page.getByRole('heading', { name: 'Pocket Shop' })).toBeVisible();\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_home_page_shows_the_shop_name(page: Page):\n    page.goto(\"https://shop.test/\")\n    expect(page).to_have_title(\"Pocket Shop\")\n    expect(page.get_by_role(\"heading\", name=\"Pocket Shop\")).to_be_visible()\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('home page shows the shop name', async ({ page }) => {\n  // 1. Open https://shop.test/\n\n  // 2. Assert the page title is \"Pocket Shop\"\n\n  // 3. Assert the heading \"Pocket Shop\" is visible\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_home_page_shows_the_shop_name(page: Page):\n    # 1. Open https://shop.test/\n\n    # 2. Assert the page title is \"Pocket Shop\"\n\n    # 3. Assert the heading \"Pocket Shop\" is visible\n    pass\n"}, "legacyId": "first-test"}}, "fix-flaky": {"id": "fix-flaky", "type": "lab", "plugin": "labs-web", "topic": "4.4", "title": "Refactor a fragile test", "placement": "standalone", "minutes": 10, "brief": "This test passes today, but it is slow and fragile. Rewrite it so it still passes **without** fixed sleeps, positional CSS, or non-retrying assertions.", "tasks": ["Remove every `waitForTimeout` / `wait_for_timeout`", "Replace the `nth-child` CSS selector with a user-facing locator for **Bike Light**", "Replace the `textContent` + `toBe` check with a web-first `toHaveText` on the badge"], "hints": ["After clicking **Log in**, the next action auto-waits for the products page — no sleep needed.", "`nth-child(2)` breaks as soon as the sort order changes; filter by the product name instead."], "checks": [{"label": "No fixed sleeps", "type": "noCalls", "args": ["waitForTimeout", "No fixed sleeps"]}, {"label": "No positional CSS", "type": "noCode", "args": [{"re": "nth-child", "flags": ""}, "No positional CSS"]}, {"label": "Web-first badge assertion", "type": "asserted", "args": ["toHaveText", "Web-first badge assertion"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('add bike light', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByLabel('Username').fill('standard_user');\n  await page.getByLabel('Password').fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n  await page.getByTestId('product').filter({ hasText: 'Bike Light' })\n    .getByRole('button', { name: 'Add to cart' }).click();\n  await expect(page.getByTestId('cart-badge')).toHaveText('1');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_add_bike_light(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n    page.get_by_test_id(\"product\").filter(has_text=\"Bike Light\").get_by_role(\"button\", name=\"Add to cart\").click()\n    expect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"1\")\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('add bike light', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.locator('#username').fill('standard_user');\n  await page.locator('#password').fill('secret_sauce');\n  await page.locator('form button').click();\n  await page.waitForTimeout(3000);\n  await page.locator('.products li:nth-child(2) button').click();\n  const badge = await page.locator('.badge').textContent();\n  expect(badge).toBe('1');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_add_bike_light(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.locator(\"#username\").fill(\"standard_user\")\n    page.locator(\"#password\").fill(\"secret_sauce\")\n    page.locator(\"form button\").click()\n    page.wait_for_timeout(3000)\n    page.locator(\".products li:nth-child(2) button\").click()\n    badge = page.locator(\".badge\").text_content()\n    assert badge == \"1\"\n"}, "legacyId": "fix-flaky"}}, "hooks": {"id": "hooks", "type": "lab", "plugin": "labs-web", "topic": "5.1", "title": "Share setup with hooks", "placement": "standalone", "minutes": 10, "brief": "Two tests need a logged-in user. Move the login into shared setup so each test only contains what it is about.", "tasks": ["JavaScript: put the login in `test.beforeEach` inside a `test.describe`. Python: an `autouse=True` fixture", "Test 1: add **Bike Light**; badge shows `1`", "Test 2: click **Log out**; assert the URL is `https://shop.test/`"], "hints": ["Each test still gets a fresh browser context — the hook runs before every test.", "pytest: `@pytest.fixture(autouse=True)` runs for every test in the file without being requested."], "checks": [{"label": "Uses shared setup", "type": "code", "args": [{"re": "test\\.beforeEach\\s*\\(", "flags": ""}, {"re": "@pytest\\.fixture\\(\\s*autouse\\s*=\\s*True\\s*\\)", "flags": ""}, "Uses shared setup"]}, {"label": "At least 2 passing tests", "type": "tests", "args": [2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest.describe('logged-in user', () => {\n  test.beforeEach(async ({ page }) => {\n    await page.goto('https://shop.test/');\n    await page.getByLabel('Username').fill('standard_user');\n    await page.getByLabel('Password').fill('secret_sauce');\n    await page.getByRole('button', { name: 'Log in' }).click();\n  });\n\n  test('can add an item', async ({ page }) => {\n    await page.getByTestId('product').filter({ hasText: 'Bike Light' })\n      .getByRole('button', { name: 'Add to cart' }).click();\n    await expect(page.getByTestId('cart-badge')).toHaveText('1');\n  });\n\n  test('can log out', async ({ page }) => {\n    await page.getByRole('button', { name: 'Log out' }).click();\n    await expect(page).toHaveURL('https://shop.test/');\n  });\n});\n", "py": "import pytest\nfrom playwright.sync_api import Page, expect\n\n\n@pytest.fixture(autouse=True)\ndef log_in(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n\n\ndef test_can_add_an_item(page: Page):\n    page.get_by_test_id(\"product\").filter(has_text=\"Bike Light\").get_by_role(\"button\", name=\"Add to cart\").click()\n    expect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"1\")\n\n\ndef test_can_log_out(page: Page):\n    page.get_by_role(\"button\", name=\"Log out\").click()\n    expect(page).to_have_url(\"https://shop.test/\")\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest.describe('logged-in user', () => {\n  // TODO: test.beforeEach(...) that logs in\n\n  test('can add an item', async ({ page }) => {\n\n  });\n\n  test('can log out', async ({ page }) => {\n\n  });\n});\n", "py": "import pytest\nfrom playwright.sync_api import Page, expect\n\n\n# TODO: an autouse fixture that logs in\n\n\ndef test_can_add_an_item(page: Page):\n    pass\n\n\ndef test_can_log_out(page: Page):\n    pass\n"}, "legacyId": "hooks"}}, "keyboard-mouse": {"id": "keyboard-mouse", "type": "lab", "plugin": "labs-web", "topic": "3.3", "title": "Keyboard and hover", "placement": "standalone", "minutes": 10, "brief": "Two short tests: build a todo list with the keyboard, then open a hover menu on the Playground.", "tasks": ["Test 1: add `Write tests`, `Run tests` and `Fix bugs`, each by pressing **Enter**", "Complete **Run tests** by checking its checkbox", "Assert the counter shows `2 items left`", "Test 2: on `https://play.test/hover`, hover **Account**, click **Settings**, assert heading `Settings`"], "hints": ["A loop keeps the three additions short.", "The menu items only exist on screen while the pointer is over the menu — `hover()` first."], "checks": [{"label": "Presses Enter three times", "type": "acted", "args": ["press", {"re": "Enter", "flags": ""}, "Presses Enter three times", 3]}, {"label": "Uses hover()", "type": "calls", "args": ["hover", "Uses hover()"]}, {"label": "At least 2 passing tests", "type": "tests", "args": [2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('build a todo list with the keyboard', async ({ page }) => {\n  await page.goto('https://todo.test/');\n  const input = page.getByPlaceholder('What needs to be done?');\n  for (const title of ['Write tests', 'Run tests', 'Fix bugs']) {\n    await input.fill(title);\n    await input.press('Enter');\n  }\n  await page.getByTestId('todo-item').filter({ hasText: 'Run tests' }).getByRole('checkbox').check();\n  await expect(page.getByTestId('todo-count')).toHaveText('2 items left');\n});\n\ntest('open the account menu by hovering', async ({ page }) => {\n  await page.goto('https://play.test/hover');\n  await page.getByRole('button', { name: 'Account' }).hover();\n  await page.getByRole('menuitem', { name: 'Settings' }).click();\n  await expect(page.getByRole('heading', { name: 'Settings' })).toBeVisible();\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_build_a_todo_list_with_the_keyboard(page: Page):\n    page.goto(\"https://todo.test/\")\n    new_todo = page.get_by_placeholder(\"What needs to be done?\")\n    for title in [\"Write tests\", \"Run tests\", \"Fix bugs\"]:\n        new_todo.fill(title)\n        new_todo.press(\"Enter\")\n    page.get_by_test_id(\"todo-item\").filter(has_text=\"Run tests\").get_by_role(\"checkbox\").check()\n    expect(page.get_by_test_id(\"todo-count\")).to_have_text(\"2 items left\")\n\n\ndef test_open_the_account_menu_by_hovering(page: Page):\n    page.goto(\"https://play.test/hover\")\n    page.get_by_role(\"button\", name=\"Account\").hover()\n    page.get_by_role(\"menuitem\", name=\"Settings\").click()\n    expect(page.get_by_role(\"heading\", name=\"Settings\")).to_be_visible()\n"}, "site": "https://todo.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('build a todo list with the keyboard', async ({ page }) => {\n  await page.goto('https://todo.test/');\n\n});\n\ntest('open the account menu by hovering', async ({ page }) => {\n  await page.goto('https://play.test/hover');\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_build_a_todo_list_with_the_keyboard(page: Page):\n    page.goto(\"https://todo.test/\")\n\n\ndef test_open_the_account_menu_by_hovering(page: Page):\n    page.goto(\"https://play.test/hover\")\n"}, "legacyId": "keyboard-mouse"}}, "mock-network": {"id": "mock-network", "type": "lab", "plugin": "labs-web", "topic": "6.1", "title": "Mock the network", "placement": "standalone", "minutes": 10, "brief": "The todo app loads its list from `GET /api/todos`. Control that response to test states that are hard to reach for real.", "tasks": ["Test 1: route `**/api/todos` and fulfill with 3 todos (one completed); assert 3 items and `2 items left`", "Test 2: abort the same request; assert the alert says `Could not load todos`", "Register the route **before** `goto()`"], "hints": ["`route.fulfill({ json })` sends a fake response; `route.abort()` simulates a network failure.", "The app fetches on page load, so the route must exist before `goto()`."], "checks": [{"label": "Fulfills a request", "type": "acted", "args": ["route.fulfill", null, "Fulfills a request"]}, {"label": "Aborts a request", "type": "acted", "args": ["route.abort", null, "Aborts a request"]}, {"label": "At least 2 passing tests", "type": "tests", "args": [2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('shows todos from the API', async ({ page }) => {\n  await page.route('**/api/todos', async route => {\n    await route.fulfill({ json: [\n      { title: 'Plan sprint', completed: false },\n      { title: 'Review PR', completed: true },\n      { title: 'Ship it', completed: false },\n    ] });\n  });\n  await page.goto('https://todo.test/');\n  await expect(page.getByTestId('todo-item')).toHaveCount(3);\n  await expect(page.getByTestId('todo-count')).toHaveText('2 items left');\n});\n\ntest('shows an error when the API fails', async ({ page }) => {\n  await page.route('**/api/todos', route => route.abort());\n  await page.goto('https://todo.test/');\n  await expect(page.getByRole('alert')).toHaveText('Could not load todos');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_shows_todos_from_the_api(page: Page):\n    page.route(\"**/api/todos\", lambda route: route.fulfill(json=[\n        {\"title\": \"Plan sprint\", \"completed\": False},\n        {\"title\": \"Review PR\", \"completed\": True},\n        {\"title\": \"Ship it\", \"completed\": False},\n    ]))\n    page.goto(\"https://todo.test/\")\n    expect(page.get_by_test_id(\"todo-item\")).to_have_count(3)\n    expect(page.get_by_test_id(\"todo-count\")).to_have_text(\"2 items left\")\n\n\ndef test_shows_an_error_when_the_api_fails(page: Page):\n    page.route(\"**/api/todos\", lambda route: route.abort())\n    page.goto(\"https://todo.test/\")\n    expect(page.get_by_role(\"alert\")).to_have_text(\"Could not load todos\")\n"}, "site": "https://todo.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('shows todos from the API', async ({ page }) => {\n  // TODO: page.route(...) then goto\n\n});\n\ntest('shows an error when the API fails', async ({ page }) => {\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_shows_todos_from_the_api(page: Page):\n    # TODO: page.route(...) then goto\n    pass\n\n\ndef test_shows_an_error_when_the_api_fails(page: Page):\n    pass\n"}, "legacyId": "mock-network"}}, "navigate-cart": {"id": "navigate-cart", "type": "lab", "plugin": "labs-web", "topic": "3.1", "title": "Navigate between pages", "placement": "standalone", "minutes": 10, "brief": "Move through the shop like a user: add an item, open the cart through the header link, and come back.", "tasks": ["Log in (lines provided)", "Add **Trail Backpack** to the cart", "Click the header link named **Cart** and assert the URL ends with `/cart`", "Assert the cart lists `Trail Backpack`", "Click **Continue shopping** and assert you are back on `/inventory`"], "hints": ["The cart link’s accessible name comes from `aria-label=\"Cart\"`.", "`toHaveURL` accepts a full string or a regular expression. Python: `re.compile(\".*/cart$\")`."], "checks": [{"label": "Clicks the Cart link", "type": "acted", "args": ["click", {"re": "link.*Cart", "flags": ""}, "Clicks the Cart link"]}, {"label": "Asserts the URL twice", "type": "asserted", "args": ["toHaveURL", "Asserts the URL twice", 2]}, {"label": "Visits the cart page", "type": "url", "args": [{"re": "\\/cart$", "flags": ""}, "Visits the cart page"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('cart round trip', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByLabel('Username').fill('standard_user');\n  await page.getByLabel('Password').fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n  await page.getByTestId('product').filter({ hasText: 'Trail Backpack' })\n    .getByRole('button', { name: 'Add to cart' }).click();\n  await page.getByRole('link', { name: 'Cart' }).click();\n  await expect(page).toHaveURL(/\\/cart$/);\n  await expect(page.getByTestId('cart-item')).toContainText('Trail Backpack');\n  await page.getByRole('link', { name: 'Continue shopping' }).click();\n  await expect(page).toHaveURL('https://shop.test/inventory');\n});\n", "py": "import re\nfrom playwright.sync_api import Page, expect\n\n\ndef test_cart_round_trip(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n    page.get_by_test_id(\"product\").filter(has_text=\"Trail Backpack\").get_by_role(\"button\", name=\"Add to cart\").click()\n    page.get_by_role(\"link\", name=\"Cart\").click()\n    expect(page).to_have_url(re.compile(\".*/cart$\"))\n    expect(page.get_by_test_id(\"cart-item\")).to_contain_text(\"Trail Backpack\")\n    page.get_by_role(\"link\", name=\"Continue shopping\").click()\n    expect(page).to_have_url(\"https://shop.test/inventory\")\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('cart round trip', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByLabel('Username').fill('standard_user');\n  await page.getByLabel('Password').fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_cart_round_trip(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n"}, "legacyId": "navigate-cart"}}, "page-object": {"id": "page-object", "type": "lab", "plugin": "labs-web", "topic": "5.3", "title": "Build a page object", "placement": "standalone", "minutes": 10, "brief": "Wrap the login screen in a `LoginPage` class so tests describe *what* they do, not *how*.", "tasks": ["Create class `LoginPage` with locators for username, password, button and error alert", "Add `goto()` and `login(username, password)` methods", "Test 1: valid login lands on `/inventory`", "Test 2: `locked_out_user` sees an error containing `locked out`"], "hints": ["Create locators in the constructor — they are lazy, so no page needs to be loaded yet.", "Keep assertions in the tests; keep the page object about actions and locators."], "checks": [{"label": "Defines LoginPage", "type": "code", "args": [{"re": "class\\s+LoginPage", "flags": ""}, {"re": "class\\s+LoginPage", "flags": ""}, "Defines LoginPage"]}, {"label": "Tests use the page object", "type": "code", "args": [{"re": "\\bnew\\s+LoginPage\\s*\\(", "flags": ""}, {"re": "LoginPage\\(\\s*page\\s*\\)", "flags": ""}, "Tests use the page object"]}, {"label": "At least 2 passing tests", "type": "tests", "args": [2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\nclass LoginPage {\n  constructor(page) {\n    this.page = page;\n    this.username = page.getByLabel('Username');\n    this.password = page.getByLabel('Password');\n    this.submit = page.getByRole('button', { name: 'Log in' });\n    this.error = page.getByRole('alert');\n  }\n  async goto() {\n    await this.page.goto('https://shop.test/');\n  }\n  async login(username, password) {\n    await this.username.fill(username);\n    await this.password.fill(password);\n    await this.submit.click();\n  }\n}\n\ntest('valid user can log in', async ({ page }) => {\n  const login = new LoginPage(page);\n  await login.goto();\n  await login.login('standard_user', 'secret_sauce');\n  await expect(page).toHaveURL(/inventory/);\n});\n\ntest('locked out user sees an error', async ({ page }) => {\n  const login = new LoginPage(page);\n  await login.goto();\n  await login.login('locked_out_user', 'secret_sauce');\n  await expect(login.error).toContainText('locked out');\n});\n", "py": "import re\nfrom playwright.sync_api import Page, expect\n\n\nclass LoginPage:\n    def __init__(self, page: Page):\n        self.page = page\n        self.username = page.get_by_label(\"Username\")\n        self.password = page.get_by_label(\"Password\")\n        self.submit = page.get_by_role(\"button\", name=\"Log in\")\n        self.error = page.get_by_role(\"alert\")\n\n    def goto(self):\n        self.page.goto(\"https://shop.test/\")\n\n    def login(self, username, password):\n        self.username.fill(username)\n        self.password.fill(password)\n        self.submit.click()\n\n\ndef test_valid_user_can_log_in(page: Page):\n    login = LoginPage(page)\n    login.goto()\n    login.login(\"standard_user\", \"secret_sauce\")\n    expect(page).to_have_url(re.compile(\"inventory\"))\n\n\ndef test_locked_out_user_sees_an_error(page: Page):\n    login = LoginPage(page)\n    login.goto()\n    login.login(\"locked_out_user\", \"secret_sauce\")\n    expect(login.error).to_contain_text(\"locked out\")\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\nclass LoginPage {\n  constructor(page) {\n    this.page = page;\n    // TODO: locators\n  }\n  // TODO: goto(), login(username, password)\n}\n\ntest('valid user can log in', async ({ page }) => {\n\n});\n\ntest('locked out user sees an error', async ({ page }) => {\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\nclass LoginPage:\n    def __init__(self, page: Page):\n        self.page = page\n        # TODO: locators\n\n    # TODO: goto(self), login(self, username, password)\n\n\ndef test_valid_user_can_log_in(page: Page):\n    pass\n\n\ndef test_locked_out_user_sees_an_error(page: Page):\n    pass\n"}, "legacyId": "page-object"}}, "playground": {"id": "playground", "type": "lab", "plugin": "labs-web", "topic": null, "title": "Playground", "placement": "standalone", "minutes": 0, "brief": "Free workspace. Nothing is checked.", "tasks": [], "hints": [], "checks": [], "payload": {"playground": true, "starter": {"js": "import { test, expect } from '@playwright/test';\n\n// Free practice. Sites: https://shop.test  https://todo.test  https://play.test  https://api.test\ntest('explore', async ({ page }) => {\n  await page.goto('https://play.test/');\n  await expect(page.getByRole('heading', { name: 'Playground' })).toBeVisible();\n  console.log(await page.getByRole('link').allTextContents());\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\n# Free practice. Sites: https://shop.test  https://todo.test  https://play.test  https://api.test\ndef test_explore(page: Page):\n    page.goto(\"https://play.test/\")\n    expect(page.get_by_role(\"heading\", name=\"Playground\")).to_be_visible()\n    print(page.get_by_role(\"link\").all_text_contents())\n"}}}, "role-login": {"id": "role-login", "type": "lab", "plugin": "labs-web", "topic": "2.1", "title": "Log in with role locators", "placement": "standalone", "minutes": 10, "brief": "Log in to Pocket Shop using **only role-based locators**. Inputs have the role `textbox`; the submit control is a `button`.", "tasks": ["Fill **Username** with `standard_user` using `getByRole('textbox', …)`", "Fill **Password** with `secret_sauce` (password fields are textboxes too)", "Click the **Log in** button", "Assert the **Products** heading is visible"], "hints": ["The accessible name of an input comes from its `<label>`.", "Python passes options as keyword arguments: `get_by_role(\"button\", name=\"Log in\")`."], "checks": [{"label": "Uses getByRole at least 4 times", "type": "calls", "args": ["getByRole", "Uses getByRole at least 4 times", 4]}, {"label": "Fills the username", "type": "acted", "args": ["fill", {"re": "standard_user", "flags": ""}, "Fills the username"]}, {"label": "Reaches the products page", "type": "url", "args": [{"re": "\\/inventory", "flags": ""}, "Reaches the products page"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('log in with role locators', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByRole('textbox', { name: 'Username' }).fill('standard_user');\n  await page.getByRole('textbox', { name: 'Password' }).fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n  await expect(page.getByRole('heading', { name: 'Products' })).toBeVisible();\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_log_in_with_role_locators(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_role(\"textbox\", name=\"Username\").fill(\"standard_user\")\n    page.get_by_role(\"textbox\", name=\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n    expect(page.get_by_role(\"heading\", name=\"Products\")).to_be_visible()\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('log in with role locators', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  // Use page.getByRole(...) for every element below\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_log_in_with_role_locators(page: Page):\n    page.goto(\"https://shop.test/\")\n    # Use page.get_by_role(...) for every element below\n"}, "legacyId": "role-login"}}, "signup-form": {"id": "signup-form", "type": "lab", "plugin": "labs-web", "topic": "3.2", "title": "Fill a complete form", "placement": "standalone", "minutes": 10, "brief": "Create an account on the Playground form. The **Create account** button stays disabled until the terms box is ticked.", "tasks": ["Fill **Full name** `Ayesha Malik`, **Email** `ayesha@example.com`, **Password** `supersecret`", "Choose **Pakistan** in the Country dropdown", "Choose the **Pro** plan radio button", "Tick **I agree to the terms** and click **Create account**", "Assert the status reads `Welcome, Ayesha! Your Pro plan is ready.`"], "hints": ["`selectOption` matches an option by value or by visible label.", "Use `check()` for radios and checkboxes — it does nothing if already checked.", "The success message appears after a short delay; web-first assertions wait for it."], "checks": [{"label": "Fills three fields", "type": "calls", "args": ["fill", "Fills three fields", 3]}, {"label": "Uses selectOption", "type": "calls", "args": ["selectOption", "Uses selectOption"]}, {"label": "Uses check() twice", "type": "calls", "args": ["check", "Uses check() twice", 2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('create an account', async ({ page }) => {\n  await page.goto('https://play.test/forms');\n  await page.getByLabel('Full name').fill('Ayesha Malik');\n  await page.getByLabel('Email').fill('ayesha@example.com');\n  await page.getByLabel('Password').fill('supersecret');\n  await page.getByLabel('Country').selectOption('Pakistan');\n  await page.getByRole('radio', { name: 'Pro' }).check();\n  await page.getByLabel('I agree to the terms').check();\n  await page.getByRole('button', { name: 'Create account' }).click();\n  await expect(page.getByRole('status')).toHaveText('Welcome, Ayesha! Your Pro plan is ready.');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_create_an_account(page: Page):\n    page.goto(\"https://play.test/forms\")\n    page.get_by_label(\"Full name\").fill(\"Ayesha Malik\")\n    page.get_by_label(\"Email\").fill(\"ayesha@example.com\")\n    page.get_by_label(\"Password\").fill(\"supersecret\")\n    page.get_by_label(\"Country\").select_option(\"Pakistan\")\n    page.get_by_role(\"radio\", name=\"Pro\").check()\n    page.get_by_label(\"I agree to the terms\").check()\n    page.get_by_role(\"button\", name=\"Create account\").click()\n    expect(page.get_by_role(\"status\")).to_have_text(\"Welcome, Ayesha! Your Pro plan is ready.\")\n"}, "site": "https://play.test/forms", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('create an account', async ({ page }) => {\n  await page.goto('https://play.test/forms');\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_create_an_account(page: Page):\n    page.goto(\"https://play.test/forms\")\n"}, "legacyId": "signup-form"}}, "sorted-list": {"id": "sorted-list", "type": "lab", "plugin": "labs-web", "topic": "4.1", "title": "Assert a whole list", "placement": "standalone", "minutes": 10, "brief": "Sort the products by price and verify the complete order in **one** web-first assertion.", "tasks": ["Log in (lines provided)", "Select **Price (low to high)** in the **Sort** dropdown", "Assert the product names (`h3` headings) are, in order: Baby Onesie, Bike Light, Graphic Tee, Trail Backpack, Rain Shell, Fleece Jacket", "Assert the first price shows `$7.99`"], "hints": ["`toHaveText([...])` with an array compares every matched element, in order.", "Headings can be filtered by level: `getByRole(\"heading\", { level: 3 })`."], "checks": [{"label": "Changes the sort order", "type": "calls", "args": ["selectOption", "Changes the sort order"]}, {"label": "Asserts an array of texts", "type": "match", "args": [{"code": {"re": "toHaveText\\(\\s*\\[|to_have_text\\(\\s*\\[", "flags": ""}, "asserted": "toHaveText"}]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('sort by price', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByLabel('Username').fill('standard_user');\n  await page.getByLabel('Password').fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n  await page.getByLabel('Sort').selectOption('Price (low to high)');\n  await expect(page.getByRole('heading', { level: 3 })).toHaveText([\n    'Baby Onesie', 'Bike Light', 'Graphic Tee', 'Trail Backpack', 'Rain Shell', 'Fleece Jacket'\n  ]);\n  await expect(page.locator('.price').first()).toHaveText('$7.99');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_sort_by_price(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n    page.get_by_label(\"Sort\").select_option(\"Price (low to high)\")\n    expect(page.get_by_role(\"heading\", level=3)).to_have_text([\n        \"Baby Onesie\", \"Bike Light\", \"Graphic Tee\", \"Trail Backpack\", \"Rain Shell\", \"Fleece Jacket\"\n    ])\n    expect(page.locator(\".price\").first).to_have_text(\"$7.99\")\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('sort by price', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByLabel('Username').fill('standard_user');\n  await page.getByLabel('Password').fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_sort_by_price(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n"}, "legacyId": "sorted-list"}}, "strict-lists": {"id": "strict-lists", "type": "lab", "plugin": "labs-web", "topic": "2.4", "title": "Strictness, counts and positions", "placement": "standalone", "minutes": 10, "brief": "Six products share the button name **Add to cart**, so a plain locator breaks strict mode. Count the products, then pick specific ones by position.", "tasks": ["Assert there are exactly **6** elements with test id `product`", "Add the **first** product to the cart with `.first()`", "Add the **last** product with `.last()`", "Assert the cart badge (test id `cart-badge`) shows `2`"], "hints": ["`toHaveCount(6)` works on a locator that matches many elements.", "In Python, `first` and `last` are **properties** (no brackets); `nth(i)` is a method."], "checks": [{"label": "Asserts the product count", "type": "asserted", "args": ["toHaveCount", "Asserts the product count"]}, {"label": "Uses first", "type": "calls", "args": ["first", "Uses first"]}, {"label": "Uses last", "type": "calls", "args": ["last", "Uses last"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('add first and last products', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByLabel('Username').fill('standard_user');\n  await page.getByLabel('Password').fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n  const products = page.getByTestId('product');\n  await expect(products).toHaveCount(6);\n  await products.first().getByRole('button', { name: 'Add to cart' }).click();\n  await products.last().getByRole('button', { name: 'Add to cart' }).click();\n  await expect(page.getByTestId('cart-badge')).toHaveText('2');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_add_first_and_last_products(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n    products = page.get_by_test_id(\"product\")\n    expect(products).to_have_count(6)\n    products.first.get_by_role(\"button\", name=\"Add to cart\").click()\n    products.last.get_by_role(\"button\", name=\"Add to cart\").click()\n    expect(page.get_by_test_id(\"cart-badge\")).to_have_text(\"2\")\n"}, "site": "https://shop.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('add first and last products', async ({ page }) => {\n  await page.goto('https://shop.test/');\n  await page.getByLabel('Username').fill('standard_user');\n  await page.getByLabel('Password').fill('secret_sauce');\n  await page.getByRole('button', { name: 'Log in' }).click();\n  const products = page.getByTestId('product');\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_add_first_and_last_products(page: Page):\n    page.goto(\"https://shop.test/\")\n    page.get_by_label(\"Username\").fill(\"standard_user\")\n    page.get_by_label(\"Password\").fill(\"secret_sauce\")\n    page.get_by_role(\"button\", name=\"Log in\").click()\n    products = page.get_by_test_id(\"product\")\n"}, "legacyId": "strict-lists"}}, "table-filter": {"id": "table-filter", "type": "lab", "plugin": "labs-web", "topic": "2.3", "title": "Chain and filter in a table", "placement": "standalone", "minutes": 10, "brief": "Every row has an **Edit** button with the same name. Narrow the search to Chen Wei’s row first, then find the button inside it.", "tasks": ["Open `https://play.test/table`", "Find the **row** that contains `Chen Wei` with `filter({ hasText })`", "Click the **Edit** button inside that row", "Assert the status says `Editing Chen Wei`"], "hints": ["`filter({ hasText: 'Chen Wei' })` keeps only rows containing that text.", "Chaining searches *inside* the previous result: `row.getByRole(...)`.", "Python keyword: `has_text=\"Chen Wei\"`."], "checks": [{"label": "Uses filter()", "type": "calls", "args": ["filter", "Uses filter()"]}, {"label": "Clicks an Edit button", "type": "acted", "args": ["click", {"re": "Edit", "flags": ""}, "Clicks an Edit button"]}, {"label": "Asserts the status text", "type": "asserted", "args": ["toHaveText", "Asserts the status text"]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('edit one team member', async ({ page }) => {\n  await page.goto('https://play.test/table');\n  const row = page.getByRole('row').filter({ hasText: 'Chen Wei' });\n  await row.getByRole('button', { name: 'Edit' }).click();\n  await expect(page.getByRole('status')).toHaveText('Editing Chen Wei');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_edit_one_team_member(page: Page):\n    page.goto(\"https://play.test/table\")\n    row = page.get_by_role(\"row\").filter(has_text=\"Chen Wei\")\n    row.get_by_role(\"button\", name=\"Edit\").click()\n    expect(page.get_by_role(\"status\")).to_have_text(\"Editing Chen Wei\")\n"}, "site": "https://play.test/table", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('edit one team member', async ({ page }) => {\n  await page.goto('https://play.test/table');\n  // Hint: page.getByRole('row').filter(...).getByRole(...)\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_edit_one_team_member(page: Page):\n    page.goto(\"https://play.test/table\")\n    # Hint: page.get_by_role(\"row\").filter(...).get_by_role(...)\n"}, "legacyId": "table-filter"}}, "timeouts": {"id": "timeouts", "type": "lab", "plugin": "labs-web", "topic": "4.3", "title": "Timeouts and negative assertions", "placement": "standalone", "minutes": 10, "brief": "The report takes **8 seconds** — longer than the default 5 s assertion timeout. Raise the timeout for that one assertion only. Then check something *disappears*.", "tasks": ["Test 1: click **Generate report**; assert status `Report ready` with a **10 000 ms** timeout", "Test 2: click **Start**; assert `Loading…` is hidden again and `Hello World!` is visible"], "hints": ["Every assertion accepts `{ timeout: ms }` — Python: `timeout=10_000`.", "`toBeHidden()` (or `not.toBeVisible()`) waits for an element to disappear."], "checks": [{"label": "Raises one assertion timeout", "type": "code", "args": [{"re": "timeout\\s*:\\s*1\\d[_\\d]{3,}", "flags": ""}, {"re": "timeout\\s*=\\s*1\\d[_\\d]{3,}", "flags": ""}, "Raises one assertion timeout"]}, {"label": "Asserts disappearance", "type": "asserted", "args": [["toBeHidden", "toBeVisible"], "Asserts disappearance", 2]}, {"label": "At least 2 passing tests", "type": "tests", "args": [2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('slow report', async ({ page }) => {\n  await page.goto('https://play.test/dynamic');\n  await page.getByRole('button', { name: 'Generate report' }).click();\n  await expect(page.getByRole('status')).toHaveText('Report ready', { timeout: 10_000 });\n});\n\ntest('loading indicator goes away', async ({ page }) => {\n  await page.goto('https://play.test/dynamic');\n  await page.getByRole('button', { name: 'Start' }).click();\n  await expect(page.getByText('Loading…')).toBeHidden();\n  await expect(page.getByText('Hello World!')).toBeVisible();\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_slow_report(page: Page):\n    page.goto(\"https://play.test/dynamic\")\n    page.get_by_role(\"button\", name=\"Generate report\").click()\n    expect(page.get_by_role(\"status\")).to_have_text(\"Report ready\", timeout=10_000)\n\n\ndef test_loading_indicator_goes_away(page: Page):\n    page.goto(\"https://play.test/dynamic\")\n    page.get_by_role(\"button\", name=\"Start\").click()\n    expect(page.get_by_text(\"Loading…\")).to_be_hidden()\n    expect(page.get_by_text(\"Hello World!\")).to_be_visible()\n"}, "site": "https://play.test/dynamic", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('slow report', async ({ page }) => {\n  await page.goto('https://play.test/dynamic');\n  await page.getByRole('button', { name: 'Generate report' }).click();\n  await expect(page.getByRole('status')).toHaveText('Report ready'); // fails: 5 s default\n});\n\ntest('loading indicator goes away', async ({ page }) => {\n  await page.goto('https://play.test/dynamic');\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_slow_report(page: Page):\n    page.goto(\"https://play.test/dynamic\")\n    page.get_by_role(\"button\", name=\"Generate report\").click()\n    expect(page.get_by_role(\"status\")).to_have_text(\"Report ready\")  # fails: 5 s default\n\n\ndef test_loading_indicator_goes_away(page: Page):\n    page.goto(\"https://play.test/dynamic\")\n"}, "legacyId": "timeouts"}}, "todo-locators": {"id": "todo-locators", "type": "lab", "plugin": "labs-web", "topic": "2.2", "title": "Placeholder and test id locators", "placement": "standalone", "minutes": 10, "brief": "The todo input has no label, only a placeholder. Add a todo and verify it using **test ids**.", "tasks": ["Find the input with `getByPlaceholder('What needs to be done?')`", "Type `Buy milk` and press **Enter**", "Assert `getByTestId('todo-item')` has the text `Buy milk`", "Assert `getByTestId('todo-count')` has the text `1 item left`"], "hints": ["Store a locator in a variable and reuse it — locators are lazy.", "`press(\"Enter\")` submits the todo.", "Python: `get_by_test_id`, `to_have_text`."], "checks": [{"label": "Uses getByPlaceholder", "type": "calls", "args": ["getByPlaceholder", "Uses getByPlaceholder"]}, {"label": "Uses getByTestId", "type": "calls", "args": ["getByTestId", "Uses getByTestId", 2]}, {"label": "Presses Enter", "type": "acted", "args": ["press", {"re": "Enter", "flags": ""}, "Presses Enter"]}, {"label": "Asserts both texts", "type": "asserted", "args": ["toHaveText", "Asserts both texts", 2]}, {"label": "All tests pass", "type": "pass", "args": []}], "payload": {"solution": {"js": "import { test, expect } from '@playwright/test';\n\ntest('add a todo', async ({ page }) => {\n  await page.goto('https://todo.test/');\n  const input = page.getByPlaceholder('What needs to be done?');\n  await input.fill('Buy milk');\n  await input.press('Enter');\n  await expect(page.getByTestId('todo-item')).toHaveText('Buy milk');\n  await expect(page.getByTestId('todo-count')).toHaveText('1 item left');\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_add_a_todo(page: Page):\n    page.goto(\"https://todo.test/\")\n    new_todo = page.get_by_placeholder(\"What needs to be done?\")\n    new_todo.fill(\"Buy milk\")\n    new_todo.press(\"Enter\")\n    expect(page.get_by_test_id(\"todo-item\")).to_have_text(\"Buy milk\")\n    expect(page.get_by_test_id(\"todo-count\")).to_have_text(\"1 item left\")\n"}, "site": "https://todo.test/", "starter": {"js": "import { test, expect } from '@playwright/test';\n\ntest('add a todo', async ({ page }) => {\n  await page.goto('https://todo.test/');\n\n});\n", "py": "from playwright.sync_api import Page, expect\n\n\ndef test_add_a_todo(page: Page):\n    page.goto(\"https://todo.test/\")\n"}, "legacyId": "todo-locators"}}}, "retired": [], "renames": {}, "interview": []});
